-- ═══════════ DDL_GANADERO.SQL ═══════════
-- DDL DE LA BASE DE DATOS DE NEGOCIO DE GANADERO (FINCAS DE DOBLE PROPOSITO QUE FUNCIONAN SIN INTERNET) ------------------------------------------
-- ESTADOS EN MAYUSCULAS Y SIN TILDES NI Ñ: SI / NO, ACTIVO / ANULADO, DUENIO, PRENIADA, MANANA
-- EL LOGIN (CORREO Y CLAVE) VIVE EN LA BASE DE SEGURIDAD (seguridadganadero). AQUI SOLO SE GUARDA EL id_usuario DE SEGURIDAD (SIN FK: SON BASES DISTINTAS)
-- VALORES EN PESOS COLOMBIANOS ENTEROS: NUMERIC(12,0). PESOS EN KG CON UN DECIMAL: NUMERIC(6,1)
--
-- LO NUEVO POR EL MODO SIN CONEXION:
--   * TODA TABLA QUE SE LLENA DESDE EL CELULAR LLEVA UUID_X (LO GENERA EL CELULAR). REINTENTAR LA SINCRONIZACION NUNCA DUPLICA
--   * TODO EVENTO LLEVA FECHA_EVENTO (CUANDO PASO EN EL POTRERO) Y FECHA_CREACION (CUANDO LLEGO AL SERVIDOR)
--   * NO SE BORRA: SE ANULA (ESTADO_X = 'ANULADO'). EL TRIGGER TRG_NO_BORRAR_* LO IMPIDE
--   * FECHA_MODIFICACION LA PONE EL TRIGGER TRG_PROTEGER_* EN CADA INSERT Y UPDATE: ES LA MARCA CON LA QUE EL CELULAR BAJA LOS CAMBIOS
--   * TODO CAMBIO QUEDA EN TAB_AUDITORIAS (TRIGGER TRG_AUDITORIA_*). VER FUNCIONES/FUN_AUDITORIA


-- DROP DE TABLAS SI EXISTEN --------------------------------------------------------------------------------------------------------------------------
-- DROP DE TABLAS DEPENDIENTES --------------------------------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS TAB_SALIDAS;
DROP TABLE IF EXISTS TAB_ORDENOS;
DROP TABLE IF EXISTS TAB_PARTOS;
DROP TABLE IF EXISTS TAB_PALPACIONES;
DROP TABLE IF EXISTS TAB_SERVICIOS;
DROP TABLE IF EXISTS TAB_VACUNACIONES;
DROP TABLE IF EXISTS TAB_PESAJES;
DROP TABLE IF EXISTS TAB_MENSAJES_WHATSAPP;
DROP TABLE IF EXISTS TAB_MOVIMIENTOS;
DROP TABLE IF EXISTS TAB_OCUPACIONES;
DROP TABLE IF EXISTS TAB_POTREROS;
DROP TABLE IF EXISTS TAB_ANIMALES;
DROP TABLE IF EXISTS TAB_LOTES;
DROP TABLE IF EXISTS TAB_SINCRONIZACIONES;
DROP TABLE IF EXISTS TAB_FINCAS_PERSONAS;
DROP TABLE IF EXISTS TAB_CICLOS_ICA;


-- DROP DE TABLAS INDEPENDIENTES --------------------------------------------------------------------------------------------------------------------------
DROP TABLE IF EXISTS TAB_AUDITORIAS;
DROP TABLE IF EXISTS TAB_VACUNAS;
DROP TABLE IF EXISTS TAB_RAZAS;
DROP TABLE IF EXISTS TAB_CONFIGURACION;
DROP TABLE IF EXISTS TAB_FINCAS;

--DROP DE FUNCIONES----------------------------------------------------------------------------------------------------------------
DROP FUNCTION IF EXISTS funcion_Retorna_ultmoid;




-- CREACION DE TABLAS INDEPENDIENTES --------------------------------------------------------------------------------------------------------------------------

-- TABLA DE FINCAS
-- REGISTRO_ICA_FINCA: REGISTRO DEL PREDIO ANTE EL ICA (OPCIONAL)
-- HIERRO_FINCA: DESCRIPCION O CODIGO DEL HIERRO CON QUE SE MARCA EL GANADO (OPCIONAL)
-- ESTADO_FINCA: ACTIVO / INACTIVO
CREATE TABLE IF NOT EXISTS TAB_FINCAS
(
    ID_FINCA INTEGER NOT NULL,
    NOM_FINCA VARCHAR(100) NOT NULL,
    MUNICIPIO_FINCA VARCHAR(80) NOT NULL,
    VEREDA_FINCA VARCHAR(80),
    REGISTRO_ICA_FINCA VARCHAR(30),
    HIERRO_FINCA VARCHAR(60),
    ESTADO_FINCA VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_FINCA),
    CONSTRAINT CK_ESTADO_FINCA CHECK (ESTADO_FINCA IN ('ACTIVO', 'INACTIVO'))
);

-- TABLA DE CONFIGURACION GENERAL (PARES NOMBRE / VALOR QUE EDITA EL ADMINISTRADOR)
-- VALOR_ORIGINAL_CONFIGURACION: EL VALOR DE FABRICA
CREATE TABLE IF NOT EXISTS TAB_CONFIGURACION
(
    ID_CONFIGURACION INTEGER NOT NULL,
    NOM_CONFIGURACION VARCHAR(80) NOT NULL UNIQUE,
    VALOR_CONFIGURACION VARCHAR NOT NULL DEFAULT '',
    VALOR_ORIGINAL_CONFIGURACION VARCHAR NOT NULL DEFAULT '',
    DESCRIPCION_CONFIGURACION VARCHAR,
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_CONFIGURACION)
);

-- CATALOGO GLOBAL DE RAZAS (LO MANTIENE EL ADMINISTRADOR; SE BAJA AL CELULAR)
CREATE TABLE IF NOT EXISTS TAB_RAZAS
(
    ID_RAZA INTEGER NOT NULL,
    NOM_RAZA VARCHAR(60) NOT NULL UNIQUE,
    ESTADO_RAZA VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_RAZA),
    CONSTRAINT CK_ESTADO_RAZA CHECK (ESTADO_RAZA IN ('ACTIVO', 'INACTIVO'))
);

-- CATALOGO GLOBAL DE VACUNAS, TRATAMIENTOS Y DESPARASITANTES (DECISION 27/10/2026: GLOBAL, LO MANTIENE EL ADMINISTRADOR)
-- DIAS_REFUERZO: CADA CUANTO SE REPITE (NULL = DOSIS UNICA). CON ESTO SE CALCULA LA PROXIMA DOSIS
-- DIAS_RETIRO_LECHE: DIAS QUE NO SE PUEDE VENDER LA LECHE DESPUES DE APLICARLO (SEGUN LA ETIQUETA DEL PRODUCTO)
-- OBLIGATORIA_ICA: SI = ENTRA EN LOS CICLOS DEL ICA (AFTOSA, BRUCELOSIS)
CREATE TABLE IF NOT EXISTS TAB_VACUNAS
(
    ID_VACUNA INTEGER NOT NULL,
    NOM_VACUNA VARCHAR(80) NOT NULL UNIQUE,
    TIPO_VACUNA VARCHAR(15) NOT NULL,
    DIAS_REFUERZO INTEGER,
    DIAS_RETIRO_LECHE INTEGER NOT NULL DEFAULT 0,
    OBLIGATORIA_ICA VARCHAR(2) NOT NULL DEFAULT 'NO',
    ESTADO_VACUNA VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_VACUNA),
    CONSTRAINT CK_TIPO_VACUNA CHECK (TIPO_VACUNA IN ('VACUNA', 'TRATAMIENTO', 'DESPARASITANTE', 'VITAMINA')),
    CONSTRAINT CK_DIAS_REFUERZO CHECK (DIAS_REFUERZO IS NULL OR DIAS_REFUERZO > 0),
    CONSTRAINT CK_DIAS_RETIRO_LECHE CHECK (DIAS_RETIRO_LECHE >= 0),
    CONSTRAINT CK_OBLIGATORIA_ICA CHECK (OBLIGATORIA_ICA IN ('SI', 'NO')),
    CONSTRAINT CK_ESTADO_VACUNA CHECK (ESTADO_VACUNA IN ('ACTIVO', 'INACTIVO'))
);

-- TABLA DE AUDITORIA: LA LLENAN SOLO LOS TRIGGERS TRG_AUDITORIA_* (NINGUNA FUNCION ESCRIBE AQUI)
-- EXCEPCION A LA REGLA DEL ID CON funcion_Retorna_ultmoid: SE ESCRIBE EN CADA CAMBIO DE CUALQUIER TABLA; CON EL CANDADO DE ultmoid
-- TODAS LAS ESCRITURAS DE LA BASE QUEDARIAN EN FILA. POR ESO USA IDENTITY (EL ID SOLO ORDENA; NADIE LO PIDE DESDE AFUERA)
-- OPERACION_AUDITORIA: CREAR, EDITAR, ANULAR (EL ESTADO PASO A ANULADO), BORRAR (SOLO LIMPIEZAS DE PRUEBA)
-- CAMBIOS_AUDITORIA: EN EDITAR Y ANULAR, SOLO LAS COLUMNAS QUE CAMBIARON {"columna": {"ANTES": .., "DESPUES": ..}}
-- DATOS_AUDITORIA: EN CREAR, LA FILA NUEVA; EN BORRAR, LA FILA QUE SE BORRO
CREATE TABLE IF NOT EXISTS TAB_AUDITORIAS
(
    ID_AUDITORIA BIGINT GENERATED ALWAYS AS IDENTITY,
    NOM_TABLA_AUDITORIA VARCHAR(60) NOT NULL,
    OPERACION_AUDITORIA VARCHAR(10) NOT NULL,
    ID_REGISTRO_AUDITORIA INTEGER,
    UUID_REGISTRO_AUDITORIA UUID,
    ID_FINCA INTEGER,
    CAMBIOS_AUDITORIA JSONB,
    DATOS_AUDITORIA JSONB,
    USUARIO_AUDITORIA VARCHAR,
    FECHA_AUDITORIA TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (ID_AUDITORIA),
    CONSTRAINT CK_OPERACION_AUDITORIA CHECK (OPERACION_AUDITORIA IN ('CREAR', 'EDITAR', 'ANULAR', 'BORRAR'))
);
CREATE INDEX IF NOT EXISTS IX_AUDITORIAS_REGISTRO ON TAB_AUDITORIAS (NOM_TABLA_AUDITORIA, ID_REGISTRO_AUDITORIA);
CREATE INDEX IF NOT EXISTS IX_AUDITORIAS_FINCA_FECHA ON TAB_AUDITORIAS (ID_FINCA, FECHA_AUDITORIA);



-- CREACION DE TABLAS DEPENDIENTES -----------------------------------------------------------------------------------------------------------------------

-- CICLOS DE VACUNACION DEL ICA (CAMBIAN CADA AÑO; LOS CREA EL ADMINISTRADOR)
CREATE TABLE IF NOT EXISTS TAB_CICLOS_ICA
(
    ID_CICLO INTEGER NOT NULL,
    ID_VACUNA INTEGER NOT NULL REFERENCES TAB_VACUNAS(ID_VACUNA),
    NOM_CICLO VARCHAR(80) NOT NULL,
    FECHA_INICIO_CICLO DATE NOT NULL,
    FECHA_FIN_CICLO DATE NOT NULL,
    ESTADO_CICLO VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_CICLO),
    CONSTRAINT CK_FECHAS_CICLO CHECK (FECHA_FIN_CICLO >= FECHA_INICIO_CICLO),
    CONSTRAINT CK_ESTADO_CICLO CHECK (ESTADO_CICLO IN ('ACTIVO', 'ANULADO'))
);

-- QUIEN TRABAJA EN QUE FINCA Y CON QUE ROL
-- ID_USUARIO: EL id_usuario DE SEGURIDAD (SIN FK). ms-logica LO SACA DEL TOKEN Y SE LO PASA A CADA FUNCION
-- NOM_PERSONA: COPIA DEL NOMBRE PARA MOSTRARLO SIN IR A SEGURIDAD
-- ROL_FINCA: DUENIO (TODO EN SU FINCA), VAQUERO (REGISTRA, NO CORRIGE NI ANULA), VETERINARIO (REGISTRA SANIDAD Y REPRODUCCION, FASE 5)
--   DECISION 27/10/2026: UN ROL POR PERSONA EN SEGURIDAD; ROL_FINCA QUEDA LISTO POR SI ALGUIEN TRABAJA EN DOS FINCAS CON ROLES DISTINTOS
-- ESTADO_FINCA_PERSONA: ACTIVO / INACTIVO (YA NO TRABAJA AHI; NO VE LA FINCA)
CREATE TABLE IF NOT EXISTS TAB_FINCAS_PERSONAS
(
    ID_FINCA_PERSONA INTEGER NOT NULL,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_USUARIO VARCHAR(60) NOT NULL,
    NOM_PERSONA VARCHAR(150) NOT NULL,
    ROL_FINCA VARCHAR(12) NOT NULL,
    ESTADO_FINCA_PERSONA VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    RESUMEN_WHATSAPP_PERSONA VARCHAR(2) NOT NULL DEFAULT 'NO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_FINCA_PERSONA),
    CONSTRAINT UQ_FINCA_USUARIO UNIQUE (ID_FINCA, ID_USUARIO),
    CONSTRAINT CK_ROL_FINCA CHECK (ROL_FINCA IN ('DUENIO', 'VAQUERO', 'VETERINARIO')),
    CONSTRAINT CK_ESTADO_FINCA_PERSONA CHECK (ESTADO_FINCA_PERSONA IN ('ACTIVO', 'INACTIVO')),
    CONSTRAINT CK_RESUMEN_WHATSAPP_PERSONA CHECK (RESUMEN_WHATSAPP_PERSONA IN ('SI', 'NO'))
);
CREATE INDEX IF NOT EXISTS IX_FINCAS_PERSONAS_USUARIO ON TAB_FINCAS_PERSONAS (ID_USUARIO);

-- REGISTRO DE CADA SINCRONIZACION (PANTALLA "SINCRONIZACION" Y SOPORTE)
-- DETALLE_SINCRONIZACION: LOS RECHAZADOS CON SU MENSAJE
CREATE TABLE IF NOT EXISTS TAB_SINCRONIZACIONES
(
    ID_SINCRONIZACION INTEGER NOT NULL,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_USUARIO VARCHAR(60) NOT NULL,
    FECHA_SINCRONIZACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    RECIBIDOS_SINCRONIZACION INTEGER NOT NULL DEFAULT 0,
    GUARDADOS_SINCRONIZACION INTEGER NOT NULL DEFAULT 0,
    OMITIDOS_SINCRONIZACION INTEGER NOT NULL DEFAULT 0,
    RECHAZADOS_SINCRONIZACION INTEGER NOT NULL DEFAULT 0,
    DETALLE_SINCRONIZACION JSON,
    PRIMARY KEY (ID_SINCRONIZACION)
);
CREATE INDEX IF NOT EXISTS IX_SINCRONIZACIONES_FINCA ON TAB_SINCRONIZACIONES (ID_FINCA, FECHA_SINCRONIZACION);

-- LOTES DE LA FINCA (ORDEÑO, HORRAS, LEVANTE, CEBA...). SE PUEDEN CREAR SIN SEÑAL
CREATE TABLE IF NOT EXISTS TAB_LOTES
(
    ID_LOTE INTEGER NOT NULL,
    UUID_LOTE UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    NOM_LOTE VARCHAR(60) NOT NULL,
    ESTADO_LOTE VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_LOTE),
    CONSTRAINT CK_ESTADO_LOTE CHECK (ESTADO_LOTE IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_LOTES_SINCRONIZACION ON TAB_LOTES (ID_FINCA, FECHA_MODIFICACION);
CREATE UNIQUE INDEX IF NOT EXISTS UQ_LOTES_NOMBRE ON TAB_LOTES (ID_FINCA, LOWER(NOM_LOTE)) WHERE ESTADO_LOTE = 'ACTIVO';

-- ANIMALES DEL HATO. LA CATEGORIA (TERNERA, NOVILLA, VACA, TORO...) NO SE GUARDA: LA CALCULA FUN_CATEGORIA_ANIMAL
-- CHAPETA_ANIMAL: NUMERO DE LA CHAPETA, UNICO POR FINCA ENTRE LOS NO ANULADOS (PUEDE ESTAR VACIA: UNA CRIA AUN SIN CHAPETA)
-- SEXO_ANIMAL: H (HEMBRA) / M (MACHO)
-- FECHA_NACIMIENTO_ESTIMADA: SI = ANIMAL COMPRADO DEL QUE SOLO SE SABE LA EDAD APROXIMADA
-- ID_MADRE / ID_PADRE: ANIMALES DE LA MISMA FINCA. PADRE_EXTERNO: PAJILLA O TORO PRESTADO (TEXTO LIBRE)
-- ORIGEN_ANIMAL: NACIDO (EN LA FINCA) / COMPRADO. FECHA_INGRESO_ANIMAL: CUANDO LLEGO (COMPRADO) O NACIO
-- PESO_ACTUAL_KG Y FECHA_ULTIMO_PESAJE: LOS MANTIENE EL TRIGGER TRG_PESO_ACTUAL CON EL ULTIMO PESAJE ACTIVO
-- FECHA_SALIDA_ANIMAL Y LOS ESTADOS VENDIDO / MUERTO / TRASLADADO: LOS PONE EL TRIGGER TRG_SALIDA_ANIMAL
CREATE TABLE IF NOT EXISTS TAB_ANIMALES
(
    ID_ANIMAL INTEGER NOT NULL,
    UUID_ANIMAL UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_LOTE INTEGER REFERENCES TAB_LOTES(ID_LOTE),
    ID_RAZA INTEGER REFERENCES TAB_RAZAS(ID_RAZA),
    CHAPETA_ANIMAL VARCHAR(20),
    NOM_ANIMAL VARCHAR(60),
    SEXO_ANIMAL VARCHAR(1) NOT NULL,
    FECHA_NACIMIENTO DATE NOT NULL,
    FECHA_NACIMIENTO_ESTIMADA VARCHAR(2) NOT NULL DEFAULT 'NO',
    ID_MADRE INTEGER REFERENCES TAB_ANIMALES(ID_ANIMAL),
    ID_PADRE INTEGER REFERENCES TAB_ANIMALES(ID_ANIMAL),
    PADRE_EXTERNO VARCHAR(80),
    ORIGEN_ANIMAL VARCHAR(10) NOT NULL DEFAULT 'NACIDO',
    FECHA_INGRESO_ANIMAL DATE NOT NULL,
    FOTO_ANIMAL VARCHAR(200),
    PESO_ACTUAL_KG NUMERIC(6,1),
    FECHA_ULTIMO_PESAJE TIMESTAMP WITHOUT TIME ZONE,
    FECHA_SALIDA_ANIMAL TIMESTAMP WITHOUT TIME ZONE,
    ESTADO_ANIMAL VARCHAR(12) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_ANIMAL),
    CONSTRAINT CK_SEXO_ANIMAL CHECK (SEXO_ANIMAL IN ('H', 'M')),
    CONSTRAINT CK_FECHA_NACIMIENTO_ESTIMADA CHECK (FECHA_NACIMIENTO_ESTIMADA IN ('SI', 'NO')),
    CONSTRAINT CK_ORIGEN_ANIMAL CHECK (ORIGEN_ANIMAL IN ('NACIDO', 'COMPRADO')),
    CONSTRAINT CK_ESTADO_ANIMAL CHECK (ESTADO_ANIMAL IN ('ACTIVO', 'VENDIDO', 'MUERTO', 'TRASLADADO', 'ANULADO')),
    CONSTRAINT CK_MADRE_PADRE_ANIMAL CHECK (ID_MADRE IS DISTINCT FROM ID_ANIMAL AND ID_PADRE IS DISTINCT FROM ID_ANIMAL)
);
CREATE INDEX IF NOT EXISTS IX_ANIMALES_SINCRONIZACION ON TAB_ANIMALES (ID_FINCA, FECHA_MODIFICACION);
CREATE UNIQUE INDEX IF NOT EXISTS UQ_ANIMALES_CHAPETA ON TAB_ANIMALES (ID_FINCA, CHAPETA_ANIMAL) WHERE CHAPETA_ANIMAL IS NOT NULL AND ESTADO_ANIMAL <> 'ANULADO';
CREATE INDEX IF NOT EXISTS IX_ANIMALES_MADRE ON TAB_ANIMALES (ID_MADRE);



-- TABLAS DE EVENTOS (LA LINEA DE TIEMPO DEL ANIMAL) -------------------------------------------------------------------------------------------------
-- TODAS COMPARTEN: UUID_X, ID_FINCA (REPETIDO A PROPOSITO PARA SINCRONIZAR CON INDICE), ID_ANIMAL, FECHA_EVENTO, OBSERVACION_X, ESTADO_X (ACTIVO / ANULADO)
-- Y EL BLOQUE DE AUDITORIA. ANULAR SACA EL EVENTO DE LA LINEA DE TIEMPO Y DE LOS CALCULOS

-- PESAJES. ESTIMADO_CINTA = SI: EL PESO SE CALCULO CON EL PERIMETRO TORACICO (FUN_PESO_POR_CINTA)
CREATE TABLE IF NOT EXISTS TAB_PESAJES
(
    ID_PESAJE INTEGER NOT NULL,
    UUID_PESAJE UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    PESO_KG NUMERIC(6,1) NOT NULL,
    ESTIMADO_CINTA VARCHAR(2) NOT NULL DEFAULT 'NO',
    PERIMETRO_CM NUMERIC(5,1),
    OBSERVACION_PESAJE VARCHAR(300),
    ESTADO_PESAJE VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_PESAJE),
    CONSTRAINT CK_PESO_KG CHECK (PESO_KG > 0 AND PESO_KG <= 1500),
    CONSTRAINT CK_ESTIMADO_CINTA CHECK (ESTIMADO_CINTA IN ('SI', 'NO')),
    CONSTRAINT CK_PERIMETRO_CINTA CHECK (ESTIMADO_CINTA = 'NO' OR PERIMETRO_CM IS NOT NULL),
    CONSTRAINT CK_ESTADO_PESAJE CHECK (ESTADO_PESAJE IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_PESAJES_SINCRONIZACION ON TAB_PESAJES (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_PESAJES_ANIMAL ON TAB_PESAJES (ID_ANIMAL, FECHA_EVENTO);

-- VACUNACIONES Y TRATAMIENTOS. LAS FECHAS DE PROXIMA DOSIS Y FIN DEL RETIRO DE LECHE SE CALCULAN CON EL CATALOGO AL GUARDAR
CREATE TABLE IF NOT EXISTS TAB_VACUNACIONES
(
    ID_VACUNACION INTEGER NOT NULL,
    UUID_VACUNACION UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    ID_VACUNA INTEGER NOT NULL REFERENCES TAB_VACUNAS(ID_VACUNA),
    DOSIS_VACUNACION VARCHAR(40),
    FECHA_PROXIMA_DOSIS DATE,
    FECHA_FIN_RETIRO DATE,
    OBSERVACION_VACUNACION VARCHAR(300),
    ESTADO_VACUNACION VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_VACUNACION),
    CONSTRAINT CK_ESTADO_VACUNACION CHECK (ESTADO_VACUNACION IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_VACUNACIONES_SINCRONIZACION ON TAB_VACUNACIONES (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_VACUNACIONES_ANIMAL ON TAB_VACUNACIONES (ID_ANIMAL, FECHA_EVENTO);

-- SERVICIOS: MONTA (CON UN TORO DE LA FINCA O UNO DE AFUERA) O INSEMINACION (PAJILLA EN TORO_EXTERNO)
CREATE TABLE IF NOT EXISTS TAB_SERVICIOS
(
    ID_SERVICIO INTEGER NOT NULL,
    UUID_SERVICIO UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    TIPO_SERVICIO VARCHAR(12) NOT NULL,
    ID_TORO INTEGER REFERENCES TAB_ANIMALES(ID_ANIMAL),
    TORO_EXTERNO VARCHAR(80),
    OBSERVACION_SERVICIO VARCHAR(300),
    ESTADO_SERVICIO VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_SERVICIO),
    CONSTRAINT CK_TIPO_SERVICIO CHECK (TIPO_SERVICIO IN ('MONTA', 'INSEMINACION')),
    CONSTRAINT CK_ESTADO_SERVICIO CHECK (ESTADO_SERVICIO IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_SERVICIOS_SINCRONIZACION ON TAB_SERVICIOS (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_SERVICIOS_ANIMAL ON TAB_SERVICIOS (ID_ANIMAL, FECHA_EVENTO);

-- PALPACIONES. ID_SERVICIO: EL ULTIMO SERVICIO ACTIVO ANTES DE LA PALPACION (LO BUSCA LA FUNCION)
CREATE TABLE IF NOT EXISTS TAB_PALPACIONES
(
    ID_PALPACION INTEGER NOT NULL,
    UUID_PALPACION UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    ID_SERVICIO INTEGER REFERENCES TAB_SERVICIOS(ID_SERVICIO),
    RESULTADO_PALPACION VARCHAR(10) NOT NULL,
    MESES_GESTACION INTEGER,
    OBSERVACION_PALPACION VARCHAR(300),
    ESTADO_PALPACION VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_PALPACION),
    CONSTRAINT CK_RESULTADO_PALPACION CHECK (RESULTADO_PALPACION IN ('PRENIADA', 'VACIA')),
    CONSTRAINT CK_MESES_GESTACION CHECK ((RESULTADO_PALPACION = 'VACIA' AND MESES_GESTACION IS NULL) OR (RESULTADO_PALPACION = 'PRENIADA' AND MESES_GESTACION BETWEEN 1 AND 9)),
    CONSTRAINT CK_ESTADO_PALPACION CHECK (ESTADO_PALPACION IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_PALPACIONES_SINCRONIZACION ON TAB_PALPACIONES (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_PALPACIONES_ANIMAL ON TAB_PALPACIONES (ID_ANIMAL, FECHA_EVENTO);

-- PARTOS. LA CRIA VIVA SE CREA COMO ANIMAL EN LA MISMA TRANSACCION (ID_CRIA). ABORTO O CRIA MUERTA: SIN ID_CRIA
CREATE TABLE IF NOT EXISTS TAB_PARTOS
(
    ID_PARTO INTEGER NOT NULL,
    UUID_PARTO UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    TIPO_PARTO VARCHAR(10) NOT NULL,
    CRIA_VIVA VARCHAR(2) NOT NULL,
    SEXO_CRIA VARCHAR(1),
    ID_CRIA INTEGER UNIQUE REFERENCES TAB_ANIMALES(ID_ANIMAL),
    OBSERVACION_PARTO VARCHAR(300),
    ESTADO_PARTO VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_PARTO),
    CONSTRAINT CK_TIPO_PARTO CHECK (TIPO_PARTO IN ('NORMAL', 'ASISTIDO', 'CESAREA', 'ABORTO')),
    CONSTRAINT CK_CRIA_VIVA CHECK (CRIA_VIVA IN ('SI', 'NO')),
    CONSTRAINT CK_SEXO_CRIA CHECK (SEXO_CRIA IS NULL OR SEXO_CRIA IN ('H', 'M')),
    CONSTRAINT CK_CRIA_PARTO CHECK (CRIA_VIVA = 'NO' OR ID_CRIA IS NOT NULL),
    CONSTRAINT CK_ESTADO_PARTO CHECK (ESTADO_PARTO IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_PARTOS_SINCRONIZACION ON TAB_PARTOS (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_PARTOS_ANIMAL ON TAB_PARTOS (ID_ANIMAL, FECHA_EVENTO);

-- ORDEÑOS POR JORNADA (DECISION 27/10/2026: MAÑANA Y TARDE; EL TOTAL DEL DIA SE CALCULA)
-- UNA SOLA JORNADA ACTIVA POR VACA Y DIA: SI DOS CELULARES ORDEÑAN LA MISMA VACA, EL SEGUNDO SE RECHAZA
CREATE TABLE IF NOT EXISTS TAB_ORDENOS
(
    ID_ORDENO INTEGER NOT NULL,
    UUID_ORDENO UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    JORNADA_ORDENO VARCHAR(6) NOT NULL,
    LITROS_ORDENO NUMERIC(5,1) NOT NULL,
    OBSERVACION_ORDENO VARCHAR(300),
    ESTADO_ORDENO VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_ORDENO),
    CONSTRAINT CK_JORNADA_ORDENO CHECK (JORNADA_ORDENO IN ('MANANA', 'TARDE')),
    CONSTRAINT CK_LITROS_ORDENO CHECK (LITROS_ORDENO >= 0 AND LITROS_ORDENO <= 60),
    CONSTRAINT CK_ESTADO_ORDENO CHECK (ESTADO_ORDENO IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_ORDENOS_SINCRONIZACION ON TAB_ORDENOS (ID_FINCA, FECHA_MODIFICACION);
CREATE UNIQUE INDEX IF NOT EXISTS UQ_ORDENOS_JORNADA ON TAB_ORDENOS (ID_ANIMAL, (FECHA_EVENTO::DATE), JORNADA_ORDENO) WHERE ESTADO_ORDENO = 'ACTIVO';

-- SALIDAS DEL HATO: VENTA, MUERTE O TRASLADO. UNA SOLA SALIDA ACTIVA POR ANIMAL
-- AL GUARDARLA, EL TRIGGER TRG_SALIDA_ANIMAL CAMBIA EL ESTADO DEL ANIMAL; AL ANULARLA LO DEVUELVE A ACTIVO
CREATE TABLE IF NOT EXISTS TAB_SALIDAS
(
    ID_SALIDA INTEGER NOT NULL,
    UUID_SALIDA UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_ANIMAL INTEGER NOT NULL REFERENCES TAB_ANIMALES(ID_ANIMAL),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    TIPO_SALIDA VARCHAR(10) NOT NULL,
    VALOR_SALIDA NUMERIC(12,0),
    PESO_SALIDA_KG NUMERIC(6,1),
    CAUSA_SALIDA VARCHAR(200),
    OBSERVACION_SALIDA VARCHAR(300),
    ESTADO_SALIDA VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_SALIDA),
    CONSTRAINT CK_TIPO_SALIDA CHECK (TIPO_SALIDA IN ('VENTA', 'MUERTE', 'TRASLADO')),
    CONSTRAINT CK_VALOR_SALIDA CHECK (VALOR_SALIDA IS NULL OR VALOR_SALIDA >= 0),
    CONSTRAINT CK_ESTADO_SALIDA CHECK (ESTADO_SALIDA IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_SALIDAS_SINCRONIZACION ON TAB_SALIDAS (ID_FINCA, FECHA_MODIFICACION);
CREATE UNIQUE INDEX IF NOT EXISTS UQ_SALIDAS_ANIMAL ON TAB_SALIDAS (ID_ANIMAL) WHERE ESTADO_SALIDA = 'ACTIVO';

-- POTREROS DE LA FINCA (FASE 5A). SE CREAN SIN SEÑAL COMO LOS LOTES (UUID DEL CELULAR)
-- AREA_POTRERO: HECTAREAS (OPCIONAL). DIAS_DESCANSO_POTRERO: LOS DIAS QUE DEBE DESCANSAR ANTES DE VOLVER A METER UN LOTE
-- CONTORNO_POTRERO: OPCIONAL, LOS PUNTOS DEL CONTORNO DIBUJADO EN EL MAPA CUANDO HAY SEÑAL: [[LATITUD, LONGITUD], ...]
CREATE TABLE IF NOT EXISTS TAB_POTREROS
(
    ID_POTRERO INTEGER NOT NULL,
    UUID_POTRERO UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    NOM_POTRERO VARCHAR(60) NOT NULL,
    AREA_POTRERO NUMERIC(7,2),
    DIAS_DESCANSO_POTRERO INTEGER NOT NULL DEFAULT 30,
    CONTORNO_POTRERO JSON,
    ESTADO_POTRERO VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_POTRERO),
    CONSTRAINT CK_AREA_POTRERO CHECK (AREA_POTRERO IS NULL OR AREA_POTRERO > 0),
    CONSTRAINT CK_DIAS_DESCANSO_POTRERO CHECK (DIAS_DESCANSO_POTRERO BETWEEN 1 AND 365),
    CONSTRAINT CK_ESTADO_POTRERO CHECK (ESTADO_POTRERO IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_POTREROS_SINCRONIZACION ON TAB_POTREROS (ID_FINCA, FECHA_MODIFICACION);
CREATE UNIQUE INDEX IF NOT EXISTS UQ_POTREROS_NOMBRE ON TAB_POTREROS (ID_FINCA, LOWER(NOM_POTRERO)) WHERE ESTADO_POTRERO = 'ACTIVO';

-- OCUPACIONES: CUANDO UN LOTE ENTRO A UN POTRERO (FECHA_EVENTO) Y CUANDO SALIO (FECHA_SALIDA_OCUPACION, NULL = SIGUE AHI)
-- UN LOTE ESTA EN UN SOLO POTRERO A LA VEZ: AL ENTRAR A OTRO, LA OCUPACION ANTERIOR SE CIERRA CON ESA MISMA FECHA
-- EN UN POTRERO PUEDE HABER VARIOS LOTES. LOS DIAS DE DESCANSO SE CUENTAN DESDE QUE SALIO EL ULTIMO LOTE
CREATE TABLE IF NOT EXISTS TAB_OCUPACIONES
(
    ID_OCUPACION INTEGER NOT NULL,
    UUID_OCUPACION UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_POTRERO INTEGER NOT NULL REFERENCES TAB_POTREROS(ID_POTRERO),
    ID_LOTE INTEGER NOT NULL REFERENCES TAB_LOTES(ID_LOTE),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    FECHA_SALIDA_OCUPACION TIMESTAMP WITHOUT TIME ZONE,
    OBSERVACION_OCUPACION VARCHAR(300),
    ESTADO_OCUPACION VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_OCUPACION),
    CONSTRAINT CK_SALIDA_OCUPACION CHECK (FECHA_SALIDA_OCUPACION IS NULL OR FECHA_SALIDA_OCUPACION >= FECHA_EVENTO),
    CONSTRAINT CK_ESTADO_OCUPACION CHECK (ESTADO_OCUPACION IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_OCUPACIONES_SINCRONIZACION ON TAB_OCUPACIONES (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_OCUPACIONES_POTRERO ON TAB_OCUPACIONES (ID_POTRERO, FECHA_EVENTO);
CREATE UNIQUE INDEX IF NOT EXISTS UQ_OCUPACIONES_LOTE_ABIERTA ON TAB_OCUPACIONES (ID_LOTE) WHERE FECHA_SALIDA_OCUPACION IS NULL AND ESTADO_OCUPACION = 'ACTIVO';

-- PLATA DE LA FINCA (FASE 5B): INGRESOS Y GASTOS QUE ANOTA EL DUEÑO (SOLO EL LOS VE). SE ANOTAN SIN SEÑAL (UUID DEL CELULAR)
-- LA VENTA DE UN ANIMAL NO SE ANOTA AQUI: ENTRA SOLA DESDE TAB_SALIDAS (TIPO VENTA CON VALOR) EN FUN_OBTENER_PLATA_JSON
-- CATEGORIAS: INGRESO -> VENTA_LECHE, OTRO_INGRESO; GASTO -> COMPRA_ANIMAL, DROGAS, SAL_CONCENTRADO, JORNALES, OTRO_GASTO
-- LITROS_MOVIMIENTO: SOLO EN VENTA_LECHE (OPCIONAL), PARA SACAR EL PRECIO POR LITRO
CREATE TABLE IF NOT EXISTS TAB_MOVIMIENTOS
(
    ID_MOVIMIENTO INTEGER NOT NULL,
    UUID_MOVIMIENTO UUID NOT NULL UNIQUE,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    FECHA_EVENTO TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    TIPO_MOVIMIENTO VARCHAR(10) NOT NULL,
    CATEGORIA_MOVIMIENTO VARCHAR(20) NOT NULL,
    VALOR_MOVIMIENTO NUMERIC(12,0) NOT NULL,
    LITROS_MOVIMIENTO NUMERIC(8,1),
    DESCRIPCION_MOVIMIENTO VARCHAR(200),
    ESTADO_MOVIMIENTO VARCHAR(10) NOT NULL DEFAULT 'ACTIVO',
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_MOVIMIENTO),
    CONSTRAINT CK_TIPO_MOVIMIENTO CHECK (TIPO_MOVIMIENTO IN ('INGRESO', 'GASTO')),
    CONSTRAINT CK_CATEGORIA_MOVIMIENTO CHECK (
        (TIPO_MOVIMIENTO = 'INGRESO' AND CATEGORIA_MOVIMIENTO IN ('VENTA_LECHE', 'OTRO_INGRESO')) OR
        (TIPO_MOVIMIENTO = 'GASTO' AND CATEGORIA_MOVIMIENTO IN ('COMPRA_ANIMAL', 'DROGAS', 'SAL_CONCENTRADO', 'JORNALES', 'OTRO_GASTO'))),
    CONSTRAINT CK_VALOR_MOVIMIENTO CHECK (VALOR_MOVIMIENTO > 0),
    CONSTRAINT CK_LITROS_MOVIMIENTO CHECK (LITROS_MOVIMIENTO IS NULL OR (LITROS_MOVIMIENTO > 0 AND CATEGORIA_MOVIMIENTO = 'VENTA_LECHE')),
    CONSTRAINT CK_ESTADO_MOVIMIENTO CHECK (ESTADO_MOVIMIENTO IN ('ACTIVO', 'ANULADO'))
);
CREATE INDEX IF NOT EXISTS IX_MOVIMIENTOS_SINCRONIZACION ON TAB_MOVIMIENTOS (ID_FINCA, FECHA_MODIFICACION);
CREATE INDEX IF NOT EXISTS IX_MOVIMIENTOS_FECHA ON TAB_MOVIMIENTOS (ID_FINCA, FECHA_EVENTO);

-- COLA DE MENSAJES DE WHATSAPP (FASE 5D): EL RESUMEN DIARIO DE CADA DUEÑO QUE LO ACTIVO. LA LLENA FUN_ENCOLAR_RESUMENES_JSON Y LA VACIA ms-logica
-- (DE A UNO, CON PAUSA ENTRE MENSAJES). UN SOLO RESUMEN POR DUEÑO, FINCA Y DIA. NO SE LLENA DESDE EL CELULAR: SIN UUID
-- ESTADO: PENDIENTE (POR MANDAR), ENVIADO, FALLIDO (3 INTENTOS SIN EXITO) Y SIN_NUMERO (LA CUENTA NO TIENE CELULAR VALIDO)
CREATE TABLE IF NOT EXISTS TAB_MENSAJES_WHATSAPP
(
    ID_MENSAJE INTEGER NOT NULL,
    ID_FINCA INTEGER NOT NULL REFERENCES TAB_FINCAS(ID_FINCA),
    ID_USUARIO VARCHAR(60) NOT NULL,
    FECHA_RESUMEN DATE NOT NULL,
    TEXTO_MENSAJE VARCHAR(4000) NOT NULL,
    ESTADO_MENSAJE VARCHAR(12) NOT NULL DEFAULT 'PENDIENTE',
    INTENTOS_MENSAJE INTEGER NOT NULL DEFAULT 0,
    ERROR_MENSAJE VARCHAR(300),
    FECHA_ENVIO_MENSAJE TIMESTAMP WITHOUT TIME ZONE,
    FECHA_CREACION TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    USUARIO_CREACION VARCHAR NOT NULL,
    FECHA_MODIFICACION TIMESTAMP WITHOUT TIME ZONE,
    USUARIO_MODIFICACION VARCHAR,
    PRIMARY KEY (ID_MENSAJE),
    CONSTRAINT UQ_MENSAJE_DIA UNIQUE (ID_FINCA, ID_USUARIO, FECHA_RESUMEN),
    CONSTRAINT CK_ESTADO_MENSAJE CHECK (ESTADO_MENSAJE IN ('PENDIENTE', 'ENVIADO', 'FALLIDO', 'SIN_NUMERO'))
);
CREATE INDEX IF NOT EXISTS IX_MENSAJES_PENDIENTES ON TAB_MENSAJES_WHATSAPP (ESTADO_MENSAJE, ID_MENSAJE);



-- FUNCION QUE RETORNA EL SIGUIENTE ID DE UNA TABLA ------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION funcion_Retorna_ultmoid(wnom_tabla VARCHAR,wnom_columna_id VARCHAR)RETURNS INTEGER AS

$$ DECLARE ULTIMOID INTEGER;
	BEGIN
		  --CANDADO POR TABLA HASTA QUE TERMINE LA TRANSACCION (14/10/2026): SI DOS INSERCIONES PIDEN ID A LA VEZ, LA SEGUNDA
		  --ESPERA A QUE LA PRIMERA GUARDE Y LUEGO LEE EL MAX YA ACTUALIZADO. SIN ESTO, CON PEDIDOS SIMULTANEOS SALIA
		  --"duplicate key value violates unique constraint" (PRUEBA DE ESTRES: 14 DE 20 PEDIDOS A LA VEZ FALLABAN)
		  PERFORM pg_advisory_xact_lock(hashtext(lower(wnom_tabla)));
		  EXECUTE 'SELECT MAX  ('||wnom_columna_id||')  FROM ' || wnom_tabla INTO ULTIMOID ;

		IF ULTIMOID IS NULL  THEN
			ULTIMOID=1;
			RETURN ULTIMOID;
		ELSE
		ULTIMOID=ULTIMOID+1;
		RETURN ULTIMOID;
		END IF;
	END;
$$
LANGUAGE PLPGSQL;



-- ═══════════ FUNCIONES/FUN_GENERALES/FUN_TAB_GENERALES.SQL ═══════════
-- FUNCIONES GENERALES QUE USAN TODAS LAS DEMAS -------------------------------------------------------------------------------------------------------
-- ACCESO A LA FINCA, CONFIGURACION, CATEGORIA Y ETIQUETA DEL ANIMAL, TRADUCCION DE UUID A ID Y LA VALIDACION COMUN DE LOS EVENTOS
-- SEGURIDAD DECIDE QUE PUEDE HACER EL ROL (menurol). AQUI SE DECIDE SOBRE QUE FINCA: CADA FUNCION REVISA QUE LA PERSONA TRABAJE EN ELLA



-- FUNCION QUE DEVUELVE UN VALOR NUMERICO DE TAB_CONFIGURACION (NULL SI NO EXISTE O ESTA VACIO)
CREATE OR REPLACE FUNCTION FUN_CONFIGURACION_NUMERO(
    jNOM_CONFIGURACION TAB_CONFIGURACION.NOM_CONFIGURACION%TYPE
) RETURNS NUMERIC AS
$$
DECLARE
    jVALOR VARCHAR;
BEGIN
    SELECT VALOR_CONFIGURACION INTO jVALOR FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = jNOM_CONFIGURACION;
    IF jVALOR IS NULL OR TRIM(jVALOR) = '' OR NOT TRIM(jVALOR) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RETURN NULL;
    END IF;
    RETURN TRIM(jVALOR)::NUMERIC;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE REVISA QUE LA PERSONA TRABAJE EN LA FINCA Y QUE SU ROL ESTE ENTRE LOS PERMITIDOS
-- jROLES: ROLES DE LA FINCA QUE PUEDEN HACER LA ACCION (NULL = CUALQUIER ROL ACTIVO)
-- DEVUELVE 200 CON DATOS.ROL_FINCA, 404 SI LA FINCA NO EXISTE O 400 SI NO TRABAJA AHI O SU ROL NO ALCANZA
CREATE OR REPLACE FUNCTION FUN_VALIDAR_ACCESO_FINCA(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jROLES VARCHAR[]
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jROL_FINCA VARCHAR;
BEGIN
    --VALIDACION DE LA FINCA
    IF jID_FINCA IS NULL OR NOT EXISTS (SELECT 1 FROM TAB_FINCAS WHERE ID_FINCA = jID_FINCA AND ESTADO_FINCA = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'La finca no existe');
        RETURN RETORNO;
    END IF;

    --ROL DE LA PERSONA EN ESA FINCA
    SELECT ROL_FINCA INTO jROL_FINCA
    FROM TAB_FINCAS_PERSONAS
    WHERE ID_FINCA = jID_FINCA AND ID_USUARIO = jID_USUARIO AND ESTADO_FINCA_PERSONA = 'ACTIVO';

    IF jROL_FINCA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No trabajas en esta finca');
    ELSIF jROLES IS NOT NULL AND NOT (jROL_FINCA = ANY (jROLES)) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Tu rol en esta finca no permite hacer esto. Pídeselo al dueño');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Acceso permitido', 'DATOS', json_build_object('ROL_FINCA', jROL_FINCA));
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE TRADUCE EL UUID DE UN ANIMAL A SU ID, SOLO SI ES DE ESA FINCA (NULL SI NO EXISTE O ES DE OTRA)
CREATE OR REPLACE FUNCTION FUN_ID_ANIMAL_POR_UUID(
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE
) RETURNS INTEGER AS
$$
DECLARE
    jID_ANIMAL INTEGER;
BEGIN
    SELECT ID_ANIMAL INTO jID_ANIMAL FROM TAB_ANIMALES WHERE UUID_ANIMAL = jUUID_ANIMAL AND ID_FINCA = jID_FINCA;
    RETURN jID_ANIMAL;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE TRADUCE EL UUID DE UN LOTE A SU ID, SOLO SI ES DE ESA FINCA Y ESTA ACTIVO
CREATE OR REPLACE FUNCTION FUN_ID_LOTE_POR_UUID(
    jID_FINCA TAB_LOTES.ID_FINCA%TYPE,
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE
) RETURNS INTEGER AS
$$
DECLARE
    jID_LOTE INTEGER;
BEGIN
    SELECT ID_LOTE INTO jID_LOTE FROM TAB_LOTES WHERE UUID_LOTE = jUUID_LOTE AND ID_FINCA = jID_FINCA AND ESTADO_LOTE = 'ACTIVO';
    RETURN jID_LOTE;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE CALCULA LA CATEGORIA DE UN ANIMAL (NO SE GUARDA: ASI NUNCA QUEDA DESACTUALIZADA)
-- HEMBRA: MENOS DE 12 MESES TERNERA; SIN PARTOS NOVILLA; CON AL MENOS UN PARTO VACA
-- MACHO: MENOS DE 12 MESES TERNERO; MENOS DE 30 MESES NOVILLO; DESDE 30 MESES TORO
-- jFECHA: A QUE FECHA SE CALCULA (NULL = HOY). SIRVE PARA VALIDAR EVENTOS QUE LLEGAN TARDE
CREATE OR REPLACE FUNCTION FUN_CATEGORIA_ANIMAL(
    jID_ANIMAL TAB_ANIMALES.ID_ANIMAL%TYPE,
    jFECHA DATE DEFAULT NULL
) RETURNS VARCHAR AS
$$
DECLARE
    jSEXO VARCHAR;
    jNACIMIENTO DATE;
    jMESES INTEGER;
    jPARTOS INTEGER;
BEGIN
    SELECT SEXO_ANIMAL, FECHA_NACIMIENTO INTO jSEXO, jNACIMIENTO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;
    IF jSEXO IS NULL THEN
        RETURN NULL;
    END IF;

    --EDAD EN MESES CUMPLIDOS
    jMESES := (EXTRACT(YEAR FROM age(COALESCE(jFECHA, CURRENT_DATE), jNACIMIENTO)) * 12
             + EXTRACT(MONTH FROM age(COALESCE(jFECHA, CURRENT_DATE), jNACIMIENTO)))::INTEGER;

    IF jSEXO = 'H' THEN
        SELECT COUNT(*) INTO jPARTOS FROM TAB_PARTOS
        WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PARTO = 'ACTIVO' AND FECHA_EVENTO::DATE <= COALESCE(jFECHA, CURRENT_DATE);
        IF jPARTOS > 0 THEN
            RETURN 'VACA';
        ELSIF jMESES < 12 THEN
            RETURN 'TERNERA';
        ELSE
            RETURN 'NOVILLA';
        END IF;
    ELSE
        IF jMESES < 12 THEN
            RETURN 'TERNERO';
        ELSIF jMESES < 30 THEN
            RETURN 'NOVILLO';
        ELSE
            RETURN 'TORO';
        END IF;
    END IF;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE ARMA COMO SE NOMBRA UN ANIMAL EN LOS MENSAJES: "la vaca 23 (Lucero)", "el ternero sin chapeta"
CREATE OR REPLACE FUNCTION FUN_ETIQUETA_ANIMAL(
    jID_ANIMAL TAB_ANIMALES.ID_ANIMAL%TYPE
) RETURNS VARCHAR AS
$$
DECLARE
    jCATEGORIA VARCHAR;
    jCHAPETA VARCHAR;
    jNOM VARCHAR;
BEGIN
    SELECT CHAPETA_ANIMAL, NOM_ANIMAL INTO jCHAPETA, jNOM FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;
    jCATEGORIA := FUN_CATEGORIA_ANIMAL(jID_ANIMAL);
    IF jCATEGORIA IS NULL THEN
        RETURN 'el animal';
    END IF;

    RETURN CASE WHEN jCATEGORIA IN ('TERNERA', 'NOVILLA', 'VACA') THEN 'la ' ELSE 'el ' END
        || LOWER(jCATEGORIA)
        || COALESCE(' ' || jCHAPETA, ' sin chapeta')
        || COALESCE(' (' || jNOM || ')', '');
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE VALIDA LO COMUN A TODOS LOS EVENTOS DE UN ANIMAL
-- LA FECHA NO PUEDE SER FUTURA (UN DIA DE MARGEN POR EL RELOJ DEL CELULAR), NI ANTES DEL NACIMIENTO, NI DESPUES DE LA SALIDA DEL ANIMAL
-- SE COMPARA CON LA FECHA DE LA SALIDA Y NO CON EL ESTADO: UN EVENTO SIN SEÑAL DE ANTES DE LA VENTA PUEDE LLEGAR DESPUES Y ES VALIDO
CREATE OR REPLACE FUNCTION FUN_VALIDAR_EVENTO_ANIMAL(
    jID_ANIMAL TAB_ANIMALES.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_PESAJES.FECHA_EVENTO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jESTADO VARCHAR;
    jNACIMIENTO DATE;
    jFECHA_SALIDA TIMESTAMP;
    jTIPO_SALIDA VARCHAR;
BEGIN
    SELECT ESTADO_ANIMAL, FECHA_NACIMIENTO INTO jESTADO, jNACIMIENTO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;
    SELECT FECHA_EVENTO, TIPO_SALIDA INTO jFECHA_SALIDA, jTIPO_SALIDA FROM TAB_SALIDAS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_SALIDA = 'ACTIVO';

    --VALIDACION DEL ANIMAL
    IF jESTADO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El animal no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ese animal fue anulado');
        RETURN RETORNO;

    --VALIDACION DE LA FECHA DEL EVENTO
    ELSIF jFECHA_EVENTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta la fecha');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO > NOW() + INTERVAL '1 day' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha no puede ser futura');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO::DATE < jNACIMIENTO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha es anterior al nacimiento de ' || FUN_ETIQUETA_ANIMAL(jID_ANIMAL)
            || ' (' || to_char(jNACIMIENTO, 'DD/MM/YYYY') || ')');
        RETURN RETORNO;
    ELSIF jFECHA_SALIDA IS NOT NULL AND jFECHA_EVENTO > jFECHA_SALIDA THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', upper(left(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 1)) || substr(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 2)
            || CASE jTIPO_SALIDA WHEN 'VENTA' THEN ' se vendió' WHEN 'MUERTE' THEN ' murió' ELSE ' salió de la finca' END
            || ' el ' || to_char(jFECHA_SALIDA, 'DD/MM/YYYY') || ': no se le pueden registrar cosas después de esa fecha');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LA TABLA Y LAS COLUMNAS DE UN TIPO DE REGISTRO (LA USAN ANULAR, EL HISTORIAL Y LA SINCRONIZACION)
-- NULL SI EL TIPO NO EXISTE. ES LA LISTA BLANCA: NINGUN NOMBRE DE TABLA LLEGA DESDE AFUERA SIN PASAR POR AQUI
CREATE OR REPLACE FUNCTION FUN_TABLA_POR_TIPO(
    jTIPO VARCHAR
) RETURNS JSON AS
$$
BEGIN
    RETURN CASE UPPER(TRIM(jTIPO))
        WHEN 'LOTE'       THEN json_build_object('TABLA', 'TAB_LOTES',        'ID', 'ID_LOTE',       'UUID', 'UUID_LOTE',       'ESTADO', 'ESTADO_LOTE')
        WHEN 'ANIMAL'     THEN json_build_object('TABLA', 'TAB_ANIMALES',     'ID', 'ID_ANIMAL',     'UUID', 'UUID_ANIMAL',     'ESTADO', 'ESTADO_ANIMAL')
        WHEN 'PESAJE'     THEN json_build_object('TABLA', 'TAB_PESAJES',      'ID', 'ID_PESAJE',     'UUID', 'UUID_PESAJE',     'ESTADO', 'ESTADO_PESAJE')
        WHEN 'VACUNACION' THEN json_build_object('TABLA', 'TAB_VACUNACIONES', 'ID', 'ID_VACUNACION', 'UUID', 'UUID_VACUNACION', 'ESTADO', 'ESTADO_VACUNACION')
        WHEN 'SERVICIO'   THEN json_build_object('TABLA', 'TAB_SERVICIOS',    'ID', 'ID_SERVICIO',   'UUID', 'UUID_SERVICIO',   'ESTADO', 'ESTADO_SERVICIO')
        WHEN 'PALPACION'  THEN json_build_object('TABLA', 'TAB_PALPACIONES',  'ID', 'ID_PALPACION',  'UUID', 'UUID_PALPACION',  'ESTADO', 'ESTADO_PALPACION')
        WHEN 'PARTO'      THEN json_build_object('TABLA', 'TAB_PARTOS',       'ID', 'ID_PARTO',      'UUID', 'UUID_PARTO',      'ESTADO', 'ESTADO_PARTO')
        WHEN 'ORDENO'     THEN json_build_object('TABLA', 'TAB_ORDENOS',      'ID', 'ID_ORDENO',     'UUID', 'UUID_ORDENO',     'ESTADO', 'ESTADO_ORDENO')
        WHEN 'SALIDA'     THEN json_build_object('TABLA', 'TAB_SALIDAS',      'ID', 'ID_SALIDA',     'UUID', 'UUID_SALIDA',     'ESTADO', 'ESTADO_SALIDA')
        WHEN 'POTRERO'    THEN json_build_object('TABLA', 'TAB_POTREROS',     'ID', 'ID_POTRERO',    'UUID', 'UUID_POTRERO',    'ESTADO', 'ESTADO_POTRERO')
        WHEN 'OCUPACION'  THEN json_build_object('TABLA', 'TAB_OCUPACIONES',  'ID', 'ID_OCUPACION',  'UUID', 'UUID_OCUPACION',  'ESTADO', 'ESTADO_OCUPACION')
        WHEN 'MOVIMIENTO' THEN json_build_object('TABLA', 'TAB_MOVIMIENTOS',  'ID', 'ID_MOVIMIENTO', 'UUID', 'UUID_MOVIMIENTO', 'ESTADO', 'ESTADO_MOVIMIENTO')
        ELSE NULL
    END;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DICE SI YA EXISTE UN REGISTRO CON ESE UUID EN LA TABLA DE SU TIPO (FALSE SI EL TIPO NO EXISTE)
-- LA USA LA SINCRONIZACION CUANDO DOS CELULARES SUBEN EL MISMO REGISTRO AL MISMO TIEMPO Y EL SEGUNDO CHOCA CON EL UNIQUE DEL UUID
CREATE OR REPLACE FUNCTION FUN_EXISTE_UUID(
    jTIPO VARCHAR,
    jUUID UUID
) RETURNS BOOLEAN AS
$$
DECLARE
    jTABLA JSON;
    jEXISTE BOOLEAN;
BEGIN
    jTABLA := FUN_TABLA_POR_TIPO(jTIPO);
    IF jTABLA IS NULL OR jUUID IS NULL THEN
        RETURN false;
    END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s WHERE %s = $1)', jTABLA ->> 'TABLA', jTABLA ->> 'UUID') INTO jEXISTE USING jUUID;
    RETURN jEXISTE;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_FINCAS/FUN_TAB_FINCAS.SQL ═══════════
-- FUNCIONES DE LAS TABLAS TAB_FINCAS Y TAB_FINCAS_PERSONAS -------------------------------------------------------------------------------------------
-- QUIEN CREA LA FINCA QUEDA COMO SU DUEÑO (EN LA MISMA TRANSACCION). EL DUEÑO AGREGA A LOS VAQUEROS Y AL VETERINARIO
-- REGLAS: TODA FINCA TIENE AL MENOS UN DUEÑO ACTIVO Y NADIE SE QUITA A SI MISMO DE LA FINCA



--FUNCION PARA VALIDAR LOS DATOS DE UNA FINCA (SIRVE PARA CREAR Y ACTUALIZAR)
--EL ORDEN DE LAS VALIDACIONES ES EL DEL FORMULARIO
CREATE OR REPLACE FUNCTION FUN_VALIDAR_FINCAS(
    jNOM_FINCA TAB_FINCAS.NOM_FINCA%TYPE,
    jMUNICIPIO_FINCA TAB_FINCAS.MUNICIPIO_FINCA%TYPE,
    jVEREDA_FINCA TAB_FINCAS.VEREDA_FINCA%TYPE,
    jREGISTRO_ICA_FINCA TAB_FINCAS.REGISTRO_ICA_FINCA%TYPE,
    jHIERRO_FINCA TAB_FINCAS.HIERRO_FINCA%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    --VALIDACION VARIABLE NOM_FINCA (OBLIGATORIO)
    IF jNOM_FINCA IS NULL OR TRIM(jNOM_FINCA) = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre de la finca');
        RETURN RETORNO;
    ELSIF LENGTH(TRIM(jNOM_FINCA)) > 100 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El nombre de la finca es demasiado largo (máximo 100 caracteres)');
        RETURN RETORNO;

    --VALIDACION VARIABLE MUNICIPIO_FINCA (OBLIGATORIO)
    ELSIF jMUNICIPIO_FINCA IS NULL OR TRIM(jMUNICIPIO_FINCA) = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el municipio');
        RETURN RETORNO;
    ELSIF LENGTH(TRIM(jMUNICIPIO_FINCA)) > 80 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El municipio es demasiado largo (máximo 80 caracteres)');
        RETURN RETORNO;

    --VALIDACION VARIABLE VEREDA_FINCA (OPCIONAL)
    ELSIF LENGTH(TRIM(COALESCE(jVEREDA_FINCA, ''))) > 80 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La vereda es demasiado larga (máximo 80 caracteres)');
        RETURN RETORNO;

    --VALIDACION VARIABLE REGISTRO_ICA_FINCA (OPCIONAL: LETRAS, NUMEROS Y GUIONES)
    ELSIF COALESCE(TRIM(jREGISTRO_ICA_FINCA), '') <> '' AND NOT TRIM(jREGISTRO_ICA_FINCA) ~ '^[A-Za-z0-9-]{3,30}$' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El registro ICA solo puede tener letras, números y guiones (de 3 a 30)');
        RETURN RETORNO;

    --VALIDACION VARIABLE HIERRO_FINCA (OPCIONAL)
    ELSIF LENGTH(TRIM(COALESCE(jHIERRO_FINCA, ''))) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La descripción del hierro es demasiado larga (máximo 60 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CREAR UNA FINCA. QUIEN LA CREA QUEDA COMO DUEÑO
-- DOS DML (FINCA Y DUEÑO): BLOQUE BEGIN ... EXCEPTION, ENTRAN LOS DOS O NINGUNO
CREATE OR REPLACE FUNCTION FUN_CREAR_FINCA_JSON(
    jNOM_FINCA TAB_FINCAS.NOM_FINCA%TYPE,
    jMUNICIPIO_FINCA TAB_FINCAS.MUNICIPIO_FINCA%TYPE,
    jVEREDA_FINCA TAB_FINCAS.VEREDA_FINCA%TYPE,
    jREGISTRO_ICA_FINCA TAB_FINCAS.REGISTRO_ICA_FINCA%TYPE,
    jHIERRO_FINCA TAB_FINCAS.HIERRO_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jNOM_PERSONA TAB_FINCAS_PERSONAS.NOM_PERSONA%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_FINCA INTEGER;
    jID_FINCA_PERSONA INTEGER;
BEGIN
    --LLAMAR A LA FUNCION DE VALIDACION
    jVALIDACION := FUN_VALIDAR_FINCAS(jNOM_FINCA, jMUNICIPIO_FINCA, jVEREDA_FINCA, jREGISTRO_ICA_FINCA, jHIERRO_FINCA);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jID_USUARIO IS NULL OR TRIM(jID_USUARIO) = '' OR jNOM_PERSONA IS NULL OR TRIM(jNOM_PERSONA) = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el usuario que crea la finca');
        RETURN RETORNO;
    END IF;

    BEGIN
        --CREAR LA FINCA
        jID_FINCA := funcion_Retorna_ultmoid('TAB_FINCAS', 'ID_FINCA');
        INSERT INTO TAB_FINCAS (ID_FINCA, NOM_FINCA, MUNICIPIO_FINCA, VEREDA_FINCA, REGISTRO_ICA_FINCA, HIERRO_FINCA, USUARIO_CREACION)
        VALUES (jID_FINCA, regexp_replace(TRIM(jNOM_FINCA), '\s+', ' ', 'g'), regexp_replace(TRIM(jMUNICIPIO_FINCA), '\s+', ' ', 'g'),
            NULLIF(TRIM(jVEREDA_FINCA), ''), NULLIF(UPPER(TRIM(jREGISTRO_ICA_FINCA)), ''), NULLIF(TRIM(jHIERRO_FINCA), ''), jID_USUARIO);
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No se pudo crear la finca';
        END IF;

        --QUIEN LA CREA QUEDA COMO DUEÑO
        jID_FINCA_PERSONA := funcion_Retorna_ultmoid('TAB_FINCAS_PERSONAS', 'ID_FINCA_PERSONA');
        INSERT INTO TAB_FINCAS_PERSONAS (ID_FINCA_PERSONA, ID_FINCA, ID_USUARIO, NOM_PERSONA, ROL_FINCA, USUARIO_CREACION)
        VALUES (jID_FINCA_PERSONA, jID_FINCA, TRIM(jID_USUARIO), regexp_replace(TRIM(jNOM_PERSONA), '\s+', ' ', 'g'), 'DUENIO', jID_USUARIO);
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No se pudo asignar el dueño de la finca';
        END IF;

        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Finca creada: ya puedes registrar tus animales', 'DATOS', json_build_object('ID_FINCA', jID_FINCA));
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ACTUALIZAR LOS DATOS DE UNA FINCA (SOLO EL DUEÑO)
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_FINCA_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jNOM_FINCA TAB_FINCAS.NOM_FINCA%TYPE,
    jMUNICIPIO_FINCA TAB_FINCAS.MUNICIPIO_FINCA%TYPE,
    jVEREDA_FINCA TAB_FINCAS.VEREDA_FINCA%TYPE,
    jREGISTRO_ICA_FINCA TAB_FINCAS.REGISTRO_ICA_FINCA%TYPE,
    jHIERRO_FINCA TAB_FINCAS.HIERRO_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
BEGIN
    --VALIDAR EL ACCESO Y LOS DATOS
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;
    jVALIDACION := FUN_VALIDAR_FINCAS(jNOM_FINCA, jMUNICIPIO_FINCA, jVEREDA_FINCA, jREGISTRO_ICA_FINCA, jHIERRO_FINCA);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --ACTUALIZAR LA FINCA
    UPDATE TAB_FINCAS
    SET NOM_FINCA = regexp_replace(TRIM(jNOM_FINCA), '\s+', ' ', 'g'),
        MUNICIPIO_FINCA = regexp_replace(TRIM(jMUNICIPIO_FINCA), '\s+', ' ', 'g'),
        VEREDA_FINCA = NULLIF(TRIM(jVEREDA_FINCA), ''),
        REGISTRO_ICA_FINCA = NULLIF(UPPER(TRIM(jREGISTRO_ICA_FINCA)), ''),
        HIERRO_FINCA = NULLIF(TRIM(jHIERRO_FINCA), ''),
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_FINCA = jID_FINCA;

    --VERIFICAR SI LA ACTUALIZACION FUE EXITOSA
    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Datos de la finca actualizados');
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al actualizar la finca');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LAS FINCAS DONDE TRABAJA UNA PERSONA, CON SU ROL Y CUANTOS ANIMALES ACTIVOS TIENE CADA UNA
CREATE OR REPLACE FUNCTION FUN_OBTENER_MIS_FINCAS_JSON(
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_FINCAS JSON;
BEGIN
    SELECT json_agg(json_build_object(
        'ID_FINCA', F.ID_FINCA,
        'NOM_FINCA', F.NOM_FINCA,
        'MUNICIPIO_FINCA', F.MUNICIPIO_FINCA,
        'VEREDA_FINCA', F.VEREDA_FINCA,
        'ROL_FINCA', P.ROL_FINCA,
        'ANIMALES_ACTIVOS', (SELECT COUNT(*) FROM TAB_ANIMALES A WHERE A.ID_FINCA = F.ID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO')
    ) ORDER BY F.NOM_FINCA) INTO LISTA_FINCAS
    FROM TAB_FINCAS_PERSONAS P
    JOIN TAB_FINCAS F ON F.ID_FINCA = P.ID_FINCA
    WHERE P.ID_USUARIO = jID_USUARIO
      AND P.ESTADO_FINCA_PERSONA = 'ACTIVO'
      AND F.ESTADO_FINCA = 'ACTIVO';

    IF LISTA_FINCAS IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Todavía no trabajas en ninguna finca');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Tus fincas', 'DATOS', LISTA_FINCAS);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LOS DATOS DE UNA FINCA CON EL ROL DE QUIEN PREGUNTA
CREATE OR REPLACE FUNCTION FUN_OBTENER_FINCA_POR_ID_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jDATOS JSON;
BEGIN
    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_build_object(
        'ID_FINCA', ID_FINCA,
        'NOM_FINCA', NOM_FINCA,
        'MUNICIPIO_FINCA', MUNICIPIO_FINCA,
        'VEREDA_FINCA', VEREDA_FINCA,
        'REGISTRO_ICA_FINCA', REGISTRO_ICA_FINCA,
        'HIERRO_FINCA', HIERRO_FINCA,
        'ROL_FINCA', jVALIDACION -> 'DATOS' ->> 'ROL_FINCA',
        'FECHA_CREACION', FECHA_CREACION
    ) INTO jDATOS
    FROM TAB_FINCAS
    WHERE ID_FINCA = jID_FINCA;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Datos de la finca', 'DATOS', jDATOS);
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA AGREGAR UNA PERSONA A LA FINCA (SOLO EL DUEÑO). LA CUENTA YA DEBE EXISTIR EN SEGURIDAD: ms-logica LA BUSCA Y PASA SU id_usuario Y NOMBRE
-- SI LA PERSONA YA ESTUVO EN LA FINCA Y SE HABIA QUITADO, SE REACTIVA CON EL ROL NUEVO
CREATE OR REPLACE FUNCTION FUN_AGREGAR_PERSONA_FINCA_JSON(
    jID_FINCA TAB_FINCAS_PERSONAS.ID_FINCA%TYPE,
    jID_USUARIO_PERSONA TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jNOM_PERSONA TAB_FINCAS_PERSONAS.NOM_PERSONA%TYPE,
    jROL_FINCA TAB_FINCAS_PERSONAS.ROL_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_FINCA_PERSONA INTEGER;
    jESTADO_ACTUAL VARCHAR;
BEGIN
    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT ID_FINCA_PERSONA, ESTADO_FINCA_PERSONA INTO jID_FINCA_PERSONA, jESTADO_ACTUAL
    FROM TAB_FINCAS_PERSONAS WHERE ID_FINCA = jID_FINCA AND ID_USUARIO = TRIM(jID_USUARIO_PERSONA);

    --VALIDACIONES
    IF jID_USUARIO_PERSONA IS NULL OR TRIM(jID_USUARIO_PERSONA) = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige la persona');
        RETURN RETORNO;
    ELSIF jNOM_PERSONA IS NULL OR TRIM(jNOM_PERSONA) = '' OR LENGTH(TRIM(jNOM_PERSONA)) > 150 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el nombre de la persona');
        RETURN RETORNO;
    ELSIF jROL_FINCA IS NULL OR jROL_FINCA NOT IN ('DUENIO', 'VAQUERO', 'VETERINARIO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige un rol válido: dueño, vaquero o veterinario');
        RETURN RETORNO;
    ELSIF jESTADO_ACTUAL = 'ACTIVO' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Esa persona ya trabaja en esta finca');
        RETURN RETORNO;
    END IF;

    IF jID_FINCA_PERSONA IS NOT NULL THEN
        --YA ESTUVO EN LA FINCA: SE REACTIVA CON EL ROL NUEVO
        UPDATE TAB_FINCAS_PERSONAS
        SET ROL_FINCA = jROL_FINCA,
            NOM_PERSONA = regexp_replace(TRIM(jNOM_PERSONA), '\s+', ' ', 'g'),
            ESTADO_FINCA_PERSONA = 'ACTIVO',
            USUARIO_MODIFICACION = jID_USUARIO,
            FECHA_MODIFICACION = NOW()
        WHERE ID_FINCA_PERSONA = jID_FINCA_PERSONA;
    ELSE
        jID_FINCA_PERSONA := funcion_Retorna_ultmoid('TAB_FINCAS_PERSONAS', 'ID_FINCA_PERSONA');
        INSERT INTO TAB_FINCAS_PERSONAS (ID_FINCA_PERSONA, ID_FINCA, ID_USUARIO, NOM_PERSONA, ROL_FINCA, USUARIO_CREACION)
        VALUES (jID_FINCA_PERSONA, jID_FINCA, TRIM(jID_USUARIO_PERSONA), regexp_replace(TRIM(jNOM_PERSONA), '\s+', ' ', 'g'), jROL_FINCA, jID_USUARIO);
    END IF;

    --VERIFICAR SI LA OPERACION FUE EXITOSA
    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Persona agregada a la finca', 'DATOS', json_build_object('ID_FINCA_PERSONA', jID_FINCA_PERSONA));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al agregar la persona');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CAMBIAR EL ROL O QUITAR / DEVOLVER A UNA PERSONA DE LA FINCA (SOLO EL DUEÑO)
-- NADIE SE CAMBIA NI SE QUITA A SI MISMO Y LA FINCA NUNCA QUEDA SIN DUEÑO ACTIVO
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_PERSONA_FINCA_JSON(
    jID_FINCA_PERSONA TAB_FINCAS_PERSONAS.ID_FINCA_PERSONA%TYPE,
    jROL_FINCA TAB_FINCAS_PERSONAS.ROL_FINCA%TYPE,
    jESTADO TAB_FINCAS_PERSONAS.ESTADO_FINCA_PERSONA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_FINCA INTEGER;
    jID_USUARIO_PERSONA VARCHAR;
    jROL_ACTUAL VARCHAR;
    jOTROS_DUENIOS INTEGER;
BEGIN
    SELECT ID_FINCA, ID_USUARIO, ROL_FINCA INTO jID_FINCA, jID_USUARIO_PERSONA, jROL_ACTUAL
    FROM TAB_FINCAS_PERSONAS WHERE ID_FINCA_PERSONA = jID_FINCA_PERSONA;

    IF jID_FINCA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Esa persona no está en la finca');
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT COUNT(*) INTO jOTROS_DUENIOS FROM TAB_FINCAS_PERSONAS
    WHERE ID_FINCA = jID_FINCA AND ROL_FINCA = 'DUENIO' AND ESTADO_FINCA_PERSONA = 'ACTIVO' AND ID_FINCA_PERSONA <> jID_FINCA_PERSONA;

    --VALIDACIONES
    IF jROL_FINCA IS NULL OR jROL_FINCA NOT IN ('DUENIO', 'VAQUERO', 'VETERINARIO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige un rol válido: dueño, vaquero o veterinario');
        RETURN RETORNO;
    ELSIF jESTADO IS NULL OR jESTADO NOT IN ('ACTIVO', 'INACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El estado debe ser ACTIVO o INACTIVO');
        RETURN RETORNO;
    ELSIF jID_USUARIO_PERSONA = jID_USUARIO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No puedes cambiar tu propio rol ni quitarte de la finca');
        RETURN RETORNO;
    ELSIF jROL_ACTUAL = 'DUENIO' AND (jROL_FINCA <> 'DUENIO' OR jESTADO = 'INACTIVO') AND jOTROS_DUENIOS = 0 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La finca se quedaría sin dueño');
        RETURN RETORNO;
    END IF;

    --ACTUALIZAR
    UPDATE TAB_FINCAS_PERSONAS
    SET ROL_FINCA = jROL_FINCA,
        ESTADO_FINCA_PERSONA = jESTADO,
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_FINCA_PERSONA = jID_FINCA_PERSONA;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE',
            CASE WHEN jESTADO = 'INACTIVO' THEN 'La persona ya no ve esta finca' ELSE 'Persona actualizada' END);
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al actualizar la persona');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LAS PERSONAS DE LA FINCA (CUALQUIER ROL LAS PUEDE VER: EL VAQUERO SABE QUIEN ES EL DUEÑO)
CREATE OR REPLACE FUNCTION FUN_OBTENER_PERSONAS_FINCA_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    LISTA_PERSONAS JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_agg(json_build_object(
        'ID_FINCA_PERSONA', ID_FINCA_PERSONA,
        'ID_USUARIO', ID_USUARIO,
        'NOM_PERSONA', NOM_PERSONA,
        'ROL_FINCA', ROL_FINCA,
        'ESTADO_FINCA_PERSONA', ESTADO_FINCA_PERSONA
    ) ORDER BY ESTADO_FINCA_PERSONA, CASE ROL_FINCA WHEN 'DUENIO' THEN 1 WHEN 'VETERINARIO' THEN 2 ELSE 3 END, NOM_PERSONA) INTO LISTA_PERSONAS
    FROM TAB_FINCAS_PERSONAS
    WHERE ID_FINCA = jID_FINCA;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Personas de la finca', 'DATOS', LISTA_PERSONAS);
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_CATALOGOS/FUN_TAB_CATALOGOS.SQL ═══════════
-- FUNCIONES DE LOS CATALOGOS GLOBALES: TAB_RAZAS, TAB_VACUNAS Y TAB_CICLOS_ICA --------------------------------------------------------------------
-- LOS MANTIENE EL ADMINISTRADOR DE LA PLATAFORMA (MENU 7 CONFIGURACION; EL PERMISO LO REVISA ms-logica CON menurol)
-- SON IGUALES PARA TODAS LAS FINCAS Y BAJAN AL CELULAR CON FUN_OBTENER_CAMBIOS_JSON



-- FUNCION QUE DEVUELVE LAS RAZAS ACTIVAS
CREATE OR REPLACE FUNCTION FUN_OBTENER_RAZAS_JSON(
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_RAZAS JSON;
BEGIN
    SELECT json_agg(json_build_object('ID_RAZA', ID_RAZA, 'NOM_RAZA', NOM_RAZA) ORDER BY NOM_RAZA) INTO LISTA_RAZAS
    FROM TAB_RAZAS WHERE ESTADO_RAZA = 'ACTIVO';

    IF LISTA_RAZAS IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'No hay razas registradas');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Razas', 'DATOS', LISTA_RAZAS);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CREAR UNA RAZA (ADMINISTRADOR)
CREATE OR REPLACE FUNCTION FUN_CREAR_RAZA_JSON(
    jNOM_RAZA TAB_RAZAS.NOM_RAZA%TYPE,
    jUSUARIO TAB_RAZAS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jID_RAZA INTEGER;
BEGIN
    --VALIDACIONES
    IF jNOM_RAZA IS NULL OR TRIM(jNOM_RAZA) = '' OR LENGTH(TRIM(jNOM_RAZA)) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre de la raza (máximo 60 caracteres)');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_RAZAS WHERE LOWER(NOM_RAZA) = LOWER(TRIM(jNOM_RAZA))) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Esa raza ya existe');
        RETURN RETORNO;
    END IF;

    jID_RAZA := funcion_Retorna_ultmoid('TAB_RAZAS', 'ID_RAZA');
    INSERT INTO TAB_RAZAS (ID_RAZA, NOM_RAZA, USUARIO_CREACION)
    VALUES (jID_RAZA, regexp_replace(TRIM(jNOM_RAZA), '\s+', ' ', 'g'), jUSUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Raza creada', 'DATOS', json_build_object('ID_RAZA', jID_RAZA));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al crear la raza');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LAS VACUNAS Y TRATAMIENTOS (jSOLO_ACTIVAS = 'SI' PARA LOS FORMULARIOS, 'NO' PARA LA PANTALLA DE CONFIGURACION)
CREATE OR REPLACE FUNCTION FUN_OBTENER_VACUNAS_JSON(
    jSOLO_ACTIVAS VARCHAR
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_VACUNAS JSON;
BEGIN
    SELECT json_agg(json_build_object(
        'ID_VACUNA', ID_VACUNA,
        'NOM_VACUNA', NOM_VACUNA,
        'TIPO_VACUNA', TIPO_VACUNA,
        'DIAS_REFUERZO', DIAS_REFUERZO,
        'DIAS_RETIRO_LECHE', DIAS_RETIRO_LECHE,
        'OBLIGATORIA_ICA', OBLIGATORIA_ICA,
        'ESTADO_VACUNA', ESTADO_VACUNA
    ) ORDER BY TIPO_VACUNA, NOM_VACUNA) INTO LISTA_VACUNAS
    FROM TAB_VACUNAS
    WHERE COALESCE(jSOLO_ACTIVAS, 'SI') = 'NO' OR ESTADO_VACUNA = 'ACTIVO';

    IF LISTA_VACUNAS IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'No hay vacunas registradas');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Vacunas y tratamientos', 'DATOS', LISTA_VACUNAS);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



--FUNCION PARA VALIDAR LOS DATOS DE UNA VACUNA (jID_VACUNA NULL AL CREAR)
CREATE OR REPLACE FUNCTION FUN_VALIDAR_VACUNAS(
    jID_VACUNA TAB_VACUNAS.ID_VACUNA%TYPE,
    jNOM_VACUNA TAB_VACUNAS.NOM_VACUNA%TYPE,
    jTIPO_VACUNA TAB_VACUNAS.TIPO_VACUNA%TYPE,
    jDIAS_REFUERZO TAB_VACUNAS.DIAS_REFUERZO%TYPE,
    jDIAS_RETIRO_LECHE TAB_VACUNAS.DIAS_RETIRO_LECHE%TYPE,
    jOBLIGATORIA_ICA TAB_VACUNAS.OBLIGATORIA_ICA%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    --VALIDACION VARIABLE ID_VACUNA (SOLO AL ACTUALIZAR)
    IF jID_VACUNA IS NOT NULL AND NOT EXISTS (SELECT 1 FROM TAB_VACUNAS WHERE ID_VACUNA = jID_VACUNA) THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'La vacuna no existe');
        RETURN RETORNO;

    --VALIDACION VARIABLE NOM_VACUNA (OBLIGATORIO, UNICO)
    ELSIF jNOM_VACUNA IS NULL OR TRIM(jNOM_VACUNA) = '' OR LENGTH(TRIM(jNOM_VACUNA)) > 80 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre del producto (máximo 80 caracteres)');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_VACUNAS WHERE LOWER(NOM_VACUNA) = LOWER(TRIM(jNOM_VACUNA)) AND ID_VACUNA IS DISTINCT FROM jID_VACUNA) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya hay un producto con ese nombre');
        RETURN RETORNO;

    --VALIDACION VARIABLE TIPO_VACUNA
    ELSIF jTIPO_VACUNA IS NULL OR jTIPO_VACUNA NOT IN ('VACUNA', 'TRATAMIENTO', 'DESPARASITANTE', 'VITAMINA') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige el tipo: vacuna, tratamiento, desparasitante o vitamina');
        RETURN RETORNO;

    --VALIDACION VARIABLES DE DIAS
    ELSIF jDIAS_REFUERZO IS NOT NULL AND (jDIAS_REFUERZO < 1 OR jDIAS_REFUERZO > 1095) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los días del refuerzo van de 1 a 1095 (o vacío si es dosis única)');
        RETURN RETORNO;
    ELSIF jDIAS_RETIRO_LECHE IS NULL OR jDIAS_RETIRO_LECHE < 0 OR jDIAS_RETIRO_LECHE > 120 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los días de retiro de leche van de 0 a 120 (mira la etiqueta del producto)');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBLIGATORIA_ICA
    ELSIF jOBLIGATORIA_ICA IS NULL OR jOBLIGATORIA_ICA NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Indica si es obligatoria del ICA (SI o NO)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CREAR UNA VACUNA O TRATAMIENTO (ADMINISTRADOR)
CREATE OR REPLACE FUNCTION FUN_CREAR_VACUNA_JSON(
    jNOM_VACUNA TAB_VACUNAS.NOM_VACUNA%TYPE,
    jTIPO_VACUNA TAB_VACUNAS.TIPO_VACUNA%TYPE,
    jDIAS_REFUERZO TAB_VACUNAS.DIAS_REFUERZO%TYPE,
    jDIAS_RETIRO_LECHE TAB_VACUNAS.DIAS_RETIRO_LECHE%TYPE,
    jOBLIGATORIA_ICA TAB_VACUNAS.OBLIGATORIA_ICA%TYPE,
    jUSUARIO TAB_VACUNAS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_VACUNA INTEGER;
BEGIN
    jVALIDACION := FUN_VALIDAR_VACUNAS(NULL, jNOM_VACUNA, jTIPO_VACUNA, jDIAS_REFUERZO, jDIAS_RETIRO_LECHE, jOBLIGATORIA_ICA);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_VACUNA := funcion_Retorna_ultmoid('TAB_VACUNAS', 'ID_VACUNA');
    INSERT INTO TAB_VACUNAS (ID_VACUNA, NOM_VACUNA, TIPO_VACUNA, DIAS_REFUERZO, DIAS_RETIRO_LECHE, OBLIGATORIA_ICA, USUARIO_CREACION)
    VALUES (jID_VACUNA, regexp_replace(TRIM(jNOM_VACUNA), '\s+', ' ', 'g'), jTIPO_VACUNA, jDIAS_REFUERZO, jDIAS_RETIRO_LECHE, jOBLIGATORIA_ICA, jUSUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Producto creado', 'DATOS', json_build_object('ID_VACUNA', jID_VACUNA));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al crear el producto');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ACTUALIZAR UNA VACUNA O TRATAMIENTO (ADMINISTRADOR). INACTIVO = YA NO SALE EN LOS FORMULARIOS (LO REGISTRADO SE CONSERVA)
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_VACUNA_JSON(
    jID_VACUNA TAB_VACUNAS.ID_VACUNA%TYPE,
    jNOM_VACUNA TAB_VACUNAS.NOM_VACUNA%TYPE,
    jTIPO_VACUNA TAB_VACUNAS.TIPO_VACUNA%TYPE,
    jDIAS_REFUERZO TAB_VACUNAS.DIAS_REFUERZO%TYPE,
    jDIAS_RETIRO_LECHE TAB_VACUNAS.DIAS_RETIRO_LECHE%TYPE,
    jOBLIGATORIA_ICA TAB_VACUNAS.OBLIGATORIA_ICA%TYPE,
    jESTADO_VACUNA TAB_VACUNAS.ESTADO_VACUNA%TYPE,
    jUSUARIO TAB_VACUNAS.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
BEGIN
    IF jID_VACUNA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'ID_VACUNA no puede ser nulo');
        RETURN RETORNO;
    ELSIF jESTADO_VACUNA IS NULL OR jESTADO_VACUNA NOT IN ('ACTIVO', 'INACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El estado debe ser ACTIVO o INACTIVO');
        RETURN RETORNO;
    END IF;
    jVALIDACION := FUN_VALIDAR_VACUNAS(jID_VACUNA, jNOM_VACUNA, jTIPO_VACUNA, jDIAS_REFUERZO, jDIAS_RETIRO_LECHE, jOBLIGATORIA_ICA);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    UPDATE TAB_VACUNAS
    SET NOM_VACUNA = regexp_replace(TRIM(jNOM_VACUNA), '\s+', ' ', 'g'),
        TIPO_VACUNA = jTIPO_VACUNA,
        DIAS_REFUERZO = jDIAS_REFUERZO,
        DIAS_RETIRO_LECHE = jDIAS_RETIRO_LECHE,
        OBLIGATORIA_ICA = jOBLIGATORIA_ICA,
        ESTADO_VACUNA = jESTADO_VACUNA,
        USUARIO_MODIFICACION = jUSUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_VACUNA = jID_VACUNA;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Producto actualizado. Lo ya registrado conserva sus fechas');
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al actualizar el producto');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LOS CICLOS DEL ICA ACTIVOS (LOS MAS RECIENTES PRIMERO)
CREATE OR REPLACE FUNCTION FUN_OBTENER_CICLOS_ICA_JSON(
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_CICLOS JSON;
BEGIN
    SELECT json_agg(json_build_object(
        'ID_CICLO', C.ID_CICLO,
        'ID_VACUNA', C.ID_VACUNA,
        'NOM_VACUNA', V.NOM_VACUNA,
        'NOM_CICLO', C.NOM_CICLO,
        'FECHA_INICIO_CICLO', C.FECHA_INICIO_CICLO,
        'FECHA_FIN_CICLO', C.FECHA_FIN_CICLO,
        'VIGENTE', CURRENT_DATE BETWEEN C.FECHA_INICIO_CICLO AND C.FECHA_FIN_CICLO
    ) ORDER BY C.FECHA_INICIO_CICLO DESC) INTO LISTA_CICLOS
    FROM TAB_CICLOS_ICA C
    JOIN TAB_VACUNAS V ON V.ID_VACUNA = C.ID_VACUNA
    WHERE C.ESTADO_CICLO = 'ACTIVO';

    IF LISTA_CICLOS IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'No hay ciclos del ICA registrados');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ciclos del ICA', 'DATOS', LISTA_CICLOS);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CREAR UN CICLO DEL ICA (ADMINISTRADOR). SOLO PARA VACUNAS OBLIGATORIAS DEL ICA Y SIN CRUZARSE CON OTRO CICLO DE LA MISMA VACUNA
CREATE OR REPLACE FUNCTION FUN_CREAR_CICLO_ICA_JSON(
    jID_VACUNA TAB_CICLOS_ICA.ID_VACUNA%TYPE,
    jNOM_CICLO TAB_CICLOS_ICA.NOM_CICLO%TYPE,
    jFECHA_INICIO TAB_CICLOS_ICA.FECHA_INICIO_CICLO%TYPE,
    jFECHA_FIN TAB_CICLOS_ICA.FECHA_FIN_CICLO%TYPE,
    jUSUARIO TAB_CICLOS_ICA.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jID_CICLO INTEGER;
BEGIN
    --VALIDACIONES
    IF NOT EXISTS (SELECT 1 FROM TAB_VACUNAS WHERE ID_VACUNA = jID_VACUNA AND OBLIGATORIA_ICA = 'SI' AND ESTADO_VACUNA = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige una vacuna obligatoria del ICA');
        RETURN RETORNO;
    ELSIF jNOM_CICLO IS NULL OR TRIM(jNOM_CICLO) = '' OR LENGTH(TRIM(jNOM_CICLO)) > 80 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre del ciclo, por ejemplo "Primer ciclo 2027"');
        RETURN RETORNO;
    ELSIF jFECHA_INICIO IS NULL OR jFECHA_FIN IS NULL OR jFECHA_FIN < jFECHA_INICIO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha final debe ser igual o posterior a la inicial');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_CICLOS_ICA WHERE ID_VACUNA = jID_VACUNA AND ESTADO_CICLO = 'ACTIVO'
                  AND FECHA_INICIO_CICLO <= jFECHA_FIN AND FECHA_FIN_CICLO >= jFECHA_INICIO) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ese ciclo se cruza con otro de la misma vacuna');
        RETURN RETORNO;
    END IF;

    jID_CICLO := funcion_Retorna_ultmoid('TAB_CICLOS_ICA', 'ID_CICLO');
    INSERT INTO TAB_CICLOS_ICA (ID_CICLO, ID_VACUNA, NOM_CICLO, FECHA_INICIO_CICLO, FECHA_FIN_CICLO, USUARIO_CREACION)
    VALUES (jID_CICLO, jID_VACUNA, regexp_replace(TRIM(jNOM_CICLO), '\s+', ' ', 'g'), jFECHA_INICIO, jFECHA_FIN, jUSUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ciclo creado', 'DATOS', json_build_object('ID_CICLO', jID_CICLO));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al crear el ciclo');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ANULAR UN CICLO DEL ICA (ADMINISTRADOR)
CREATE OR REPLACE FUNCTION FUN_ANULAR_CICLO_ICA_JSON(
    jID_CICLO TAB_CICLOS_ICA.ID_CICLO%TYPE,
    jUSUARIO TAB_CICLOS_ICA.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    UPDATE TAB_CICLOS_ICA
    SET ESTADO_CICLO = 'ANULADO',
        USUARIO_MODIFICACION = jUSUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_CICLO = jID_CICLO AND ESTADO_CICLO = 'ACTIVO';

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ciclo anulado');
    ELSE
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El ciclo no existe o ya estaba anulado');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_LOTES/FUN_TAB_LOTES.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_LOTES -------------------------------------------------------------------------------------------------------------------
-- LOS LOTES SE PUEDEN CREAR SIN SEÑAL: EL CELULAR GENERA EL UUID Y LA FUNCION ES IDEMPOTENTE (SI EL UUID YA EXISTE, NO DUPLICA)
-- CREAR Y EDITAR: DUEÑO Y VAQUERO PUEDEN CREAR; SOLO EL DUEÑO EDITA Y ANULA



-- FUNCION PARA CREAR UN LOTE
CREATE OR REPLACE FUNCTION FUN_CREAR_LOTE_JSON(
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE,
    jID_FINCA TAB_LOTES.ID_FINCA%TYPE,
    jNOM_LOTE TAB_LOTES.NOM_LOTE%TYPE,
    jID_USUARIO TAB_LOTES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_LOTE INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_LOTE INTO jID_LOTE FROM TAB_LOTES WHERE UUID_LOTE = jUUID_LOTE;
    IF jID_LOTE IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El lote ya estaba guardado',
            'DATOS', json_build_object('ID_LOTE', jID_LOTE, 'UUID_LOTE', jUUID_LOTE, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO Y LOS DATOS
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VAQUERO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_LOTE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del lote');
        RETURN RETORNO;
    ELSIF jNOM_LOTE IS NULL OR TRIM(jNOM_LOTE) = '' OR LENGTH(TRIM(jNOM_LOTE)) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre del lote (máximo 60 caracteres)');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_LOTES WHERE ID_FINCA = jID_FINCA AND LOWER(NOM_LOTE) = LOWER(TRIM(jNOM_LOTE)) AND ESTADO_LOTE = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya hay un lote con ese nombre');
        RETURN RETORNO;
    END IF;

    --INSERTAR EL LOTE
    jID_LOTE := funcion_Retorna_ultmoid('TAB_LOTES', 'ID_LOTE');
    INSERT INTO TAB_LOTES (ID_LOTE, UUID_LOTE, ID_FINCA, NOM_LOTE, USUARIO_CREACION)
    VALUES (jID_LOTE, jUUID_LOTE, jID_FINCA, regexp_replace(TRIM(jNOM_LOTE), '\s+', ' ', 'g'), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Lote creado',
            'DATOS', json_build_object('ID_LOTE', jID_LOTE, 'UUID_LOTE', jUUID_LOTE, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al crear el lote');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CAMBIAR EL NOMBRE DE UN LOTE (SOLO EL DUEÑO)
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_LOTE_JSON(
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE,
    jID_FINCA TAB_LOTES.ID_FINCA%TYPE,
    jNOM_LOTE TAB_LOTES.NOM_LOTE%TYPE,
    jID_USUARIO TAB_LOTES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_LOTE INTEGER;
BEGIN
    --VALIDAR EL ACCESO Y LOS DATOS
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_LOTE := FUN_ID_LOTE_POR_UUID(jID_FINCA, jUUID_LOTE);
    IF jID_LOTE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El lote no existe en esta finca');
        RETURN RETORNO;
    ELSIF jNOM_LOTE IS NULL OR TRIM(jNOM_LOTE) = '' OR LENGTH(TRIM(jNOM_LOTE)) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre del lote (máximo 60 caracteres)');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_LOTES WHERE ID_FINCA = jID_FINCA AND LOWER(NOM_LOTE) = LOWER(TRIM(jNOM_LOTE)) AND ESTADO_LOTE = 'ACTIVO' AND ID_LOTE <> jID_LOTE) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya hay un lote con ese nombre');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_LOTES
    SET NOM_LOTE = regexp_replace(TRIM(jNOM_LOTE), '\s+', ' ', 'g'),
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_LOTE = jID_LOTE;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Lote actualizado');
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al actualizar el lote');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ANULAR UN LOTE (SOLO EL DUEÑO). SUS ANIMALES QUEDAN SIN LOTE Y, SI ESTABA EN UN POTRERO, SALE DE EL HOY
-- DOS DML: BLOQUE BEGIN ... EXCEPTION. SI YA ESTABA ANULADO RESPONDE 200 CON YA_EXISTIA (REINTENTO SEGURO)
CREATE OR REPLACE FUNCTION FUN_ANULAR_LOTE_JSON(
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE,
    jID_FINCA TAB_LOTES.ID_FINCA%TYPE,
    jID_USUARIO TAB_LOTES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_LOTE INTEGER;
    jESTADO VARCHAR;
BEGIN
    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT ID_LOTE, ESTADO_LOTE INTO jID_LOTE, jESTADO FROM TAB_LOTES WHERE UUID_LOTE = jUUID_LOTE AND ID_FINCA = jID_FINCA;
    IF jID_LOTE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El lote no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El lote ya estaba anulado', 'DATOS', json_build_object('YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    BEGIN
        --LOS ANIMALES DEL LOTE QUEDAN SIN LOTE (PUEDE QUE NO HAYA NINGUNO: NO SE REVISA FOUND)
        UPDATE TAB_ANIMALES
        SET ID_LOTE = NULL,
            USUARIO_MODIFICACION = jID_USUARIO,
            FECHA_MODIFICACION = NOW()
        WHERE ID_LOTE = jID_LOTE;

        --SI ESTABA EN UN POTRERO, SALE HOY (FASE 5A; PUEDE QUE NO ESTE EN NINGUNO: NO SE REVISA FOUND)
        UPDATE TAB_OCUPACIONES
        SET FECHA_SALIDA_OCUPACION = GREATEST(LOCALTIMESTAMP, FECHA_EVENTO),
            USUARIO_MODIFICACION = jID_USUARIO,
            FECHA_MODIFICACION = NOW()
        WHERE ID_LOTE = jID_LOTE AND FECHA_SALIDA_OCUPACION IS NULL AND ESTADO_OCUPACION = 'ACTIVO';

        --ANULAR EL LOTE
        UPDATE TAB_LOTES
        SET ESTADO_LOTE = 'ANULADO',
            USUARIO_MODIFICACION = jID_USUARIO,
            FECHA_MODIFICACION = NOW()
        WHERE ID_LOTE = jID_LOTE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No se pudo anular el lote';
        END IF;

        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Lote anulado: sus animales quedaron sin lote', 'DATOS', json_build_object('YA_EXISTIA', false));
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LOS LOTES ACTIVOS DE LA FINCA CON CUANTOS ANIMALES ACTIVOS TIENE CADA UNO
CREATE OR REPLACE FUNCTION FUN_OBTENER_LOTES_JSON(
    jID_FINCA TAB_LOTES.ID_FINCA%TYPE,
    jID_USUARIO TAB_LOTES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    LISTA_LOTES JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_agg(json_build_object(
        'ID_LOTE', L.ID_LOTE,
        'UUID_LOTE', L.UUID_LOTE,
        'NOM_LOTE', L.NOM_LOTE,
        'ANIMALES_ACTIVOS', (SELECT COUNT(*) FROM TAB_ANIMALES A WHERE A.ID_LOTE = L.ID_LOTE AND A.ESTADO_ANIMAL = 'ACTIVO')
    ) ORDER BY L.NOM_LOTE) INTO LISTA_LOTES
    FROM TAB_LOTES L
    WHERE L.ID_FINCA = jID_FINCA AND L.ESTADO_LOTE = 'ACTIVO';

    IF LISTA_LOTES IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'La finca todavía no tiene lotes');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Lotes de la finca', 'DATOS', LISTA_LOTES);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_ANIMALES/FUN_TAB_ANIMALES.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_ANIMALES ----------------------------------------------------------------------------------------------------------------
-- EL CELULAR SE REFIERE A TODO POR UUID (ANIMAL, LOTE, MADRE, PADRE); LA BASE TRADUCE A LOS ID ENTEROS
-- CREAR: DUEÑO Y VAQUERO. EDITAR, CAMBIAR FOTO Y ANULAR: SOLO EL DUEÑO (EL VAQUERO REGISTRA PERO NO CORRIGE NI ANULA)
-- EDITAR ES "GANA EL ULTIMO QUE SINCRONIZA": SI DOS PERSONAS CAMBIAN LA FICHA, QUEDA LA ULTIMA QUE LLEGA



-- FUNCION QUE ARMA EL JSON DE UN ANIMAL (NULL SI NO EXISTE). LA USAN LA LISTA, LA FICHA Y LA SINCRONIZACION
-- VA CON LOS UUID DE LOTE, MADRE Y PADRE PORQUE EL CELULAR GUARDA TODO POR UUID
CREATE OR REPLACE FUNCTION FUN_DATOS_ANIMAL(
    jID_ANIMAL TAB_ANIMALES.ID_ANIMAL%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    SELECT json_build_object(
        'ID_ANIMAL', A.ID_ANIMAL,
        'UUID_ANIMAL', A.UUID_ANIMAL,
        'UUID_LOTE', L.UUID_LOTE,
        'NOM_LOTE', L.NOM_LOTE,
        'ID_RAZA', A.ID_RAZA,
        'NOM_RAZA', R.NOM_RAZA,
        'CHAPETA_ANIMAL', A.CHAPETA_ANIMAL,
        'NOM_ANIMAL', A.NOM_ANIMAL,
        'SEXO_ANIMAL', A.SEXO_ANIMAL,
        'CATEGORIA_ANIMAL', FUN_CATEGORIA_ANIMAL(A.ID_ANIMAL),
        'FECHA_NACIMIENTO', A.FECHA_NACIMIENTO,
        'FECHA_NACIMIENTO_ESTIMADA', A.FECHA_NACIMIENTO_ESTIMADA,
        'UUID_MADRE', M.UUID_ANIMAL,
        'CHAPETA_MADRE', M.CHAPETA_ANIMAL,
        'UUID_PADRE', P.UUID_ANIMAL,
        'CHAPETA_PADRE', P.CHAPETA_ANIMAL,
        'PADRE_EXTERNO', A.PADRE_EXTERNO,
        'ORIGEN_ANIMAL', A.ORIGEN_ANIMAL,
        'FECHA_INGRESO_ANIMAL', A.FECHA_INGRESO_ANIMAL,
        'FOTO_ANIMAL', A.FOTO_ANIMAL,
        'PESO_ACTUAL_KG', A.PESO_ACTUAL_KG,
        'FECHA_ULTIMO_PESAJE', A.FECHA_ULTIMO_PESAJE,
        'FECHA_SALIDA_ANIMAL', A.FECHA_SALIDA_ANIMAL,
        'ESTADO_ANIMAL', A.ESTADO_ANIMAL,
        'FECHA_MODIFICACION', A.FECHA_MODIFICACION
    ) INTO RETORNO
    FROM TAB_ANIMALES A
    LEFT JOIN TAB_LOTES L ON L.ID_LOTE = A.ID_LOTE
    LEFT JOIN TAB_RAZAS R ON R.ID_RAZA = A.ID_RAZA
    LEFT JOIN TAB_ANIMALES M ON M.ID_ANIMAL = A.ID_MADRE
    LEFT JOIN TAB_ANIMALES P ON P.ID_ANIMAL = A.ID_PADRE
    WHERE A.ID_ANIMAL = jID_ANIMAL;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



--FUNCION PARA VALIDAR LOS DATOS DE UN ANIMAL (jID_ANIMAL NULL AL CREAR)
--LA MADRE Y EL PADRE LLEGAN YA TRADUCIDOS A ID (NULL = NO TIENE). EL ORDEN DE LAS VALIDACIONES ES EL DEL FORMULARIO
CREATE OR REPLACE FUNCTION FUN_VALIDAR_ANIMALES(
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jID_ANIMAL TAB_ANIMALES.ID_ANIMAL%TYPE,
    jID_RAZA TAB_ANIMALES.ID_RAZA%TYPE,
    jCHAPETA TAB_ANIMALES.CHAPETA_ANIMAL%TYPE,
    jNOM_ANIMAL TAB_ANIMALES.NOM_ANIMAL%TYPE,
    jSEXO TAB_ANIMALES.SEXO_ANIMAL%TYPE,
    jFECHA_NACIMIENTO TAB_ANIMALES.FECHA_NACIMIENTO%TYPE,
    jFECHA_NACIMIENTO_ESTIMADA TAB_ANIMALES.FECHA_NACIMIENTO_ESTIMADA%TYPE,
    jID_MADRE TAB_ANIMALES.ID_MADRE%TYPE,
    jID_PADRE TAB_ANIMALES.ID_PADRE%TYPE,
    jPADRE_EXTERNO TAB_ANIMALES.PADRE_EXTERNO%TYPE,
    jORIGEN TAB_ANIMALES.ORIGEN_ANIMAL%TYPE,
    jFECHA_INGRESO TAB_ANIMALES.FECHA_INGRESO_ANIMAL%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jSEXO_MADRE VARCHAR;
    jNACIMIENTO_MADRE DATE;
    jSEXO_PADRE VARCHAR;
BEGIN
    SELECT SEXO_ANIMAL, FECHA_NACIMIENTO INTO jSEXO_MADRE, jNACIMIENTO_MADRE FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_MADRE AND ESTADO_ANIMAL <> 'ANULADO';
    SELECT SEXO_ANIMAL INTO jSEXO_PADRE FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_PADRE AND ESTADO_ANIMAL <> 'ANULADO';

    --VALIDACION VARIABLE ID_RAZA (OPCIONAL)
    IF jID_RAZA IS NOT NULL AND NOT EXISTS (SELECT 1 FROM TAB_RAZAS WHERE ID_RAZA = jID_RAZA) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige una raza de la lista');
        RETURN RETORNO;

    --VALIDACION VARIABLE CHAPETA_ANIMAL (OPCIONAL, UNICA EN LA FINCA)
    ELSIF COALESCE(TRIM(jCHAPETA), '') <> '' AND NOT TRIM(jCHAPETA) ~ '^[A-Za-z0-9-]{1,20}$' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La chapeta solo puede tener letras, números y guiones (máximo 20)');
        RETURN RETORNO;
    ELSIF COALESCE(TRIM(jCHAPETA), '') <> '' AND EXISTS (SELECT 1 FROM TAB_ANIMALES WHERE ID_FINCA = jID_FINCA AND CHAPETA_ANIMAL = UPPER(TRIM(jCHAPETA))
                  AND ESTADO_ANIMAL <> 'ANULADO' AND ID_ANIMAL IS DISTINCT FROM jID_ANIMAL) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La chapeta ' || UPPER(TRIM(jCHAPETA)) || ' ya la tiene otro animal de la finca');
        RETURN RETORNO;

    --VALIDACION VARIABLE NOM_ANIMAL (OPCIONAL)
    ELSIF LENGTH(TRIM(COALESCE(jNOM_ANIMAL, ''))) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El nombre es demasiado largo (máximo 60 caracteres)');
        RETURN RETORNO;
    ELSIF COALESCE(TRIM(jCHAPETA), '') = '' AND COALESCE(TRIM(jNOM_ANIMAL), '') = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe la chapeta o un nombre para reconocer al animal');
        RETURN RETORNO;

    --VALIDACION VARIABLE SEXO_ANIMAL
    ELSIF jSEXO IS NULL OR jSEXO NOT IN ('H', 'M') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige si es hembra o macho');
        RETURN RETORNO;

    --VALIDACION VARIABLE FECHA_NACIMIENTO
    ELSIF jFECHA_NACIMIENTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe la fecha de nacimiento (si no la sabes, una aproximada)');
        RETURN RETORNO;
    ELSIF jFECHA_NACIMIENTO > CURRENT_DATE THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha de nacimiento no puede ser futura');
        RETURN RETORNO;
    ELSIF jFECHA_NACIMIENTO < CURRENT_DATE - INTERVAL '25 years' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Revisa la fecha de nacimiento: el animal tendría más de 25 años');
        RETURN RETORNO;
    ELSIF jFECHA_NACIMIENTO_ESTIMADA IS NULL OR jFECHA_NACIMIENTO_ESTIMADA NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Indica si la fecha de nacimiento es aproximada (SI o NO)');
        RETURN RETORNO;

    --VALIDACION DE LA MADRE (HEMBRA DE LA FINCA, AL MENOS 15 MESES MAYOR)
    ELSIF jID_MADRE IS NOT NULL AND jSEXO_MADRE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La madre no existe en esta finca');
        RETURN RETORNO;
    ELSIF jID_MADRE IS NOT NULL AND jSEXO_MADRE <> 'H' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La madre debe ser una hembra');
        RETURN RETORNO;
    ELSIF jID_MADRE IS NOT NULL AND jNACIMIENTO_MADRE > jFECHA_NACIMIENTO - INTERVAL '15 months' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La madre es demasiado joven para ser la madre de este animal');
        RETURN RETORNO;
    ELSIF jID_MADRE IS NOT NULL AND jID_MADRE = jID_ANIMAL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Un animal no puede ser su propia madre');
        RETURN RETORNO;

    --VALIDACION DEL PADRE (MACHO DE LA FINCA O TEXTO LIBRE, NO LOS DOS)
    ELSIF jID_PADRE IS NOT NULL AND jSEXO_PADRE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El padre no existe en esta finca');
        RETURN RETORNO;
    ELSIF jID_PADRE IS NOT NULL AND jSEXO_PADRE <> 'M' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El padre debe ser un macho');
        RETURN RETORNO;
    ELSIF jID_PADRE IS NOT NULL AND jID_PADRE = jID_ANIMAL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Un animal no puede ser su propio padre');
        RETURN RETORNO;
    ELSIF jID_PADRE IS NOT NULL AND COALESCE(TRIM(jPADRE_EXTERNO), '') <> '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige el padre de la finca o escribe el de afuera, no los dos');
        RETURN RETORNO;
    ELSIF LENGTH(TRIM(COALESCE(jPADRE_EXTERNO, ''))) > 80 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El padre de afuera es demasiado largo (máximo 80 caracteres)');
        RETURN RETORNO;

    --VALIDACION DEL ORIGEN Y LA FECHA DE INGRESO
    ELSIF jORIGEN IS NULL OR jORIGEN NOT IN ('NACIDO', 'COMPRADO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Indica si nació en la finca o fue comprado');
        RETURN RETORNO;
    ELSIF jORIGEN = 'COMPRADO' AND jFECHA_INGRESO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe la fecha en que llegó a la finca');
        RETURN RETORNO;
    ELSIF jORIGEN = 'COMPRADO' AND (jFECHA_INGRESO < jFECHA_NACIMIENTO OR jFECHA_INGRESO > CURRENT_DATE) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha de llegada debe estar entre el nacimiento y hoy');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CREAR UN ANIMAL (NACIDO EN LA FINCA SIN PARTO REGISTRADO, O COMPRADO). LAS CRIAS DE UN PARTO LAS CREA FUN_CREAR_PARTO_JSON
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_ANIMAL_JSON(
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE,
    jID_RAZA TAB_ANIMALES.ID_RAZA%TYPE,
    jCHAPETA TAB_ANIMALES.CHAPETA_ANIMAL%TYPE,
    jNOM_ANIMAL TAB_ANIMALES.NOM_ANIMAL%TYPE,
    jSEXO TAB_ANIMALES.SEXO_ANIMAL%TYPE,
    jFECHA_NACIMIENTO TAB_ANIMALES.FECHA_NACIMIENTO%TYPE,
    jFECHA_NACIMIENTO_ESTIMADA TAB_ANIMALES.FECHA_NACIMIENTO_ESTIMADA%TYPE,
    jUUID_MADRE TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jUUID_PADRE TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jPADRE_EXTERNO TAB_ANIMALES.PADRE_EXTERNO%TYPE,
    jORIGEN TAB_ANIMALES.ORIGEN_ANIMAL%TYPE,
    jFECHA_INGRESO TAB_ANIMALES.FECHA_INGRESO_ANIMAL%TYPE,
    jID_USUARIO TAB_ANIMALES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ANIMAL INTEGER;
    jID_LOTE INTEGER;
    jID_MADRE INTEGER;
    jID_PADRE INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_ANIMAL INTO jID_ANIMAL FROM TAB_ANIMALES WHERE UUID_ANIMAL = jUUID_ANIMAL;
    IF jID_ANIMAL IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El animal ya estaba guardado',
            'DATOS', json_build_object('ID_ANIMAL', jID_ANIMAL, 'UUID_ANIMAL', jUUID_ANIMAL, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VAQUERO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_ANIMAL IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del animal');
        RETURN RETORNO;
    END IF;

    --TRADUCIR LOS UUID A ID
    jID_LOTE := FUN_ID_LOTE_POR_UUID(jID_FINCA, jUUID_LOTE);
    jID_MADRE := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_MADRE);
    jID_PADRE := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_PADRE);
    IF jUUID_LOTE IS NOT NULL AND jID_LOTE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El lote no existe en esta finca');
        RETURN RETORNO;
    ELSIF jUUID_MADRE IS NOT NULL AND jID_MADRE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La madre no existe en esta finca');
        RETURN RETORNO;
    ELSIF jUUID_PADRE IS NOT NULL AND jID_PADRE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El padre no existe en esta finca');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jVALIDACION := FUN_VALIDAR_ANIMALES(jID_FINCA, NULL, jID_RAZA, jCHAPETA, jNOM_ANIMAL, jSEXO, jFECHA_NACIMIENTO, COALESCE(jFECHA_NACIMIENTO_ESTIMADA, 'NO'),
        jID_MADRE, jID_PADRE, jPADRE_EXTERNO, jORIGEN, jFECHA_INGRESO);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL ANIMAL (NACIDO EN LA FINCA: INGRESA EL DIA QUE NACE)
    jID_ANIMAL := funcion_Retorna_ultmoid('TAB_ANIMALES', 'ID_ANIMAL');
    INSERT INTO TAB_ANIMALES (ID_ANIMAL, UUID_ANIMAL, ID_FINCA, ID_LOTE, ID_RAZA, CHAPETA_ANIMAL, NOM_ANIMAL, SEXO_ANIMAL, FECHA_NACIMIENTO,
        FECHA_NACIMIENTO_ESTIMADA, ID_MADRE, ID_PADRE, PADRE_EXTERNO, ORIGEN_ANIMAL, FECHA_INGRESO_ANIMAL, USUARIO_CREACION)
    VALUES (jID_ANIMAL, jUUID_ANIMAL, jID_FINCA, jID_LOTE, jID_RAZA, NULLIF(UPPER(TRIM(jCHAPETA)), ''), NULLIF(regexp_replace(TRIM(jNOM_ANIMAL), '\s+', ' ', 'g'), ''),
        jSEXO, jFECHA_NACIMIENTO, COALESCE(jFECHA_NACIMIENTO_ESTIMADA, 'NO'), jID_MADRE, jID_PADRE, NULLIF(TRIM(jPADRE_EXTERNO), ''), jORIGEN,
        CASE WHEN jORIGEN = 'NACIDO' THEN jFECHA_NACIMIENTO ELSE jFECHA_INGRESO END, jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Animal registrado',
            'DATOS', json_build_object('ID_ANIMAL', jID_ANIMAL, 'UUID_ANIMAL', jUUID_ANIMAL, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al registrar el animal');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ACTUALIZAR LA FICHA DE UN ANIMAL (SOLO EL DUEÑO). NO CAMBIA EL ESTADO: ESO LO HACEN LA SALIDA Y LA ANULACION
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_ANIMAL_JSON(
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE,
    jID_RAZA TAB_ANIMALES.ID_RAZA%TYPE,
    jCHAPETA TAB_ANIMALES.CHAPETA_ANIMAL%TYPE,
    jNOM_ANIMAL TAB_ANIMALES.NOM_ANIMAL%TYPE,
    jSEXO TAB_ANIMALES.SEXO_ANIMAL%TYPE,
    jFECHA_NACIMIENTO TAB_ANIMALES.FECHA_NACIMIENTO%TYPE,
    jFECHA_NACIMIENTO_ESTIMADA TAB_ANIMALES.FECHA_NACIMIENTO_ESTIMADA%TYPE,
    jUUID_MADRE TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jUUID_PADRE TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jPADRE_EXTERNO TAB_ANIMALES.PADRE_EXTERNO%TYPE,
    jORIGEN TAB_ANIMALES.ORIGEN_ANIMAL%TYPE,
    jFECHA_INGRESO TAB_ANIMALES.FECHA_INGRESO_ANIMAL%TYPE,
    jID_USUARIO TAB_ANIMALES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ANIMAL INTEGER;
    jESTADO VARCHAR;
    jID_LOTE INTEGER;
    jID_MADRE INTEGER;
    jID_PADRE INTEGER;
BEGIN
    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    SELECT ESTADO_ANIMAL INTO jESTADO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;
    IF jID_ANIMAL IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El animal no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ese animal fue anulado: no se puede editar');
        RETURN RETORNO;
    END IF;

    --TRADUCIR LOS UUID A ID
    jID_LOTE := FUN_ID_LOTE_POR_UUID(jID_FINCA, jUUID_LOTE);
    jID_MADRE := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_MADRE);
    jID_PADRE := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_PADRE);
    IF jUUID_LOTE IS NOT NULL AND jID_LOTE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El lote no existe en esta finca');
        RETURN RETORNO;
    ELSIF jUUID_MADRE IS NOT NULL AND jID_MADRE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La madre no existe en esta finca');
        RETURN RETORNO;
    ELSIF jUUID_PADRE IS NOT NULL AND jID_PADRE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El padre no existe en esta finca');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jVALIDACION := FUN_VALIDAR_ANIMALES(jID_FINCA, jID_ANIMAL, jID_RAZA, jCHAPETA, jNOM_ANIMAL, jSEXO, jFECHA_NACIMIENTO, COALESCE(jFECHA_NACIMIENTO_ESTIMADA, 'NO'),
        jID_MADRE, jID_PADRE, jPADRE_EXTERNO, jORIGEN, jFECHA_INGRESO);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jSEXO = 'M' AND EXISTS (SELECT 1 FROM TAB_PARTOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No se puede cambiar a macho: tiene partos registrados');
        RETURN RETORNO;
    --EL SEXO TAMPOCO CAMBIA SI YA ES MADRE O PADRE DE OTROS ANIMALES, O SI FUE EL TORO DE UN SERVICIO (HALLADO EN LA FASE 1)
    ELSIF jSEXO = 'M' AND EXISTS (SELECT 1 FROM TAB_ANIMALES WHERE ID_MADRE = jID_ANIMAL AND ESTADO_ANIMAL <> 'ANULADO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No se puede cambiar a macho: es la madre de otros animales');
        RETURN RETORNO;
    ELSIF jSEXO = 'H' AND (EXISTS (SELECT 1 FROM TAB_ANIMALES WHERE ID_PADRE = jID_ANIMAL AND ESTADO_ANIMAL <> 'ANULADO')
                        OR EXISTS (SELECT 1 FROM TAB_SERVICIOS WHERE ID_TORO = jID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO')) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No se puede cambiar a hembra: es el padre de otros animales o el toro de un servicio');
        RETURN RETORNO;
    END IF;

    --ACTUALIZAR EL ANIMAL
    UPDATE TAB_ANIMALES
    SET ID_LOTE = jID_LOTE,
        ID_RAZA = jID_RAZA,
        CHAPETA_ANIMAL = NULLIF(UPPER(TRIM(jCHAPETA)), ''),
        NOM_ANIMAL = NULLIF(regexp_replace(TRIM(jNOM_ANIMAL), '\s+', ' ', 'g'), ''),
        SEXO_ANIMAL = jSEXO,
        FECHA_NACIMIENTO = jFECHA_NACIMIENTO,
        FECHA_NACIMIENTO_ESTIMADA = COALESCE(jFECHA_NACIMIENTO_ESTIMADA, 'NO'),
        ID_MADRE = jID_MADRE,
        ID_PADRE = jID_PADRE,
        PADRE_EXTERNO = NULLIF(TRIM(jPADRE_EXTERNO), ''),
        ORIGEN_ANIMAL = jORIGEN,
        FECHA_INGRESO_ANIMAL = CASE WHEN jORIGEN = 'NACIDO' THEN jFECHA_NACIMIENTO ELSE jFECHA_INGRESO END,
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_ANIMAL = jID_ANIMAL;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ficha del animal actualizada');
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al actualizar el animal');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CAMBIAR LA FOTO DE UN ANIMAL (SOLO EL DUEÑO). LAS FOTOS SUBEN APARTE Y DESPUES DE LOS DATOS; AQUI SOLO SE GUARDA EL NOMBRE DEL ARCHIVO
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_FOTO_ANIMAL_JSON(
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jFOTO TAB_ANIMALES.FOTO_ANIMAL%TYPE,
    jID_USUARIO TAB_ANIMALES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ANIMAL INTEGER;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    IF jID_ANIMAL IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El animal no existe en esta finca');
        RETURN RETORNO;
    ELSIF COALESCE(TRIM(jFOTO), '') <> '' AND NOT TRIM(jFOTO) ~ '^[A-Za-z0-9._-]{1,200}$' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Nombre de archivo de foto no válido');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_ANIMALES
    SET FOTO_ANIMAL = NULLIF(TRIM(jFOTO), ''),
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_ANIMAL = jID_ANIMAL;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', CASE WHEN COALESCE(TRIM(jFOTO), '') = '' THEN 'Foto quitada' ELSE 'Foto guardada' END);
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar la foto');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ANULAR UN ANIMAL REGISTRADO POR ERROR (SOLO EL DUEÑO)
-- NO SE ANULA SI TIENE EVENTOS ACTIVOS, CRIAS O SI NACIO DE UN PARTO (EN ESE CASO SE ANULA EL PARTO). PARA LO QUE SE VENDIO O MURIO ESTA LA SALIDA
CREATE OR REPLACE FUNCTION FUN_ANULAR_ANIMAL_JSON(
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jID_USUARIO TAB_ANIMALES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ANIMAL INTEGER;
    jESTADO VARCHAR;
    jEVENTOS INTEGER;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    SELECT ESTADO_ANIMAL INTO jESTADO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;

    --EVENTOS ACTIVOS DEL ANIMAL (COMO PROTAGONISTA O COMO TORO DE UN SERVICIO)
    SELECT (SELECT COUNT(*) FROM TAB_PESAJES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PESAJE = 'ACTIVO')
         + (SELECT COUNT(*) FROM TAB_VACUNACIONES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_VACUNACION = 'ACTIVO')
         + (SELECT COUNT(*) FROM TAB_SERVICIOS WHERE (ID_ANIMAL = jID_ANIMAL OR ID_TORO = jID_ANIMAL) AND ESTADO_SERVICIO = 'ACTIVO')
         + (SELECT COUNT(*) FROM TAB_PALPACIONES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO')
         + (SELECT COUNT(*) FROM TAB_PARTOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PARTO = 'ACTIVO')
         + (SELECT COUNT(*) FROM TAB_ORDENOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_ORDENO = 'ACTIVO')
         + (SELECT COUNT(*) FROM TAB_SALIDAS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_SALIDA = 'ACTIVO')
    INTO jEVENTOS;

    --VALIDACIONES
    IF jID_ANIMAL IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El animal no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El animal ya estaba anulado', 'DATOS', json_build_object('YA_EXISTIA', true));
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_PARTOS WHERE ID_CRIA = jID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Este animal nació de un parto registrado: anula el parto y se anula la cría');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_ANIMALES WHERE (ID_MADRE = jID_ANIMAL OR ID_PADRE = jID_ANIMAL) AND ESTADO_ANIMAL <> 'ANULADO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No se puede anular: es madre o padre de otros animales');
        RETURN RETORNO;
    ELSIF jEVENTOS > 0 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No se puede anular: tiene ' || jEVENTOS || ' registros en su línea de tiempo. Si se vendió o murió, registra la salida');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_ANIMALES
    SET ESTADO_ANIMAL = 'ANULADO',
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_ANIMAL = jID_ANIMAL;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Animal anulado', 'DATOS', json_build_object('YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al anular el animal');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LOS ANIMALES DE LA FINCA (jESTADO: 'ACTIVO' = EL HATO DE HOY, 'TODOS' = TAMBIEN LOS VENDIDOS, MUERTOS Y TRASLADADOS)
CREATE OR REPLACE FUNCTION FUN_OBTENER_ANIMALES_JSON(
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jESTADO VARCHAR,
    jID_USUARIO TAB_ANIMALES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    LISTA_ANIMALES JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_agg(FUN_DATOS_ANIMAL(ID_ANIMAL) ORDER BY ESTADO_ANIMAL, CHAPETA_ANIMAL NULLS LAST, NOM_ANIMAL) INTO LISTA_ANIMALES
    FROM TAB_ANIMALES
    WHERE ID_FINCA = jID_FINCA
      AND ESTADO_ANIMAL <> 'ANULADO'
      AND (COALESCE(jESTADO, 'ACTIVO') = 'TODOS' OR ESTADO_ANIMAL = 'ACTIVO');

    IF LISTA_ANIMALES IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Todavía no hay animales registrados');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Animales de la finca', 'DATOS', LISTA_ANIMALES);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LA FICHA DE UN ANIMAL CON SUS CRIAS
CREATE OR REPLACE FUNCTION FUN_OBTENER_ANIMAL_POR_UUID_JSON(
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_USUARIO TAB_ANIMALES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ANIMAL INTEGER;
    LISTA_CRIAS JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    IF jID_ANIMAL IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El animal no existe en esta finca');
        RETURN RETORNO;
    END IF;

    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', UUID_ANIMAL,
        'CHAPETA_ANIMAL', CHAPETA_ANIMAL,
        'NOM_ANIMAL', NOM_ANIMAL,
        'SEXO_ANIMAL', SEXO_ANIMAL,
        'FECHA_NACIMIENTO', FECHA_NACIMIENTO,
        'ESTADO_ANIMAL', ESTADO_ANIMAL
    ) ORDER BY FECHA_NACIMIENTO DESC) INTO LISTA_CRIAS
    FROM TAB_ANIMALES
    WHERE (ID_MADRE = jID_ANIMAL OR ID_PADRE = jID_ANIMAL) AND ESTADO_ANIMAL <> 'ANULADO';

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ficha del animal',
        'DATOS', json_build_object('ANIMAL', FUN_DATOS_ANIMAL(jID_ANIMAL), 'CRIAS', LISTA_CRIAS));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LA LINEA DE TIEMPO DE UN ANIMAL: TODOS SUS EVENTOS ACTIVOS, DEL MAS NUEVO AL MAS VIEJO, MAS SU NACIMIENTO O LLEGADA
-- SE ARMA CON UNION ALL SOBRE LAS TABLAS DE EVENTOS (SIN CTE). DESCRIPCION_EVENTO YA VIENE EN PALABRAS DEL CAMPO PARA MOSTRARLA TAL CUAL
CREATE OR REPLACE FUNCTION FUN_OBTENER_LINEA_TIEMPO_JSON(
    jID_FINCA TAB_ANIMALES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_USUARIO TAB_ANIMALES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ANIMAL INTEGER;
    LISTA_EVENTOS JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    IF jID_ANIMAL IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El animal no existe en esta finca');
        RETURN RETORNO;
    END IF;

    SELECT json_agg(json_build_object(
        'TIPO_EVENTO', E.TIPO_EVENTO,
        'UUID_EVENTO', E.UUID_EVENTO,
        'FECHA_EVENTO', E.FECHA_EVENTO,
        'DESCRIPCION_EVENTO', E.DESCRIPCION_EVENTO,
        'OBSERVACION_EVENTO', E.OBSERVACION_EVENTO,
        'USUARIO_CREACION', E.USUARIO_CREACION
    ) ORDER BY E.FECHA_EVENTO DESC, E.ORDEN DESC) INTO LISTA_EVENTOS
    FROM (
        SELECT 'NACIMIENTO' AS TIPO_EVENTO, A.UUID_ANIMAL AS UUID_EVENTO, A.FECHA_INGRESO_ANIMAL::TIMESTAMP AS FECHA_EVENTO, 0 AS ORDEN,
            CASE WHEN A.ORIGEN_ANIMAL = 'COMPRADO' THEN 'Llegó a la finca (comprado)' ELSE 'Nació en la finca' END AS DESCRIPCION_EVENTO,
            NULL::VARCHAR AS OBSERVACION_EVENTO, A.USUARIO_CREACION
        FROM TAB_ANIMALES A WHERE A.ID_ANIMAL = jID_ANIMAL
        UNION ALL
        SELECT 'PESAJE', UUID_PESAJE, FECHA_EVENTO, 1,
            'Pesó ' || trim(to_char(PESO_KG, 'FM9990.0')) || ' kg' || CASE WHEN ESTIMADO_CINTA = 'SI' THEN ' (estimado con cinta)' ELSE '' END,
            OBSERVACION_PESAJE, USUARIO_CREACION
        FROM TAB_PESAJES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PESAJE = 'ACTIVO'
        UNION ALL
        SELECT 'VACUNACION', VC.UUID_VACUNACION, VC.FECHA_EVENTO, 1,
            CASE V.TIPO_VACUNA WHEN 'VACUNA' THEN 'Vacunada: ' WHEN 'DESPARASITANTE' THEN 'Desparasitada: ' ELSE 'Tratamiento: ' END || V.NOM_VACUNA
                || CASE WHEN VC.FECHA_FIN_RETIRO > VC.FECHA_EVENTO::DATE THEN ' · sin vender leche hasta el ' || to_char(VC.FECHA_FIN_RETIRO, 'DD/MM/YYYY') ELSE '' END,
            VC.OBSERVACION_VACUNACION, VC.USUARIO_CREACION
        FROM TAB_VACUNACIONES VC JOIN TAB_VACUNAS V ON V.ID_VACUNA = VC.ID_VACUNA
        WHERE VC.ID_ANIMAL = jID_ANIMAL AND VC.ESTADO_VACUNACION = 'ACTIVO'
        UNION ALL
        SELECT 'SERVICIO', S.UUID_SERVICIO, S.FECHA_EVENTO, 2,
            CASE WHEN S.TIPO_SERVICIO = 'MONTA' THEN 'Monta' ELSE 'Inseminación' END
                || COALESCE(' con ' || COALESCE(T.CHAPETA_ANIMAL, T.NOM_ANIMAL), ' con ' || S.TORO_EXTERNO, ''),
            S.OBSERVACION_SERVICIO, S.USUARIO_CREACION
        FROM TAB_SERVICIOS S LEFT JOIN TAB_ANIMALES T ON T.ID_ANIMAL = S.ID_TORO
        WHERE S.ID_ANIMAL = jID_ANIMAL AND S.ESTADO_SERVICIO = 'ACTIVO'
        UNION ALL
        SELECT 'PALPACION', UUID_PALPACION, FECHA_EVENTO, 3,
            CASE WHEN RESULTADO_PALPACION = 'PRENIADA' THEN 'Palpada: preñada de ' || MESES_GESTACION || CASE WHEN MESES_GESTACION = 1 THEN ' mes' ELSE ' meses' END ELSE 'Palpada: vacía' END,
            OBSERVACION_PALPACION, USUARIO_CREACION
        FROM TAB_PALPACIONES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO'
        UNION ALL
        SELECT 'PARTO', P.UUID_PARTO, P.FECHA_EVENTO, 4,
            CASE WHEN P.TIPO_PARTO = 'ABORTO' THEN 'Abortó'
                 ELSE 'Parió' || CASE WHEN P.SEXO_CRIA = 'H' THEN ' una ternera' WHEN P.SEXO_CRIA = 'M' THEN ' un ternero' ELSE '' END
                      || CASE WHEN P.CRIA_VIVA = 'NO' THEN ' muerta' ELSE '' END
                      || COALESCE(' (' || C.CHAPETA_ANIMAL || ')', '')
                      || CASE WHEN P.TIPO_PARTO IN ('ASISTIDO', 'CESAREA') THEN ' · parto ' || LOWER(P.TIPO_PARTO) ELSE '' END END,
            P.OBSERVACION_PARTO, P.USUARIO_CREACION
        FROM TAB_PARTOS P LEFT JOIN TAB_ANIMALES C ON C.ID_ANIMAL = P.ID_CRIA
        WHERE P.ID_ANIMAL = jID_ANIMAL AND P.ESTADO_PARTO = 'ACTIVO'
        UNION ALL
        SELECT 'ORDENO', UUID_ORDENO, FECHA_EVENTO, 1,
            'Ordeño de la ' || CASE WHEN JORNADA_ORDENO = 'MANANA' THEN 'mañana' ELSE 'tarde' END || ': ' || trim(to_char(LITROS_ORDENO, 'FM990.0')) || ' litros',
            OBSERVACION_ORDENO, USUARIO_CREACION
        FROM TAB_ORDENOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_ORDENO = 'ACTIVO'
        UNION ALL
        SELECT 'SALIDA', UUID_SALIDA, FECHA_EVENTO, 9,
            CASE TIPO_SALIDA WHEN 'VENTA' THEN 'Se vendió' || COALESCE(' por $' || trim(to_char(VALOR_SALIDA, 'FM999G999G999G990')), '')
                             WHEN 'MUERTE' THEN 'Murió' || COALESCE(': ' || CAUSA_SALIDA, '')
                             ELSE 'Salió de la finca (traslado)' END,
            OBSERVACION_SALIDA, USUARIO_CREACION
        FROM TAB_SALIDAS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_SALIDA = 'ACTIVO'
    ) E;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Línea de tiempo', 'DATOS', LISTA_EVENTOS);
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_PESAJES/FUN_TAB_PESAJES.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_PESAJES -----------------------------------------------------------------------------------------------------------------
-- ES EL EVENTO CON EL QUE SE PRUEBA EL MOTOR DE SINCRONIZACION EN LA FASE 0
-- TODOS LOS ROLES DE LA FINCA PUEDEN PESAR. EL PESO ACTUAL DEL ANIMAL LO MANTIENE EL TRIGGER TRG_PESO_ACTUAL



-- FUNCION QUE ESTIMA EL PESO CON EL PERIMETRO TORACICO (CINTA). FORMULA DE QUETELET: KILOS = (PERIMETRO EN METROS)³ × COEFICIENTE_CINTA
-- ES UNA ESTIMACION: EL PESAJE QUEDA MARCADO CON ESTIMADO_CINTA = 'SI'
CREATE OR REPLACE FUNCTION FUN_PESO_POR_CINTA(
    jPERIMETRO_CM TAB_PESAJES.PERIMETRO_CM%TYPE
) RETURNS NUMERIC AS
$$
BEGIN
    IF jPERIMETRO_CM IS NULL OR jPERIMETRO_CM <= 0 THEN
        RETURN NULL;
    END IF;
    RETURN round(power(jPERIMETRO_CM / 100.0, 3) * COALESCE(FUN_CONFIGURACION_NUMERO('COEFICIENTE_CINTA'), 80), 1);
END;
$$ LANGUAGE plpgsql;



--FUNCION PARA VALIDAR LOS DATOS DE UN PESAJE
CREATE OR REPLACE FUNCTION FUN_VALIDAR_PESAJES(
    jID_ANIMAL TAB_PESAJES.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_PESAJES.FECHA_EVENTO%TYPE,
    jPESO_KG TAB_PESAJES.PESO_KG%TYPE,
    jESTIMADO_CINTA TAB_PESAJES.ESTIMADO_CINTA%TYPE,
    jPERIMETRO_CM TAB_PESAJES.PERIMETRO_CM%TYPE,
    jOBSERVACION TAB_PESAJES.OBSERVACION_PESAJE%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;

    --VALIDACION VARIABLE ESTIMADO_CINTA Y PERIMETRO_CM
    ELSIF jESTIMADO_CINTA IS NULL OR jESTIMADO_CINTA NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Indica si el peso es con báscula o con cinta');
        RETURN RETORNO;
    ELSIF jESTIMADO_CINTA = 'SI' AND (jPERIMETRO_CM IS NULL OR jPERIMETRO_CM < 50 OR jPERIMETRO_CM > 300) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Con cinta, escribe el perímetro del pecho en centímetros (de 50 a 300)');
        RETURN RETORNO;

    --VALIDACION VARIABLE PESO_KG
    ELSIF jPESO_KG IS NULL OR jPESO_KG <= 0 OR jPESO_KG > 1500 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe un peso entre 1 y 1500 kilos');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR UN PESAJE. CON CINTA Y SIN PESO, EL PESO SE CALCULA CON EL PERIMETRO
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_PESAJE_JSON(
    jUUID_PESAJE TAB_PESAJES.UUID_PESAJE%TYPE,
    jID_FINCA TAB_PESAJES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jPESO_KG TAB_PESAJES.PESO_KG%TYPE,
    jESTIMADO_CINTA TAB_PESAJES.ESTIMADO_CINTA%TYPE,
    jPERIMETRO_CM TAB_PESAJES.PERIMETRO_CM%TYPE,
    jFECHA_EVENTO TAB_PESAJES.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_PESAJES.OBSERVACION_PESAJE%TYPE,
    jID_USUARIO TAB_PESAJES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_PESAJE INTEGER;
    jID_ANIMAL INTEGER;
    jPESO NUMERIC;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_PESAJE INTO jID_PESAJE FROM TAB_PESAJES WHERE UUID_PESAJE = jUUID_PESAJE;
    IF jID_PESAJE IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El pesaje ya estaba guardado',
            'DATOS', json_build_object('ID_PESAJE', jID_PESAJE, 'UUID_PESAJE', jUUID_PESAJE, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_PESAJE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del pesaje');
        RETURN RETORNO;
    END IF;

    --TRADUCIR EL ANIMAL Y CALCULAR EL PESO CON CINTA SI NO VINO
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jPESO := CASE WHEN jESTIMADO_CINTA = 'SI' AND jPESO_KG IS NULL THEN FUN_PESO_POR_CINTA(jPERIMETRO_CM) ELSE jPESO_KG END;

    --LLAMAR A LA FUNCION DE VALIDACION
    jVALIDACION := FUN_VALIDAR_PESAJES(jID_ANIMAL, jFECHA_EVENTO, jPESO, COALESCE(jESTIMADO_CINTA, 'NO'), jPERIMETRO_CM, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL PESAJE (EL TRIGGER TRG_PESO_ACTUAL ACTUALIZA EL PESO DEL ANIMAL)
    jID_PESAJE := funcion_Retorna_ultmoid('TAB_PESAJES', 'ID_PESAJE');
    INSERT INTO TAB_PESAJES (ID_PESAJE, UUID_PESAJE, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, PESO_KG, ESTIMADO_CINTA, PERIMETRO_CM, OBSERVACION_PESAJE, USUARIO_CREACION)
    VALUES (jID_PESAJE, jUUID_PESAJE, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jPESO, COALESCE(jESTIMADO_CINTA, 'NO'),
        CASE WHEN jESTIMADO_CINTA = 'SI' THEN jPERIMETRO_CM END, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Pesaje guardado: ' || trim(to_char(jPESO, 'FM9990.0')) || ' kg',
            'DATOS', json_build_object('ID_PESAJE', jID_PESAJE, 'UUID_PESAJE', jUUID_PESAJE, 'PESO_KG', jPESO, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar el pesaje');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_VACUNACIONES/FUN_TAB_VACUNACIONES.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_VACUNACIONES ------------------------------------------------------------------------------------------------------------
-- VACUNAS, TRATAMIENTOS Y DESPARASITANTES. LA PROXIMA DOSIS Y EL FIN DEL RETIRO DE LECHE SE CALCULAN CON EL CATALOGO Y QUEDAN GUARDADOS
-- (SI EL ADMINISTRADOR CAMBIA EL CATALOGO DESPUES, LO YA REGISTRADO CONSERVA SUS FECHAS)



--FUNCION PARA VALIDAR LOS DATOS DE UNA VACUNACION
CREATE OR REPLACE FUNCTION FUN_VALIDAR_VACUNACIONES(
    jID_ANIMAL TAB_VACUNACIONES.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_VACUNACIONES.FECHA_EVENTO%TYPE,
    jID_VACUNA TAB_VACUNACIONES.ID_VACUNA%TYPE,
    jDOSIS TAB_VACUNACIONES.DOSIS_VACUNACION%TYPE,
    jOBSERVACION TAB_VACUNACIONES.OBSERVACION_VACUNACION%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;

    --VALIDACION VARIABLE ID_VACUNA
    ELSIF jID_VACUNA IS NULL OR NOT EXISTS (SELECT 1 FROM TAB_VACUNAS WHERE ID_VACUNA = jID_VACUNA AND ESTADO_VACUNA = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige la vacuna o el producto de la lista');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_VACUNACIONES WHERE ID_ANIMAL = jID_ANIMAL AND ID_VACUNA = jID_VACUNA
                  AND FECHA_EVENTO::DATE = jFECHA_EVENTO::DATE AND ESTADO_VACUNACION = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ese producto ya se le registró a ' || FUN_ETIQUETA_ANIMAL(jID_ANIMAL) || ' ese mismo día');
        RETURN RETORNO;

    --VALIDACION VARIABLE DOSIS (OPCIONAL)
    ELSIF LENGTH(TRIM(COALESCE(jDOSIS, ''))) > 40 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La dosis es demasiado larga (máximo 40 caracteres)');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR UNA VACUNACION O TRATAMIENTO
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_VACUNACION_JSON(
    jUUID_VACUNACION TAB_VACUNACIONES.UUID_VACUNACION%TYPE,
    jID_FINCA TAB_VACUNACIONES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jID_VACUNA TAB_VACUNACIONES.ID_VACUNA%TYPE,
    jDOSIS TAB_VACUNACIONES.DOSIS_VACUNACION%TYPE,
    jFECHA_EVENTO TAB_VACUNACIONES.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_VACUNACIONES.OBSERVACION_VACUNACION%TYPE,
    jID_USUARIO TAB_VACUNACIONES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_VACUNACION INTEGER;
    jID_ANIMAL INTEGER;
    jDIAS_REFUERZO INTEGER;
    jDIAS_RETIRO INTEGER;
    jPROXIMA DATE;
    jFIN_RETIRO DATE;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_VACUNACION INTO jID_VACUNACION FROM TAB_VACUNACIONES WHERE UUID_VACUNACION = jUUID_VACUNACION;
    IF jID_VACUNACION IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'La vacunación ya estaba guardada',
            'DATOS', json_build_object('ID_VACUNACION', jID_VACUNACION, 'UUID_VACUNACION', jUUID_VACUNACION, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_VACUNACION IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID de la vacunación');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jVALIDACION := FUN_VALIDAR_VACUNACIONES(jID_ANIMAL, jFECHA_EVENTO, jID_VACUNA, jDOSIS, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --CALCULAR LA PROXIMA DOSIS Y EL FIN DEL RETIRO DE LECHE CON EL CATALOGO
    SELECT DIAS_REFUERZO, DIAS_RETIRO_LECHE INTO jDIAS_REFUERZO, jDIAS_RETIRO FROM TAB_VACUNAS WHERE ID_VACUNA = jID_VACUNA;
    jPROXIMA := CASE WHEN jDIAS_REFUERZO IS NOT NULL THEN jFECHA_EVENTO::DATE + jDIAS_REFUERZO END;
    jFIN_RETIRO := CASE WHEN jDIAS_RETIRO > 0 THEN jFECHA_EVENTO::DATE + jDIAS_RETIRO END;

    --INSERTAR LA VACUNACION
    jID_VACUNACION := funcion_Retorna_ultmoid('TAB_VACUNACIONES', 'ID_VACUNACION');
    INSERT INTO TAB_VACUNACIONES (ID_VACUNACION, UUID_VACUNACION, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, ID_VACUNA, DOSIS_VACUNACION,
        FECHA_PROXIMA_DOSIS, FECHA_FIN_RETIRO, OBSERVACION_VACUNACION, USUARIO_CREACION)
    VALUES (jID_VACUNACION, jUUID_VACUNACION, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jID_VACUNA, NULLIF(TRIM(jDOSIS), ''),
        jPROXIMA, jFIN_RETIRO, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Vacunación guardada'
                || CASE WHEN jFIN_RETIRO IS NOT NULL THEN '. No vender su leche hasta el ' || to_char(jFIN_RETIRO, 'DD/MM/YYYY') ELSE '' END,
            'DATOS', json_build_object('ID_VACUNACION', jID_VACUNACION, 'UUID_VACUNACION', jUUID_VACUNACION,
                'FECHA_PROXIMA_DOSIS', jPROXIMA, 'FECHA_FIN_RETIRO', jFIN_RETIRO, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar la vacunación');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_SERVICIOS/FUN_TAB_SERVICIOS.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_SERVICIOS ---------------------------------------------------------------------------------------------------------------
-- MONTA (CON UN TORO DE LA FINCA O UNO DE AFUERA) O INSEMINACION (LA PAJILLA VA EN TORO_EXTERNO)
-- EL PARTO PROBABLE ES FECHA DEL SERVICIO + DIAS_GESTACION (TAB_CONFIGURACION); LO USAN LA PANTALLA "HOY" Y LAS ALERTAS (FASE 3)



--FUNCION PARA VALIDAR LOS DATOS DE UN SERVICIO (EL TORO LLEGA YA TRADUCIDO A ID)
CREATE OR REPLACE FUNCTION FUN_VALIDAR_SERVICIOS(
    jID_ANIMAL TAB_SERVICIOS.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_SERVICIOS.FECHA_EVENTO%TYPE,
    jTIPO_SERVICIO TAB_SERVICIOS.TIPO_SERVICIO%TYPE,
    jID_TORO TAB_SERVICIOS.ID_TORO%TYPE,
    jTORO_EXTERNO TAB_SERVICIOS.TORO_EXTERNO%TYPE,
    jOBSERVACION TAB_SERVICIOS.OBSERVACION_SERVICIO%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jSEXO VARCHAR;
    jNACIMIENTO DATE;
    jSEXO_TORO VARCHAR;
    jESTADO_TORO VARCHAR;
    jMESES_MINIMOS INTEGER;
BEGIN
    SELECT SEXO_ANIMAL, FECHA_NACIMIENTO INTO jSEXO, jNACIMIENTO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;
    SELECT SEXO_ANIMAL, ESTADO_ANIMAL INTO jSEXO_TORO, jESTADO_TORO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_TORO;
    jMESES_MINIMOS := COALESCE(FUN_CONFIGURACION_NUMERO('MESES_MINIMOS_SERVICIO'), 12)::INTEGER;

    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;

    --LA HEMBRA
    ELSIF jSEXO <> 'H' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El servicio se registra a una hembra');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO::DATE < jNACIMIENTO + make_interval(months => jMESES_MINIMOS) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', upper(left(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 1)) || substr(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 2)
            || ' tenía menos de ' || jMESES_MINIMOS || ' meses en esa fecha');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_SERVICIOS WHERE ID_ANIMAL = jID_ANIMAL AND FECHA_EVENTO::DATE = jFECHA_EVENTO::DATE AND ESTADO_SERVICIO = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya hay un servicio de ' || FUN_ETIQUETA_ANIMAL(jID_ANIMAL) || ' ese mismo día');
        RETURN RETORNO;

    --VALIDACION VARIABLE TIPO_SERVICIO
    ELSIF jTIPO_SERVICIO IS NULL OR jTIPO_SERVICIO NOT IN ('MONTA', 'INSEMINACION') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige si fue monta o inseminación');
        RETURN RETORNO;

    --EL TORO: DE LA FINCA (MACHO, NO ANULADO) O DE AFUERA, NO LOS DOS. LA INSEMINACION LLEVA LA PAJILLA
    ELSIF jID_TORO IS NOT NULL AND COALESCE(TRIM(jTORO_EXTERNO), '') <> '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige el toro de la finca o escribe el de afuera, no los dos');
        RETURN RETORNO;
    ELSIF jID_TORO IS NOT NULL AND (jSEXO_TORO <> 'M' OR jESTADO_TORO = 'ANULADO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El toro elegido no es un macho de la finca');
        RETURN RETORNO;
    ELSIF jTIPO_SERVICIO = 'INSEMINACION' AND jID_TORO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'En la inseminación escribe la pajilla (toro de afuera)');
        RETURN RETORNO;
    ELSIF jTIPO_SERVICIO = 'INSEMINACION' AND COALESCE(TRIM(jTORO_EXTERNO), '') = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe la pajilla o el toro de la inseminación');
        RETURN RETORNO;
    ELSIF LENGTH(TRIM(COALESCE(jTORO_EXTERNO, ''))) > 80 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El toro de afuera es demasiado largo (máximo 80 caracteres)');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR UN SERVICIO (MONTA O INSEMINACION)
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_SERVICIO_JSON(
    jUUID_SERVICIO TAB_SERVICIOS.UUID_SERVICIO%TYPE,
    jID_FINCA TAB_SERVICIOS.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jTIPO_SERVICIO TAB_SERVICIOS.TIPO_SERVICIO%TYPE,
    jUUID_TORO TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jTORO_EXTERNO TAB_SERVICIOS.TORO_EXTERNO%TYPE,
    jFECHA_EVENTO TAB_SERVICIOS.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_SERVICIOS.OBSERVACION_SERVICIO%TYPE,
    jID_USUARIO TAB_SERVICIOS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_SERVICIO INTEGER;
    jID_ANIMAL INTEGER;
    jID_TORO INTEGER;
    jPARTO_PROBABLE DATE;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_SERVICIO INTO jID_SERVICIO FROM TAB_SERVICIOS WHERE UUID_SERVICIO = jUUID_SERVICIO;
    IF jID_SERVICIO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El servicio ya estaba guardado',
            'DATOS', json_build_object('ID_SERVICIO', jID_SERVICIO, 'UUID_SERVICIO', jUUID_SERVICIO, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_SERVICIO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del servicio');
        RETURN RETORNO;
    END IF;

    --TRADUCIR LOS UUID
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jID_TORO := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_TORO);
    IF jUUID_TORO IS NOT NULL AND jID_TORO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El toro no existe en esta finca');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jVALIDACION := FUN_VALIDAR_SERVICIOS(jID_ANIMAL, jFECHA_EVENTO, jTIPO_SERVICIO, jID_TORO, jTORO_EXTERNO, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL SERVICIO
    jPARTO_PROBABLE := jFECHA_EVENTO::DATE + COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_GESTACION'), 283)::INTEGER;
    jID_SERVICIO := funcion_Retorna_ultmoid('TAB_SERVICIOS', 'ID_SERVICIO');
    INSERT INTO TAB_SERVICIOS (ID_SERVICIO, UUID_SERVICIO, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, TIPO_SERVICIO, ID_TORO, TORO_EXTERNO, OBSERVACION_SERVICIO, USUARIO_CREACION)
    VALUES (jID_SERVICIO, jUUID_SERVICIO, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jTIPO_SERVICIO, jID_TORO, NULLIF(TRIM(jTORO_EXTERNO), ''),
        NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Servicio guardado. Parto probable: ' || to_char(jPARTO_PROBABLE, 'DD/MM/YYYY'),
            'DATOS', json_build_object('ID_SERVICIO', jID_SERVICIO, 'UUID_SERVICIO', jUUID_SERVICIO, 'FECHA_PARTO_PROBABLE', jPARTO_PROBABLE, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar el servicio');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_PALPACIONES/FUN_TAB_PALPACIONES.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_PALPACIONES -------------------------------------------------------------------------------------------------------------
-- PRENIADA (CON LOS MESES ESTIMADOS) O VACIA. LA PALPACION SE ENLAZA SOLA CON EL ULTIMO SERVICIO ACTIVO ANTERIOR (SI HAY)



--FUNCION PARA VALIDAR LOS DATOS DE UNA PALPACION
CREATE OR REPLACE FUNCTION FUN_VALIDAR_PALPACIONES(
    jID_ANIMAL TAB_PALPACIONES.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_PALPACIONES.FECHA_EVENTO%TYPE,
    jRESULTADO TAB_PALPACIONES.RESULTADO_PALPACION%TYPE,
    jMESES TAB_PALPACIONES.MESES_GESTACION%TYPE,
    jOBSERVACION TAB_PALPACIONES.OBSERVACION_PALPACION%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jSEXO VARCHAR;
BEGIN
    SELECT SEXO_ANIMAL INTO jSEXO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;

    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;
    ELSIF jSEXO <> 'H' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La palpación se registra a una hembra');
        RETURN RETORNO;
    ELSIF FUN_CATEGORIA_ANIMAL(jID_ANIMAL, jFECHA_EVENTO::DATE) = 'TERNERA' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'En esa fecha era una ternera: no se puede palpar');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_PALPACIONES WHERE ID_ANIMAL = jID_ANIMAL AND FECHA_EVENTO::DATE = jFECHA_EVENTO::DATE AND ESTADO_PALPACION = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya hay una palpación de ' || FUN_ETIQUETA_ANIMAL(jID_ANIMAL) || ' ese mismo día');
        RETURN RETORNO;

    --VALIDACION VARIABLE RESULTADO Y MESES
    ELSIF jRESULTADO IS NULL OR jRESULTADO NOT IN ('PRENIADA', 'VACIA') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige el resultado: preñada o vacía');
        RETURN RETORNO;
    ELSIF jRESULTADO = 'PRENIADA' AND (jMESES IS NULL OR jMESES < 1 OR jMESES > 9) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe de cuántos meses está preñada (de 1 a 9)');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR UNA PALPACION
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_PALPACION_JSON(
    jUUID_PALPACION TAB_PALPACIONES.UUID_PALPACION%TYPE,
    jID_FINCA TAB_PALPACIONES.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jRESULTADO TAB_PALPACIONES.RESULTADO_PALPACION%TYPE,
    jMESES TAB_PALPACIONES.MESES_GESTACION%TYPE,
    jFECHA_EVENTO TAB_PALPACIONES.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_PALPACIONES.OBSERVACION_PALPACION%TYPE,
    jID_USUARIO TAB_PALPACIONES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_PALPACION INTEGER;
    jID_ANIMAL INTEGER;
    jID_SERVICIO INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_PALPACION INTO jID_PALPACION FROM TAB_PALPACIONES WHERE UUID_PALPACION = jUUID_PALPACION;
    IF jID_PALPACION IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'La palpación ya estaba guardada',
            'DATOS', json_build_object('ID_PALPACION', jID_PALPACION, 'UUID_PALPACION', jUUID_PALPACION, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_PALPACION IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID de la palpación');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jVALIDACION := FUN_VALIDAR_PALPACIONES(jID_ANIMAL, jFECHA_EVENTO, jRESULTADO, jMESES, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --ULTIMO SERVICIO ACTIVO ANTES DE LA PALPACION
    SELECT ID_SERVICIO INTO jID_SERVICIO FROM TAB_SERVICIOS
    WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO' AND FECHA_EVENTO <= jFECHA_EVENTO
    ORDER BY FECHA_EVENTO DESC LIMIT 1;

    --INSERTAR LA PALPACION
    jID_PALPACION := funcion_Retorna_ultmoid('TAB_PALPACIONES', 'ID_PALPACION');
    INSERT INTO TAB_PALPACIONES (ID_PALPACION, UUID_PALPACION, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, ID_SERVICIO, RESULTADO_PALPACION, MESES_GESTACION,
        OBSERVACION_PALPACION, USUARIO_CREACION)
    VALUES (jID_PALPACION, jUUID_PALPACION, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jID_SERVICIO, jRESULTADO,
        CASE WHEN jRESULTADO = 'PRENIADA' THEN jMESES END, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', CASE WHEN jRESULTADO = 'PRENIADA' THEN 'Palpación guardada: preñada' ELSE 'Palpación guardada: vacía' END,
            'DATOS', json_build_object('ID_PALPACION', jID_PALPACION, 'UUID_PALPACION', jUUID_PALPACION, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar la palpación');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_PARTOS/FUN_TAB_PARTOS.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_PARTOS ------------------------------------------------------------------------------------------------------------------
-- EL PARTO CON CRIA VIVA CREA LA CRIA (Y SU PESO AL NACER, SI LO ANOTARON) EN LA MISMA TRANSACCION: ENTRAN TODOS O NINGUNO
-- LA CRIA HEREDA LA MADRE Y EL PADRE DEL ULTIMO SERVICIO ACTIVO DESPUES DEL PARTO ANTERIOR (TORO DE LA FINCA O PAJILLA)
-- EL CELULAR GENERA EL UUID DEL PARTO Y EL DE LA CRIA: ASI LA CRIA APARECE EN EL HATO DEL CELULAR ANTES DE SINCRONIZAR



--FUNCION PARA VALIDAR LOS DATOS DE UN PARTO
CREATE OR REPLACE FUNCTION FUN_VALIDAR_PARTOS(
    jID_FINCA TAB_PARTOS.ID_FINCA%TYPE,
    jID_ANIMAL TAB_PARTOS.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_PARTOS.FECHA_EVENTO%TYPE,
    jTIPO_PARTO TAB_PARTOS.TIPO_PARTO%TYPE,
    jCRIA_VIVA TAB_PARTOS.CRIA_VIVA%TYPE,
    jUUID_CRIA TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jSEXO_CRIA TAB_PARTOS.SEXO_CRIA%TYPE,
    jCHAPETA_CRIA TAB_ANIMALES.CHAPETA_ANIMAL%TYPE,
    jNOM_CRIA TAB_ANIMALES.NOM_ANIMAL%TYPE,
    jPESO_CRIA_KG TAB_PESAJES.PESO_KG%TYPE,
    jOBSERVACION TAB_PARTOS.OBSERVACION_PARTO%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jSEXO VARCHAR;
    jDIAS_MINIMOS INTEGER;
    jPARTO_CERCANO TIMESTAMP;
BEGIN
    SELECT SEXO_ANIMAL INTO jSEXO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;
    jDIAS_MINIMOS := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_MINIMOS_ENTRE_PARTOS'), 240)::INTEGER;
    SELECT FECHA_EVENTO INTO jPARTO_CERCANO FROM TAB_PARTOS
    WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PARTO = 'ACTIVO'
      AND abs(FECHA_EVENTO::DATE - jFECHA_EVENTO::DATE) < jDIAS_MINIMOS
    LIMIT 1;

    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;

    --LA MADRE
    ELSIF jSEXO <> 'H' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El parto se registra a una hembra');
        RETURN RETORNO;
    ELSIF FUN_CATEGORIA_ANIMAL(jID_ANIMAL, jFECHA_EVENTO::DATE) = 'TERNERA' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'En esa fecha era una ternera: no pudo parir');
        RETURN RETORNO;
    ELSIF jPARTO_CERCANO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', upper(left(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 1)) || substr(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 2)
            || ' ya tiene un parto el ' || to_char(jPARTO_CERCANO, 'DD/MM/YYYY') || ': dos partos deben estar separados al menos ' || jDIAS_MINIMOS || ' días');
        RETURN RETORNO;

    --VALIDACION VARIABLE TIPO_PARTO Y CRIA_VIVA
    ELSIF jTIPO_PARTO IS NULL OR jTIPO_PARTO NOT IN ('NORMAL', 'ASISTIDO', 'CESAREA', 'ABORTO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige cómo fue: normal, asistido, cesárea o aborto');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA IS NULL OR jCRIA_VIVA NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Indica si la cría nació viva');
        RETURN RETORNO;
    ELSIF jTIPO_PARTO = 'ABORTO' AND jCRIA_VIVA = 'SI' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'En un aborto no hay cría viva');
        RETURN RETORNO;
    ELSIF jSEXO_CRIA IS NOT NULL AND jSEXO_CRIA NOT IN ('H', 'M') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El sexo de la cría debe ser hembra o macho');
        RETURN RETORNO;

    --LA CRIA VIVA: UUID, SEXO, CHAPETA OPCIONAL Y UNICA, PESO AL NACER OPCIONAL
    ELSIF jCRIA_VIVA = 'SI' AND jUUID_CRIA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID de la cría');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA = 'SI' AND EXISTS (SELECT 1 FROM TAB_ANIMALES WHERE UUID_ANIMAL = jUUID_CRIA) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya existe un animal con el UUID de la cría');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA = 'SI' AND jSEXO_CRIA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige si la cría es ternera o ternero');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA = 'SI' AND COALESCE(TRIM(jCHAPETA_CRIA), '') <> '' AND NOT TRIM(jCHAPETA_CRIA) ~ '^[A-Za-z0-9-]{1,20}$' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La chapeta solo puede tener letras, números y guiones (máximo 20)');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA = 'SI' AND COALESCE(TRIM(jCHAPETA_CRIA), '') <> '' AND EXISTS (SELECT 1 FROM TAB_ANIMALES
                  WHERE ID_FINCA = jID_FINCA AND CHAPETA_ANIMAL = UPPER(TRIM(jCHAPETA_CRIA)) AND ESTADO_ANIMAL <> 'ANULADO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La chapeta ' || UPPER(TRIM(jCHAPETA_CRIA)) || ' ya la tiene otro animal de la finca');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA = 'SI' AND LENGTH(TRIM(COALESCE(jNOM_CRIA, ''))) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El nombre de la cría es demasiado largo (máximo 60 caracteres)');
        RETURN RETORNO;
    ELSIF jCRIA_VIVA = 'SI' AND jPESO_CRIA_KG IS NOT NULL AND (jPESO_CRIA_KG < 5 OR jPESO_CRIA_KG > 80) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El peso al nacer debe estar entre 5 y 80 kilos');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR UN PARTO. CON CRIA VIVA CREA LA CRIA Y SU PESO AL NACER
-- HASTA TRES DML (CRIA, PARTO, PESAJE): BLOQUE BEGIN ... EXCEPTION CON RAISE EXCEPTION (ROLLBACK REAL)
-- IDEMPOTENTE: SI EL UUID DEL PARTO YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_PARTO_JSON(
    jUUID_PARTO TAB_PARTOS.UUID_PARTO%TYPE,
    jID_FINCA TAB_PARTOS.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jTIPO_PARTO TAB_PARTOS.TIPO_PARTO%TYPE,
    jCRIA_VIVA TAB_PARTOS.CRIA_VIVA%TYPE,
    jUUID_CRIA TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jSEXO_CRIA TAB_PARTOS.SEXO_CRIA%TYPE,
    jCHAPETA_CRIA TAB_ANIMALES.CHAPETA_ANIMAL%TYPE,
    jNOM_CRIA TAB_ANIMALES.NOM_ANIMAL%TYPE,
    jPESO_CRIA_KG TAB_PESAJES.PESO_KG%TYPE,
    jFECHA_EVENTO TAB_PARTOS.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_PARTOS.OBSERVACION_PARTO%TYPE,
    jID_USUARIO TAB_PARTOS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_PARTO INTEGER;
    jID_ANIMAL INTEGER;
    jID_CRIA INTEGER;
    jID_PESAJE INTEGER;
    jID_LOTE INTEGER;
    jID_TORO INTEGER;
    jTORO_EXTERNO VARCHAR;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_PARTO, ID_CRIA INTO jID_PARTO, jID_CRIA FROM TAB_PARTOS WHERE UUID_PARTO = jUUID_PARTO;
    IF jID_PARTO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El parto ya estaba guardado',
            'DATOS', json_build_object('ID_PARTO', jID_PARTO, 'UUID_PARTO', jUUID_PARTO, 'ID_CRIA', jID_CRIA, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_PARTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del parto');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jVALIDACION := FUN_VALIDAR_PARTOS(jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jTIPO_PARTO, jCRIA_VIVA, jUUID_CRIA, jSEXO_CRIA,
        jCHAPETA_CRIA, jNOM_CRIA, jPESO_CRIA_KG, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --EL PADRE: ULTIMO SERVICIO ACTIVO ANTES DEL PARTO Y DESPUES DEL PARTO ANTERIOR. LA CRIA QUEDA EN EL LOTE DE LA MADRE
    SELECT S.ID_TORO, S.TORO_EXTERNO INTO jID_TORO, jTORO_EXTERNO
    FROM TAB_SERVICIOS S
    WHERE S.ID_ANIMAL = jID_ANIMAL AND S.ESTADO_SERVICIO = 'ACTIVO' AND S.FECHA_EVENTO < jFECHA_EVENTO
      AND S.FECHA_EVENTO > COALESCE((SELECT MAX(P.FECHA_EVENTO) FROM TAB_PARTOS P WHERE P.ID_ANIMAL = jID_ANIMAL AND P.ESTADO_PARTO = 'ACTIVO' AND P.FECHA_EVENTO < jFECHA_EVENTO), '-infinity')
    ORDER BY S.FECHA_EVENTO DESC LIMIT 1;
    SELECT ID_LOTE INTO jID_LOTE FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;

    BEGIN
        --1. LA CRIA VIVA ENTRA AL HATO
        IF jCRIA_VIVA = 'SI' THEN
            jID_CRIA := funcion_Retorna_ultmoid('TAB_ANIMALES', 'ID_ANIMAL');
            INSERT INTO TAB_ANIMALES (ID_ANIMAL, UUID_ANIMAL, ID_FINCA, ID_LOTE, CHAPETA_ANIMAL, NOM_ANIMAL, SEXO_ANIMAL, FECHA_NACIMIENTO,
                ID_MADRE, ID_PADRE, PADRE_EXTERNO, ORIGEN_ANIMAL, FECHA_INGRESO_ANIMAL, USUARIO_CREACION)
            VALUES (jID_CRIA, jUUID_CRIA, jID_FINCA, jID_LOTE, NULLIF(UPPER(TRIM(jCHAPETA_CRIA)), ''), NULLIF(regexp_replace(TRIM(jNOM_CRIA), '\s+', ' ', 'g'), ''),
                jSEXO_CRIA, jFECHA_EVENTO::DATE, jID_ANIMAL, jID_TORO, jTORO_EXTERNO, 'NACIDO', jFECHA_EVENTO::DATE, jID_USUARIO);
            IF NOT FOUND THEN
                RAISE EXCEPTION 'No se pudo registrar la cría';
            END IF;
        END IF;

        --2. EL PARTO
        jID_PARTO := funcion_Retorna_ultmoid('TAB_PARTOS', 'ID_PARTO');
        INSERT INTO TAB_PARTOS (ID_PARTO, UUID_PARTO, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, TIPO_PARTO, CRIA_VIVA, SEXO_CRIA, ID_CRIA, OBSERVACION_PARTO, USUARIO_CREACION)
        VALUES (jID_PARTO, jUUID_PARTO, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jTIPO_PARTO, jCRIA_VIVA, jSEXO_CRIA, jID_CRIA, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No se pudo registrar el parto';
        END IF;

        --3. EL PESO AL NACER (SI LO ANOTARON). SU UUID LO GENERA LA BASE: EL CELULAR LO RECIBE AL BAJAR LOS CAMBIOS
        IF jCRIA_VIVA = 'SI' AND jPESO_CRIA_KG IS NOT NULL THEN
            jID_PESAJE := funcion_Retorna_ultmoid('TAB_PESAJES', 'ID_PESAJE');
            INSERT INTO TAB_PESAJES (ID_PESAJE, UUID_PESAJE, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, PESO_KG, OBSERVACION_PESAJE, USUARIO_CREACION)
            VALUES (jID_PESAJE, gen_random_uuid(), jID_FINCA, jID_CRIA, jFECHA_EVENTO, jPESO_CRIA_KG, 'Peso al nacer', jID_USUARIO);
            IF NOT FOUND THEN
                RAISE EXCEPTION 'No se pudo registrar el peso al nacer';
            END IF;
        END IF;

        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE',
            CASE WHEN jCRIA_VIVA = 'SI' THEN 'Parto guardado: ' || CASE WHEN jSEXO_CRIA = 'H' THEN 'la ternera' ELSE 'el ternero' END || ' ya está en el hato'
                 WHEN jTIPO_PARTO = 'ABORTO' THEN 'Aborto registrado'
                 ELSE 'Parto guardado (cría muerta)' END,
            'DATOS', json_build_object('ID_PARTO', jID_PARTO, 'UUID_PARTO', jUUID_PARTO, 'ID_CRIA', jID_CRIA, 'UUID_CRIA', CASE WHEN jCRIA_VIVA = 'SI' THEN jUUID_CRIA END,
                'YA_EXISTIA', false));
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_ORDENOS/FUN_TAB_ORDENOS.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_ORDENOS -----------------------------------------------------------------------------------------------------------------
-- ORDEÑO POR JORNADA (MAÑANA Y TARDE). EN LA PANTALLA SE PASAN LAS VACAS UNA POR UNA Y SOLO SE ESCRIBEN LOS LITROS (CADA VACA ES UN REGISTRO)
-- UNA JORNADA ACTIVA POR VACA Y DIA (INDICE UQ_ORDENOS_JORNADA): SI DOS CELULARES ORDEÑAN LA MISMA VACA, EL SEGUNDO SE RECHAZA CON MENSAJE



--FUNCION PARA VALIDAR LOS DATOS DE UN ORDEÑO
CREATE OR REPLACE FUNCTION FUN_VALIDAR_ORDENOS(
    jID_ANIMAL TAB_ORDENOS.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_ORDENOS.FECHA_EVENTO%TYPE,
    jJORNADA TAB_ORDENOS.JORNADA_ORDENO%TYPE,
    jLITROS TAB_ORDENOS.LITROS_ORDENO%TYPE,
    jOBSERVACION TAB_ORDENOS.OBSERVACION_ORDENO%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jSEXO VARCHAR;
BEGIN
    SELECT SEXO_ANIMAL INTO jSEXO FROM TAB_ANIMALES WHERE ID_ANIMAL = jID_ANIMAL;

    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA)
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;
    ELSIF jSEXO <> 'H' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El ordeño se registra a una vaca');
        RETURN RETORNO;
    ELSIF FUN_CATEGORIA_ANIMAL(jID_ANIMAL, jFECHA_EVENTO::DATE) = 'TERNERA' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'En esa fecha era una ternera: no se ordeña');
        RETURN RETORNO;

    --VALIDACION VARIABLE JORNADA (UNA POR VACA Y DIA)
    ELSIF jJORNADA IS NULL OR jJORNADA NOT IN ('MANANA', 'TARDE') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige la jornada: mañana o tarde');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_ORDENOS WHERE ID_ANIMAL = jID_ANIMAL AND FECHA_EVENTO::DATE = jFECHA_EVENTO::DATE
                  AND JORNADA_ORDENO = jJORNADA AND ESTADO_ORDENO = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya se registró el ordeño de la ' || CASE WHEN jJORNADA = 'MANANA' THEN 'mañana' ELSE 'tarde' END
            || ' del ' || to_char(jFECHA_EVENTO, 'DD/MM/YYYY') || ' de ' || FUN_ETIQUETA_ANIMAL(jID_ANIMAL));
        RETURN RETORNO;

    --VALIDACION VARIABLE LITROS
    ELSIF jLITROS IS NULL OR jLITROS < 0 OR jLITROS > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe los litros (de 0 a 60)');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR EL ORDEÑO DE UNA VACA EN UNA JORNADA
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_ORDENO_JSON(
    jUUID_ORDENO TAB_ORDENOS.UUID_ORDENO%TYPE,
    jID_FINCA TAB_ORDENOS.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jJORNADA TAB_ORDENOS.JORNADA_ORDENO%TYPE,
    jLITROS TAB_ORDENOS.LITROS_ORDENO%TYPE,
    jFECHA_EVENTO TAB_ORDENOS.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_ORDENOS.OBSERVACION_ORDENO%TYPE,
    jID_USUARIO TAB_ORDENOS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_ORDENO INTEGER;
    jID_ANIMAL INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_ORDENO INTO jID_ORDENO FROM TAB_ORDENOS WHERE UUID_ORDENO = jUUID_ORDENO;
    IF jID_ORDENO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El ordeño ya estaba guardado',
            'DATOS', json_build_object('ID_ORDENO', jID_ORDENO, 'UUID_ORDENO', jUUID_ORDENO, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_ORDENO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del ordeño');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jVALIDACION := FUN_VALIDAR_ORDENOS(jID_ANIMAL, jFECHA_EVENTO, jJORNADA, jLITROS, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL ORDEÑO
    jID_ORDENO := funcion_Retorna_ultmoid('TAB_ORDENOS', 'ID_ORDENO');
    INSERT INTO TAB_ORDENOS (ID_ORDENO, UUID_ORDENO, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, JORNADA_ORDENO, LITROS_ORDENO, OBSERVACION_ORDENO, USUARIO_CREACION)
    VALUES (jID_ORDENO, jUUID_ORDENO, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jJORNADA, jLITROS, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ordeño guardado: ' || trim(to_char(jLITROS, 'FM990.0')) || ' litros',
            'DATOS', json_build_object('ID_ORDENO', jID_ORDENO, 'UUID_ORDENO', jUUID_ORDENO, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar el ordeño');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_SALIDAS/FUN_TAB_SALIDAS.SQL ═══════════
-- FUNCIONES DE LA TABLA TAB_SALIDAS -----------------------------------------------------------------------------------------------------------------
-- VENTA, MUERTE O TRASLADO. EL ESTADO DEL ANIMAL LO CAMBIA EL TRIGGER TRG_SALIDA_ANIMAL (Y LO DEVUELVE A ACTIVO SI SE ANULA LA SALIDA)
-- UNA SOLA SALIDA ACTIVA POR ANIMAL (INDICE UQ_SALIDAS_ANIMAL)



--FUNCION PARA VALIDAR LOS DATOS DE UNA SALIDA
CREATE OR REPLACE FUNCTION FUN_VALIDAR_SALIDAS(
    jID_ANIMAL TAB_SALIDAS.ID_ANIMAL%TYPE,
    jFECHA_EVENTO TAB_SALIDAS.FECHA_EVENTO%TYPE,
    jTIPO_SALIDA TAB_SALIDAS.TIPO_SALIDA%TYPE,
    jVALOR TAB_SALIDAS.VALOR_SALIDA%TYPE,
    jPESO_KG TAB_SALIDAS.PESO_SALIDA_KG%TYPE,
    jCAUSA TAB_SALIDAS.CAUSA_SALIDA%TYPE,
    jOBSERVACION TAB_SALIDAS.OBSERVACION_SALIDA%TYPE
    ) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jULTIMO_EVENTO TIMESTAMP;
BEGIN
    --EL EVENTO MAS RECIENTE DEL ANIMAL: LA SALIDA NO PUEDE QUEDAR ANTES DE ALGO YA REGISTRADO
    SELECT MAX(F) INTO jULTIMO_EVENTO FROM (
        SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PESAJES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PESAJE = 'ACTIVO'
        UNION ALL SELECT MAX(FECHA_EVENTO) FROM TAB_VACUNACIONES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_VACUNACION = 'ACTIVO'
        UNION ALL SELECT MAX(FECHA_EVENTO) FROM TAB_SERVICIOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
        UNION ALL SELECT MAX(FECHA_EVENTO) FROM TAB_PALPACIONES WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO'
        UNION ALL SELECT MAX(FECHA_EVENTO) FROM TAB_PARTOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_PARTO = 'ACTIVO'
        UNION ALL SELECT MAX(FECHA_EVENTO) FROM TAB_ORDENOS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_ORDENO = 'ACTIVO'
    ) T;

    --LO COMUN A TODOS LOS EVENTOS (ANIMAL Y FECHA). SI YA TIENE UNA SALIDA ACTIVA, AQUI SE VE CUANDO LA FECHA ES POSTERIOR
    RETORNO := FUN_VALIDAR_EVENTO_ANIMAL(jID_ANIMAL, jFECHA_EVENTO);
    IF (RETORNO ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_SALIDAS WHERE ID_ANIMAL = jID_ANIMAL AND ESTADO_SALIDA = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', upper(left(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 1)) || substr(FUN_ETIQUETA_ANIMAL(jID_ANIMAL), 2)
            || ' ya tiene registrada su salida. Si está mal, anúlala primero');
        RETURN RETORNO;
    ELSIF jULTIMO_EVENTO IS NOT NULL AND jFECHA_EVENTO < jULTIMO_EVENTO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Tiene registros hasta el ' || to_char(jULTIMO_EVENTO, 'DD/MM/YYYY') || ': la salida no puede ser antes');
        RETURN RETORNO;

    --VALIDACION VARIABLE TIPO_SALIDA Y LO QUE PIDE CADA UNA
    ELSIF jTIPO_SALIDA IS NULL OR jTIPO_SALIDA NOT IN ('VENTA', 'MUERTE', 'TRASLADO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige el tipo de salida: venta, muerte o traslado');
        RETURN RETORNO;
    ELSIF jTIPO_SALIDA = 'VENTA' AND (jVALOR IS NULL OR jVALOR <= 0) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe en cuánto se vendió');
        RETURN RETORNO;
    ELSIF jVALOR IS NOT NULL AND jVALOR > 99999999999 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Revisa el valor de la venta');
        RETURN RETORNO;
    ELSIF jTIPO_SALIDA = 'MUERTE' AND COALESCE(TRIM(jCAUSA), '') = '' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe la causa de la muerte (si no se sabe, "desconocida")');
        RETURN RETORNO;
    ELSIF LENGTH(TRIM(COALESCE(jCAUSA, ''))) > 200 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La causa es demasiado larga (máximo 200 caracteres)');
        RETURN RETORNO;
    ELSIF jPESO_KG IS NOT NULL AND (jPESO_KG <= 0 OR jPESO_KG > 1500) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El peso de salida debe estar entre 1 y 1500 kilos');
        RETURN RETORNO;

    --VALIDACION VARIABLE OBSERVACION (OPCIONAL)
    ELSIF LENGTH(COALESCE(jOBSERVACION, '')) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La nota es demasiado larga (máximo 300 caracteres)');
        RETURN RETORNO;

    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA REGISTRAR LA SALIDA DE UN ANIMAL (VENTA, MUERTE O TRASLADO)
-- IDEMPOTENTE: SI EL UUID YA EXISTE RESPONDE 200 CON YA_EXISTIA Y NO DUPLICA
CREATE OR REPLACE FUNCTION FUN_CREAR_SALIDA_JSON(
    jUUID_SALIDA TAB_SALIDAS.UUID_SALIDA%TYPE,
    jID_FINCA TAB_SALIDAS.ID_FINCA%TYPE,
    jUUID_ANIMAL TAB_ANIMALES.UUID_ANIMAL%TYPE,
    jTIPO_SALIDA TAB_SALIDAS.TIPO_SALIDA%TYPE,
    jVALOR TAB_SALIDAS.VALOR_SALIDA%TYPE,
    jPESO_KG TAB_SALIDAS.PESO_SALIDA_KG%TYPE,
    jCAUSA TAB_SALIDAS.CAUSA_SALIDA%TYPE,
    jFECHA_EVENTO TAB_SALIDAS.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_SALIDAS.OBSERVACION_SALIDA%TYPE,
    jID_USUARIO TAB_SALIDAS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_SALIDA INTEGER;
    jID_ANIMAL INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_SALIDA INTO jID_SALIDA FROM TAB_SALIDAS WHERE UUID_SALIDA = jUUID_SALIDA;
    IF jID_SALIDA IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'La salida ya estaba guardada',
            'DATOS', json_build_object('ID_SALIDA', jID_SALIDA, 'UUID_SALIDA', jUUID_SALIDA, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_SALIDA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID de la salida');
        RETURN RETORNO;
    END IF;

    --LLAMAR A LA FUNCION DE VALIDACION
    jID_ANIMAL := FUN_ID_ANIMAL_POR_UUID(jID_FINCA, jUUID_ANIMAL);
    jVALIDACION := FUN_VALIDAR_SALIDAS(jID_ANIMAL, jFECHA_EVENTO, jTIPO_SALIDA, jVALOR, jPESO_KG, jCAUSA, jOBSERVACION);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR LA SALIDA (EL TRIGGER TRG_SALIDA_ANIMAL CAMBIA EL ESTADO DEL ANIMAL)
    jID_SALIDA := funcion_Retorna_ultmoid('TAB_SALIDAS', 'ID_SALIDA');
    INSERT INTO TAB_SALIDAS (ID_SALIDA, UUID_SALIDA, ID_FINCA, ID_ANIMAL, FECHA_EVENTO, TIPO_SALIDA, VALOR_SALIDA, PESO_SALIDA_KG, CAUSA_SALIDA,
        OBSERVACION_SALIDA, USUARIO_CREACION)
    VALUES (jID_SALIDA, jUUID_SALIDA, jID_FINCA, jID_ANIMAL, jFECHA_EVENTO, jTIPO_SALIDA, jVALOR, jPESO_KG, NULLIF(TRIM(jCAUSA), ''),
        NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE',
            CASE jTIPO_SALIDA WHEN 'VENTA' THEN 'Venta registrada' WHEN 'MUERTE' THEN 'Muerte registrada' ELSE 'Traslado registrado' END,
            'DATOS', json_build_object('ID_SALIDA', jID_SALIDA, 'UUID_SALIDA', jUUID_SALIDA, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al registrar la salida');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_POTREROS/FUN_TAB_POTREROS.SQL ═══════════
-- FUNCIONES DE LAS TABLAS TAB_POTREROS Y TAB_OCUPACIONES (FASE 5A: POTREROS Y ROTACION) ----------------------------------------------------------
-- TODO SE PUEDE HACER SIN SEÑAL: EL CELULAR GENERA LOS UUID Y LAS FUNCIONES SON IDEMPOTENTES (UN REINTENTO NO DUPLICA)
-- POTREROS: DUEÑO Y VAQUERO CREAN; SOLO EL DUEÑO EDITA Y ANULA (COMO LOS LOTES)
-- OCUPACIONES: DUEÑO Y VAQUERO METEN Y SACAN LOTES; SOLO EL DUEÑO ANULA (COMO LOS EVENTOS)
-- ESTADO DE UN POTRERO (FUN_ESTADO_POTRERO):
--   OCUPADO      UNO O MAS LOTES ADENTRO (OCUPACION ABIERTA)
--   DESCANSANDO  SIN LOTES; LLEVA (HOY - ULTIMA SALIDA) DIAS DE DESCANSO DE LOS DIAS_DESCANSO_POTRERO QUE NECESITA
--   LISTO        SIN LOTES Y YA DESCANSO SUS DIAS
--   SIN_USO      NUNCA SE HA REGISTRADO UN LOTE EN EL
-- EL CELULAR CALCULA LO MISMO CON SU COPIA PARA VERLO SIN SEÑAL (estadoPotrero EN potreros.service.ts); LA REGLA OFICIAL ES ESTA



-- FUNCION QUE DEVUELVE EL ID DE UN POTRERO ACTIVO DE LA FINCA POR SU UUID (NULL SI NO EXISTE O ESTA ANULADO)
CREATE OR REPLACE FUNCTION FUN_ID_POTRERO_POR_UUID(
    jID_FINCA TAB_POTREROS.ID_FINCA%TYPE,
    jUUID_POTRERO TAB_POTREROS.UUID_POTRERO%TYPE
) RETURNS INTEGER AS
$$
DECLARE
    jID_POTRERO INTEGER;
BEGIN
    SELECT ID_POTRERO INTO jID_POTRERO FROM TAB_POTREROS WHERE UUID_POTRERO = jUUID_POTRERO AND ID_FINCA = jID_FINCA AND ESTADO_POTRERO = 'ACTIVO';
    RETURN jID_POTRERO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE VALIDA LOS DATOS DE UN POTRERO (CREAR Y ACTUALIZAR). jID_POTRERO NULL AL CREAR
-- EL CONTORNO ES OPCIONAL: SI VIENE, UNA LISTA DE 3 A 200 PUNTOS [LATITUD, LONGITUD] DENTRO DE COLOMBIA (APROXIMADO)
CREATE OR REPLACE FUNCTION FUN_VALIDAR_POTRERO(
    jID_FINCA TAB_POTREROS.ID_FINCA%TYPE,
    jID_POTRERO TAB_POTREROS.ID_POTRERO%TYPE,
    jNOM_POTRERO TAB_POTREROS.NOM_POTRERO%TYPE,
    jAREA_POTRERO TAB_POTREROS.AREA_POTRERO%TYPE,
    jDIAS_DESCANSO_POTRERO TAB_POTREROS.DIAS_DESCANSO_POTRERO%TYPE,
    jCONTORNO_POTRERO TAB_POTREROS.CONTORNO_POTRERO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jPUNTOS_MALOS INTEGER;
BEGIN
    IF jNOM_POTRERO IS NULL OR TRIM(jNOM_POTRERO) = '' OR LENGTH(TRIM(jNOM_POTRERO)) > 60 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el nombre del potrero (máximo 60 caracteres)');
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_POTREROS WHERE ID_FINCA = jID_FINCA AND LOWER(NOM_POTRERO) = LOWER(regexp_replace(TRIM(jNOM_POTRERO), '\s+', ' ', 'g'))
                  AND ESTADO_POTRERO = 'ACTIVO' AND ID_POTRERO IS DISTINCT FROM jID_POTRERO) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Ya hay un potrero con ese nombre');
        RETURN RETORNO;
    ELSIF jAREA_POTRERO IS NOT NULL AND (jAREA_POTRERO <= 0 OR jAREA_POTRERO > 10000) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El área debe estar entre 0,01 y 10.000 hectáreas');
        RETURN RETORNO;
    ELSIF jDIAS_DESCANSO_POTRERO IS NULL OR jDIAS_DESCANSO_POTRERO < 1 OR jDIAS_DESCANSO_POTRERO > 365 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los días de descanso deben estar entre 1 y 365');
        RETURN RETORNO;
    ELSIF jCONTORNO_POTRERO IS NOT NULL AND json_typeof(jCONTORNO_POTRERO) <> 'null' THEN
        IF json_typeof(jCONTORNO_POTRERO) <> 'array' OR json_array_length(jCONTORNO_POTRERO) < 3 OR json_array_length(jCONTORNO_POTRERO) > 200 THEN
            RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El contorno del mapa debe tener entre 3 y 200 puntos');
            RETURN RETORNO;
        END IF;
        SELECT COUNT(*) INTO jPUNTOS_MALOS
        FROM json_array_elements(jCONTORNO_POTRERO) P
        WHERE json_typeof(P.value) <> 'array' OR json_array_length(P.value) <> 2
           OR json_typeof(P.value -> 0) <> 'number' OR json_typeof(P.value -> 1) <> 'number'
           OR (P.value ->> 0)::NUMERIC NOT BETWEEN -5 AND 14 OR (P.value ->> 1)::NUMERIC NOT BETWEEN -82 AND -66;
        IF jPUNTOS_MALOS > 0 THEN
            RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El contorno del mapa tiene puntos que no son válidos');
            RETURN RETORNO;
        END IF;
    END IF;
    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA CREAR UN POTRERO (DUEÑO Y VAQUERO)
CREATE OR REPLACE FUNCTION FUN_CREAR_POTRERO_JSON(
    jUUID_POTRERO TAB_POTREROS.UUID_POTRERO%TYPE,
    jID_FINCA TAB_POTREROS.ID_FINCA%TYPE,
    jNOM_POTRERO TAB_POTREROS.NOM_POTRERO%TYPE,
    jAREA_POTRERO TAB_POTREROS.AREA_POTRERO%TYPE,
    jDIAS_DESCANSO_POTRERO TAB_POTREROS.DIAS_DESCANSO_POTRERO%TYPE,
    jCONTORNO_POTRERO TAB_POTREROS.CONTORNO_POTRERO%TYPE,
    jID_USUARIO TAB_POTREROS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_POTRERO INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_POTRERO INTO jID_POTRERO FROM TAB_POTREROS WHERE UUID_POTRERO = jUUID_POTRERO;
    IF jID_POTRERO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El potrero ya estaba guardado',
            'DATOS', json_build_object('ID_POTRERO', jID_POTRERO, 'UUID_POTRERO', jUUID_POTRERO, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO Y LOS DATOS
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VAQUERO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_POTRERO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del potrero');
        RETURN RETORNO;
    END IF;
    jVALIDACION := FUN_VALIDAR_POTRERO(jID_FINCA, NULL, jNOM_POTRERO, jAREA_POTRERO, COALESCE(jDIAS_DESCANSO_POTRERO, 30), jCONTORNO_POTRERO);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL POTRERO
    jID_POTRERO := funcion_Retorna_ultmoid('TAB_POTREROS', 'ID_POTRERO');
    INSERT INTO TAB_POTREROS (ID_POTRERO, UUID_POTRERO, ID_FINCA, NOM_POTRERO, AREA_POTRERO, DIAS_DESCANSO_POTRERO, CONTORNO_POTRERO, USUARIO_CREACION)
    VALUES (jID_POTRERO, jUUID_POTRERO, jID_FINCA, regexp_replace(TRIM(jNOM_POTRERO), '\s+', ' ', 'g'), jAREA_POTRERO,
        COALESCE(jDIAS_DESCANSO_POTRERO, 30), CASE WHEN json_typeof(jCONTORNO_POTRERO) = 'array' THEN jCONTORNO_POTRERO END, jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Potrero creado',
            'DATOS', json_build_object('ID_POTRERO', jID_POTRERO, 'UUID_POTRERO', jUUID_POTRERO, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al crear el potrero');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ACTUALIZAR UN POTRERO: NOMBRE, AREA, DIAS DE DESCANSO Y CONTORNO (SOLO EL DUEÑO). GANA EL ULTIMO QUE SINCRONIZA
CREATE OR REPLACE FUNCTION FUN_ACTUALIZAR_POTRERO_JSON(
    jUUID_POTRERO TAB_POTREROS.UUID_POTRERO%TYPE,
    jID_FINCA TAB_POTREROS.ID_FINCA%TYPE,
    jNOM_POTRERO TAB_POTREROS.NOM_POTRERO%TYPE,
    jAREA_POTRERO TAB_POTREROS.AREA_POTRERO%TYPE,
    jDIAS_DESCANSO_POTRERO TAB_POTREROS.DIAS_DESCANSO_POTRERO%TYPE,
    jCONTORNO_POTRERO TAB_POTREROS.CONTORNO_POTRERO%TYPE,
    jID_USUARIO TAB_POTREROS.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_POTRERO INTEGER;
BEGIN
    --VALIDAR EL ACCESO Y LOS DATOS
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;
    jID_POTRERO := FUN_ID_POTRERO_POR_UUID(jID_FINCA, jUUID_POTRERO);
    IF jID_POTRERO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El potrero no existe en esta finca');
        RETURN RETORNO;
    END IF;
    jVALIDACION := FUN_VALIDAR_POTRERO(jID_FINCA, jID_POTRERO, jNOM_POTRERO, jAREA_POTRERO, jDIAS_DESCANSO_POTRERO, jCONTORNO_POTRERO);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    UPDATE TAB_POTREROS
    SET NOM_POTRERO = regexp_replace(TRIM(jNOM_POTRERO), '\s+', ' ', 'g'),
        AREA_POTRERO = jAREA_POTRERO,
        DIAS_DESCANSO_POTRERO = jDIAS_DESCANSO_POTRERO,
        CONTORNO_POTRERO = CASE WHEN json_typeof(jCONTORNO_POTRERO) = 'array' THEN jCONTORNO_POTRERO END,
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_POTRERO = jID_POTRERO;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Potrero actualizado');
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al actualizar el potrero');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ANULAR UN POTRERO (SOLO EL DUEÑO). NO SE PUEDE SI TIENE UN LOTE ADENTRO: PRIMERO SE SACA
-- SI YA ESTABA ANULADO RESPONDE 200 CON YA_EXISTIA (REINTENTO SEGURO). SU HISTORIA DE OCUPACIONES SE CONSERVA
CREATE OR REPLACE FUNCTION FUN_ANULAR_POTRERO_JSON(
    jUUID_POTRERO TAB_POTREROS.UUID_POTRERO%TYPE,
    jID_FINCA TAB_POTREROS.ID_FINCA%TYPE,
    jID_USUARIO TAB_POTREROS.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_POTRERO INTEGER;
    jESTADO VARCHAR;
BEGIN
    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT ID_POTRERO, ESTADO_POTRERO INTO jID_POTRERO, jESTADO FROM TAB_POTREROS WHERE UUID_POTRERO = jUUID_POTRERO AND ID_FINCA = jID_FINCA;
    IF jID_POTRERO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El potrero no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El potrero ya estaba anulado', 'DATOS', json_build_object('YA_EXISTIA', true));
        RETURN RETORNO;
    ELSIF EXISTS (SELECT 1 FROM TAB_OCUPACIONES WHERE ID_POTRERO = jID_POTRERO AND FECHA_SALIDA_OCUPACION IS NULL AND ESTADO_OCUPACION = 'ACTIVO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El potrero tiene un lote adentro: sácalo antes de anularlo');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_POTREROS
    SET ESTADO_POTRERO = 'ANULADO',
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_POTRERO = jID_POTRERO;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Potrero anulado', 'DATOS', json_build_object('YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al anular el potrero');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA METER UN LOTE A UN POTRERO (DUEÑO Y VAQUERO). SI EL LOTE ESTABA EN OTRO POTRERO, ESA OCUPACION SE CIERRA CON LA MISMA FECHA
-- REGLAS: LA FECHA NO PUEDE SER FUTURA (UN DIA DE MARGEN, COMO LOS EVENTOS) NI ANTERIOR A LA ULTIMA ENTRADA O SALIDA DEL LOTE
-- (SIN SEÑAL LOS MOVIMIENTOS LLEGAN EN ORDEN; UNO VIEJO QUE LLEGA TARDE SE RECHAZA EN VEZ DE REESCRIBIR LA HISTORIA)
-- DOS DML: BLOQUE BEGIN ... EXCEPTION
CREATE OR REPLACE FUNCTION FUN_ENTRAR_LOTE_POTRERO_JSON(
    jUUID_OCUPACION TAB_OCUPACIONES.UUID_OCUPACION%TYPE,
    jID_FINCA TAB_OCUPACIONES.ID_FINCA%TYPE,
    jUUID_LOTE TAB_LOTES.UUID_LOTE%TYPE,
    jUUID_POTRERO TAB_POTREROS.UUID_POTRERO%TYPE,
    jFECHA_EVENTO TAB_OCUPACIONES.FECHA_EVENTO%TYPE,
    jOBSERVACION TAB_OCUPACIONES.OBSERVACION_OCUPACION%TYPE,
    jID_USUARIO TAB_OCUPACIONES.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_OCUPACION INTEGER;
    jID_LOTE INTEGER;
    jID_POTRERO INTEGER;
    jID_ABIERTA INTEGER;
    jID_POTRERO_ABIERTA INTEGER;
    jULTIMA_FECHA TIMESTAMP;
    jNOM_POTRERO VARCHAR;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_OCUPACION INTO jID_OCUPACION FROM TAB_OCUPACIONES WHERE UUID_OCUPACION = jUUID_OCUPACION;
    IF jID_OCUPACION IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El movimiento ya estaba guardado',
            'DATOS', json_build_object('ID_OCUPACION', jID_OCUPACION, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VAQUERO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    jID_LOTE := FUN_ID_LOTE_POR_UUID(jID_FINCA, jUUID_LOTE);
    jID_POTRERO := FUN_ID_POTRERO_POR_UUID(jID_FINCA, jUUID_POTRERO);
    SELECT ID_OCUPACION, ID_POTRERO INTO jID_ABIERTA, jID_POTRERO_ABIERTA
    FROM TAB_OCUPACIONES WHERE ID_LOTE = jID_LOTE AND FECHA_SALIDA_OCUPACION IS NULL AND ESTADO_OCUPACION = 'ACTIVO';
    SELECT MAX(GREATEST(FECHA_EVENTO, COALESCE(FECHA_SALIDA_OCUPACION, FECHA_EVENTO))) INTO jULTIMA_FECHA
    FROM TAB_OCUPACIONES WHERE ID_LOTE = jID_LOTE AND ESTADO_OCUPACION = 'ACTIVO';
    SELECT NOM_POTRERO INTO jNOM_POTRERO FROM TAB_POTREROS WHERE ID_POTRERO = jID_POTRERO;

    --VALIDAR LOS DATOS
    IF jUUID_OCUPACION IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del movimiento');
        RETURN RETORNO;
    ELSIF jID_LOTE IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El lote no existe en esta finca');
        RETURN RETORNO;
    ELSIF jID_POTRERO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'El potrero no existe en esta finca');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta la fecha');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO > NOW() + INTERVAL '1 day' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha no puede ser futura');
        RETURN RETORNO;
    ELSIF jID_POTRERO_ABIERTA = jID_POTRERO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El lote ya está en el potrero ' || jNOM_POTRERO);
        RETURN RETORNO;
    ELSIF jULTIMA_FECHA IS NOT NULL AND jFECHA_EVENTO < jULTIMA_FECHA THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El lote ya tiene un movimiento del ' || to_char(jULTIMA_FECHA, 'DD/MM/YYYY')
            || ': la entrada no puede ser antes');
        RETURN RETORNO;
    ELSIF jOBSERVACION IS NOT NULL AND LENGTH(jOBSERVACION) > 300 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La observación es muy larga (máximo 300 caracteres)');
        RETURN RETORNO;
    END IF;

    BEGIN
        --CERRAR LA OCUPACION ANTERIOR DEL LOTE (SI ESTABA EN OTRO POTRERO)
        IF jID_ABIERTA IS NOT NULL THEN
            UPDATE TAB_OCUPACIONES
            SET FECHA_SALIDA_OCUPACION = jFECHA_EVENTO,
                USUARIO_MODIFICACION = jID_USUARIO,
                FECHA_MODIFICACION = NOW()
            WHERE ID_OCUPACION = jID_ABIERTA;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'No se pudo sacar el lote del potrero anterior';
            END IF;
        END IF;

        --LA OCUPACION NUEVA
        jID_OCUPACION := funcion_Retorna_ultmoid('TAB_OCUPACIONES', 'ID_OCUPACION');
        INSERT INTO TAB_OCUPACIONES (ID_OCUPACION, UUID_OCUPACION, ID_FINCA, ID_POTRERO, ID_LOTE, FECHA_EVENTO, OBSERVACION_OCUPACION, USUARIO_CREACION)
        VALUES (jID_OCUPACION, jUUID_OCUPACION, jID_FINCA, jID_POTRERO, jID_LOTE, jFECHA_EVENTO, NULLIF(TRIM(jOBSERVACION), ''), jID_USUARIO);
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No se pudo meter el lote al potrero';
        END IF;

        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El lote entró al potrero ' || jNOM_POTRERO,
            'DATOS', json_build_object('ID_OCUPACION', jID_OCUPACION, 'YA_EXISTIA', false));
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA SACAR UN LOTE DE SU POTRERO SIN METERLO A OTRO (AL CORRAL, A LA CARRETERA...) (DUEÑO Y VAQUERO)
-- jUUID_OCUPACION ES LA OCUPACION ABIERTA. SI YA ESTABA CERRADA CON ESA MISMA FECHA, RESPONDE 200 CON YA_EXISTIA (REINTENTO)
CREATE OR REPLACE FUNCTION FUN_SACAR_LOTE_POTRERO_JSON(
    jUUID_OCUPACION TAB_OCUPACIONES.UUID_OCUPACION%TYPE,
    jID_FINCA TAB_OCUPACIONES.ID_FINCA%TYPE,
    jFECHA_SALIDA TAB_OCUPACIONES.FECHA_SALIDA_OCUPACION%TYPE,
    jID_USUARIO TAB_OCUPACIONES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_OCUPACION INTEGER;
    jENTRADA TIMESTAMP;
    jSALIDA TIMESTAMP;
    jESTADO VARCHAR;
BEGIN
    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VAQUERO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT ID_OCUPACION, FECHA_EVENTO, FECHA_SALIDA_OCUPACION, ESTADO_OCUPACION INTO jID_OCUPACION, jENTRADA, jSALIDA, jESTADO
    FROM TAB_OCUPACIONES WHERE UUID_OCUPACION = jUUID_OCUPACION AND ID_FINCA = jID_FINCA;

    --VALIDAR LOS DATOS
    IF jID_OCUPACION IS NULL OR jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Ese movimiento no existe en esta finca');
        RETURN RETORNO;
    ELSIF jSALIDA IS NOT NULL AND jSALIDA = jFECHA_SALIDA THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El lote ya había salido', 'DATOS', json_build_object('YA_EXISTIA', true));
        RETURN RETORNO;
    ELSIF jSALIDA IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El lote ya había salido de ese potrero el ' || to_char(jSALIDA, 'DD/MM/YYYY'));
        RETURN RETORNO;
    ELSIF jFECHA_SALIDA IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta la fecha');
        RETURN RETORNO;
    ELSIF jFECHA_SALIDA > NOW() + INTERVAL '1 day' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha no puede ser futura');
        RETURN RETORNO;
    ELSIF jFECHA_SALIDA < jENTRADA THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La salida no puede ser antes de la entrada (' || to_char(jENTRADA, 'DD/MM/YYYY') || ')');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_OCUPACIONES
    SET FECHA_SALIDA_OCUPACION = jFECHA_SALIDA,
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_OCUPACION = jID_OCUPACION;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El lote salió del potrero', 'DATOS', json_build_object('YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al sacar el lote');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ANULAR UN MOVIMIENTO (SOLO EL DUEÑO, PARA CORREGIR UN ERROR). SOLO EL ULTIMO MOVIMIENTO DEL LOTE
-- SI AL ENTRAR SE HABIA CERRADO LA OCUPACION ANTERIOR (SALIDA = ESTA ENTRADA), ESA SE VUELVE A ABRIR: EL LOTE QUEDA DONDE ESTABA
-- DOS DML: BLOQUE BEGIN ... EXCEPTION. SI YA ESTABA ANULADO RESPONDE 200 CON YA_EXISTIA
CREATE OR REPLACE FUNCTION FUN_ANULAR_OCUPACION_JSON(
    jUUID_OCUPACION TAB_OCUPACIONES.UUID_OCUPACION%TYPE,
    jID_FINCA TAB_OCUPACIONES.ID_FINCA%TYPE,
    jID_USUARIO TAB_OCUPACIONES.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_OCUPACION INTEGER;
    jID_LOTE INTEGER;
    jENTRADA TIMESTAMP;
    jESTADO VARCHAR;
    jID_ANTERIOR INTEGER;
BEGIN
    --VALIDAR EL ACCESO
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT ID_OCUPACION, ID_LOTE, FECHA_EVENTO, ESTADO_OCUPACION INTO jID_OCUPACION, jID_LOTE, jENTRADA, jESTADO
    FROM TAB_OCUPACIONES WHERE UUID_OCUPACION = jUUID_OCUPACION AND ID_FINCA = jID_FINCA;
    IF jID_OCUPACION IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Ese movimiento no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El movimiento ya estaba anulado', 'DATOS', json_build_object('YA_EXISTIA', true));
        RETURN RETORNO;
    --CON LA MISMA HORA (DOS MOVIMIENTOS EN EL MISMO MINUTO) GANA EL QUE SE GUARDO DESPUES (ID MAS ALTO)
    ELSIF EXISTS (SELECT 1 FROM TAB_OCUPACIONES WHERE ID_LOTE = jID_LOTE AND ESTADO_OCUPACION = 'ACTIVO' AND ID_OCUPACION <> jID_OCUPACION
                  AND (FECHA_EVENTO > jENTRADA OR (FECHA_EVENTO = jENTRADA AND ID_OCUPACION > jID_OCUPACION))) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Solo se puede anular el último movimiento del lote');
        RETURN RETORNO;
    END IF;

    --LA OCUPACION QUE ESTA ENTRADA CERRO (SI LA HUBO)
    SELECT ID_OCUPACION INTO jID_ANTERIOR FROM TAB_OCUPACIONES
    WHERE ID_LOTE = jID_LOTE AND ESTADO_OCUPACION = 'ACTIVO' AND ID_OCUPACION < jID_OCUPACION AND FECHA_SALIDA_OCUPACION = jENTRADA
    ORDER BY FECHA_EVENTO DESC, ID_OCUPACION DESC LIMIT 1;

    BEGIN
        UPDATE TAB_OCUPACIONES
        SET ESTADO_OCUPACION = 'ANULADO',
            USUARIO_MODIFICACION = jID_USUARIO,
            FECHA_MODIFICACION = NOW()
        WHERE ID_OCUPACION = jID_OCUPACION;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'No se pudo anular el movimiento';
        END IF;

        IF jID_ANTERIOR IS NOT NULL THEN
            UPDATE TAB_OCUPACIONES
            SET FECHA_SALIDA_OCUPACION = NULL,
                USUARIO_MODIFICACION = jID_USUARIO,
                FECHA_MODIFICACION = NOW()
            WHERE ID_OCUPACION = jID_ANTERIOR;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'No se pudo devolver el lote al potrero anterior';
            END IF;
        END IF;

        RETORNO := json_build_object('CODIGO', 200,
            'MENSAJE', CASE WHEN jID_ANTERIOR IS NULL THEN 'Movimiento anulado' ELSE 'Movimiento anulado: el lote volvió al potrero anterior' END,
            'DATOS', json_build_object('YA_EXISTIA', false));
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DICE EN QUE ESTADO ESTA UN POTRERO HOY (VER LA TABLA DE ESTADOS ARRIBA)
-- DEVUELVE {ESTADO, DIAS_OCUPADO, DIAS_DESCANSO, LOTES:[{UUID_LOTE, NOM_LOTE, FECHA_ENTRADA, DIAS}]}
CREATE OR REPLACE FUNCTION FUN_ESTADO_POTRERO(
    jID_POTRERO TAB_POTREROS.ID_POTRERO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_LOTES JSON;
    jENTRADA_MAS_VIEJA TIMESTAMP;
    jULTIMA_SALIDA TIMESTAMP;
    jDIAS_NECESARIOS INTEGER;
    jDIAS INTEGER;
BEGIN
    SELECT DIAS_DESCANSO_POTRERO INTO jDIAS_NECESARIOS FROM TAB_POTREROS WHERE ID_POTRERO = jID_POTRERO;

    --LOTES ADENTRO
    SELECT json_agg(json_build_object('UUID_LOTE', L.UUID_LOTE, 'NOM_LOTE', L.NOM_LOTE, 'FECHA_ENTRADA', O.FECHA_EVENTO,
        'DIAS', CURRENT_DATE - O.FECHA_EVENTO::DATE) ORDER BY O.FECHA_EVENTO), MIN(O.FECHA_EVENTO)
    INTO LISTA_LOTES, jENTRADA_MAS_VIEJA
    FROM TAB_OCUPACIONES O JOIN TAB_LOTES L ON L.ID_LOTE = O.ID_LOTE
    WHERE O.ID_POTRERO = jID_POTRERO AND O.FECHA_SALIDA_OCUPACION IS NULL AND O.ESTADO_OCUPACION = 'ACTIVO';

    IF LISTA_LOTES IS NOT NULL THEN
        RETORNO := json_build_object('ESTADO', 'OCUPADO', 'DIAS_OCUPADO', CURRENT_DATE - jENTRADA_MAS_VIEJA::DATE, 'DIAS_DESCANSO', NULL,
            'DIAS_DESCANSO_POTRERO', jDIAS_NECESARIOS, 'LOTES', LISTA_LOTES);
        RETURN RETORNO;
    END IF;

    --SIN LOTES: DESDE CUANDO DESCANSA
    SELECT MAX(FECHA_SALIDA_OCUPACION) INTO jULTIMA_SALIDA
    FROM TAB_OCUPACIONES WHERE ID_POTRERO = jID_POTRERO AND ESTADO_OCUPACION = 'ACTIVO';
    IF jULTIMA_SALIDA IS NULL THEN
        RETORNO := json_build_object('ESTADO', 'SIN_USO', 'DIAS_OCUPADO', NULL, 'DIAS_DESCANSO', NULL,
            'DIAS_DESCANSO_POTRERO', jDIAS_NECESARIOS, 'LOTES', '[]'::JSON);
        RETURN RETORNO;
    END IF;
    jDIAS := CURRENT_DATE - jULTIMA_SALIDA::DATE;
    RETORNO := json_build_object('ESTADO', CASE WHEN jDIAS >= jDIAS_NECESARIOS THEN 'LISTO' ELSE 'DESCANSANDO' END,
        'DIAS_OCUPADO', NULL, 'DIAS_DESCANSO', jDIAS, 'DIAS_DESCANSO_POTRERO', jDIAS_NECESARIOS, 'LOTES', '[]'::JSON);
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LOS POTREROS ACTIVOS DE LA FINCA CON SU ESTADO DE HOY (CUALQUIER ROL DE LA FINCA)
CREATE OR REPLACE FUNCTION FUN_OBTENER_POTREROS_JSON(
    jID_FINCA TAB_POTREROS.ID_FINCA%TYPE,
    jID_USUARIO TAB_POTREROS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    LISTA_POTREROS JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_agg(json_build_object(
        'UUID_POTRERO', P.UUID_POTRERO,
        'NOM_POTRERO', P.NOM_POTRERO,
        'AREA_POTRERO', P.AREA_POTRERO,
        'DIAS_DESCANSO_POTRERO', P.DIAS_DESCANSO_POTRERO,
        'TIENE_CONTORNO', P.CONTORNO_POTRERO IS NOT NULL,
        'ESTADO_HOY', FUN_ESTADO_POTRERO(P.ID_POTRERO)
    ) ORDER BY P.NOM_POTRERO) INTO LISTA_POTREROS
    FROM TAB_POTREROS P
    WHERE P.ID_FINCA = jID_FINCA AND P.ESTADO_POTRERO = 'ACTIVO';

    IF LISTA_POTREROS IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'La finca todavía no tiene potreros');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Potreros de la finca', 'DATOS', LISTA_POTREROS);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_PLATA/FUN_TAB_PLATA.SQL ═══════════
-- FUNCIONES DE LA PLATA DE LA FINCA (FASE 5B: TAB_MOVIMIENTOS) -----------------------------------------------------------------------------------
-- SOLO EL DUEÑO ANOTA, VE Y ANULA (EL VAQUERO Y EL VETERINARIO NO RECIBEN LOS MOVIMIENTOS AL SINCRONIZAR)
-- SE ANOTA SIN SEÑAL: EL CELULAR GENERA EL UUID Y CREAR ES IDEMPOTENTE. ANULAR USA FUN_ANULAR_EVENTO_JSON (TIPO MOVIMIENTO)
-- LA VENTA DE ANIMALES NO SE ANOTA AQUI: SALE DE TAB_SALIDAS (VENTA CON VALOR), ASI NUNCA SE CUENTA DOS VECES



-- FUNCION QUE VALIDA UN MOVIMIENTO
CREATE OR REPLACE FUNCTION FUN_VALIDAR_MOVIMIENTO(
    jTIPO_MOVIMIENTO TAB_MOVIMIENTOS.TIPO_MOVIMIENTO%TYPE,
    jCATEGORIA_MOVIMIENTO TAB_MOVIMIENTOS.CATEGORIA_MOVIMIENTO%TYPE,
    jVALOR_MOVIMIENTO TAB_MOVIMIENTOS.VALOR_MOVIMIENTO%TYPE,
    jLITROS_MOVIMIENTO TAB_MOVIMIENTOS.LITROS_MOVIMIENTO%TYPE,
    jDESCRIPCION_MOVIMIENTO TAB_MOVIMIENTOS.DESCRIPCION_MOVIMIENTO%TYPE,
    jFECHA_EVENTO TAB_MOVIMIENTOS.FECHA_EVENTO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    IF jTIPO_MOVIMIENTO IS NULL OR jTIPO_MOVIMIENTO NOT IN ('INGRESO', 'GASTO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Di si es un ingreso o un gasto');
        RETURN RETORNO;
    ELSIF jTIPO_MOVIMIENTO = 'INGRESO' AND jCATEGORIA_MOVIMIENTO IS DISTINCT FROM 'VENTA_LECHE' AND jCATEGORIA_MOVIMIENTO IS DISTINCT FROM 'OTRO_INGRESO' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige de dónde viene el ingreso (la venta de animales se anota como salida del animal)');
        RETURN RETORNO;
    ELSIF jTIPO_MOVIMIENTO = 'GASTO' AND (jCATEGORIA_MOVIMIENTO IS NULL OR jCATEGORIA_MOVIMIENTO NOT IN ('COMPRA_ANIMAL', 'DROGAS', 'SAL_CONCENTRADO', 'JORNALES', 'OTRO_GASTO')) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Elige en qué fue el gasto');
        RETURN RETORNO;
    ELSIF jVALOR_MOVIMIENTO IS NULL OR jVALOR_MOVIMIENTO <= 0 OR jVALOR_MOVIMIENTO > 9999999999 OR jVALOR_MOVIMIENTO <> TRUNC(jVALOR_MOVIMIENTO) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe el valor en pesos (sin centavos)');
        RETURN RETORNO;
    ELSIF jLITROS_MOVIMIENTO IS NOT NULL AND jCATEGORIA_MOVIMIENTO <> 'VENTA_LECHE' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los litros solo van en la venta de leche');
        RETURN RETORNO;
    ELSIF jLITROS_MOVIMIENTO IS NOT NULL AND (jLITROS_MOVIMIENTO <= 0 OR jLITROS_MOVIMIENTO > 1000000) THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los litros deben ser más de 0');
        RETURN RETORNO;
    ELSIF jCATEGORIA_MOVIMIENTO IN ('OTRO_INGRESO', 'OTRO_GASTO') AND (jDESCRIPCION_MOVIMIENTO IS NULL OR TRIM(jDESCRIPCION_MOVIMIENTO) = '') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Escribe qué fue (en «Otro» la descripción es obligatoria)');
        RETURN RETORNO;
    ELSIF jDESCRIPCION_MOVIMIENTO IS NOT NULL AND LENGTH(TRIM(jDESCRIPCION_MOVIMIENTO)) > 200 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La descripción es muy larga (máximo 200 caracteres)');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta la fecha');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO > NOW() + INTERVAL '1 day' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha no puede ser futura');
        RETURN RETORNO;
    ELSIF jFECHA_EVENTO < NOW() - INTERVAL '5 years' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha es de hace más de 5 años');
        RETURN RETORNO;
    END IF;
    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Todos los datos son válidos');
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA ANOTAR UN INGRESO O UN GASTO (SOLO EL DUEÑO)
CREATE OR REPLACE FUNCTION FUN_CREAR_MOVIMIENTO_JSON(
    jUUID_MOVIMIENTO TAB_MOVIMIENTOS.UUID_MOVIMIENTO%TYPE,
    jID_FINCA TAB_MOVIMIENTOS.ID_FINCA%TYPE,
    jTIPO_MOVIMIENTO TAB_MOVIMIENTOS.TIPO_MOVIMIENTO%TYPE,
    jCATEGORIA_MOVIMIENTO TAB_MOVIMIENTOS.CATEGORIA_MOVIMIENTO%TYPE,
    jVALOR_MOVIMIENTO TAB_MOVIMIENTOS.VALOR_MOVIMIENTO%TYPE,
    jLITROS_MOVIMIENTO TAB_MOVIMIENTOS.LITROS_MOVIMIENTO%TYPE,
    jDESCRIPCION_MOVIMIENTO TAB_MOVIMIENTOS.DESCRIPCION_MOVIMIENTO%TYPE,
    jFECHA_EVENTO TAB_MOVIMIENTOS.FECHA_EVENTO%TYPE,
    jID_USUARIO TAB_MOVIMIENTOS.USUARIO_CREACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jID_MOVIMIENTO INTEGER;
BEGIN
    --SI YA LLEGO ANTES (REINTENTO DE LA SINCRONIZACION), NO SE DUPLICA
    SELECT ID_MOVIMIENTO INTO jID_MOVIMIENTO FROM TAB_MOVIMIENTOS WHERE UUID_MOVIMIENTO = jUUID_MOVIMIENTO;
    IF jID_MOVIMIENTO IS NOT NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'El movimiento ya estaba guardado',
            'DATOS', json_build_object('ID_MOVIMIENTO', jID_MOVIMIENTO, 'YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (SOLO EL DUEÑO) Y LOS DATOS
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jUUID_MOVIMIENTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Falta el UUID del movimiento');
        RETURN RETORNO;
    END IF;
    jVALIDACION := FUN_VALIDAR_MOVIMIENTO(jTIPO_MOVIMIENTO, jCATEGORIA_MOVIMIENTO, jVALOR_MOVIMIENTO, jLITROS_MOVIMIENTO, jDESCRIPCION_MOVIMIENTO, jFECHA_EVENTO);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --INSERTAR EL MOVIMIENTO
    jID_MOVIMIENTO := funcion_Retorna_ultmoid('TAB_MOVIMIENTOS', 'ID_MOVIMIENTO');
    INSERT INTO TAB_MOVIMIENTOS (ID_MOVIMIENTO, UUID_MOVIMIENTO, ID_FINCA, FECHA_EVENTO, TIPO_MOVIMIENTO, CATEGORIA_MOVIMIENTO, VALOR_MOVIMIENTO,
        LITROS_MOVIMIENTO, DESCRIPCION_MOVIMIENTO, USUARIO_CREACION)
    VALUES (jID_MOVIMIENTO, jUUID_MOVIMIENTO, jID_FINCA, jFECHA_EVENTO, jTIPO_MOVIMIENTO, jCATEGORIA_MOVIMIENTO, jVALOR_MOVIMIENTO,
        jLITROS_MOVIMIENTO, NULLIF(TRIM(jDESCRIPCION_MOVIMIENTO), ''), jID_USUARIO);

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', CASE jTIPO_MOVIMIENTO WHEN 'INGRESO' THEN 'Ingreso anotado' ELSE 'Gasto anotado' END,
            'DATOS', json_build_object('ID_MOVIMIENTO', jID_MOVIMIENTO, 'YA_EXISTIA', false));
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al anotar el movimiento');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE TODA LA PLATA DE UN PERIODO EN UNA SOLA LISTA: LOS MOVIMIENTOS ANOTADOS Y LAS VENTAS DE ANIMALES (TAB_SALIDAS)
-- LA USAN FUN_OBTENER_PLATA_JSON Y SUS PRUEBAS. NO REVISA ACCESO: QUIEN LA LLAMA YA LO HIZO
CREATE OR REPLACE FUNCTION FUN_PLATA_DEL_PERIODO(
    jID_FINCA TAB_MOVIMIENTOS.ID_FINCA%TYPE,
    jINICIO DATE,
    jFIN DATE
) RETURNS TABLE (TIPO VARCHAR, CATEGORIA VARCHAR, VALOR NUMERIC, LITROS NUMERIC, FECHA DATE) AS
$$
    SELECT TIPO_MOVIMIENTO, CATEGORIA_MOVIMIENTO, VALOR_MOVIMIENTO, LITROS_MOVIMIENTO, FECHA_EVENTO::DATE
    FROM TAB_MOVIMIENTOS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_MOVIMIENTO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
    UNION ALL
    SELECT 'INGRESO', 'VENTA_ANIMAL', VALOR_SALIDA, NULL, FECHA_EVENTO::DATE
    FROM TAB_SALIDAS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_SALIDA = 'ACTIVO' AND TIPO_SALIDA = 'VENTA' AND VALOR_SALIDA > 0
      AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;
$$ LANGUAGE sql STABLE;



-- FUNCION QUE DEVUELVE EL RESUMEN DE LA PLATA DE UN PERIODO (SOLO EL DUEÑO). DESDE Y HASTA NULL = ESTE MES. MAXIMO 3 AÑOS
-- INGRESOS = MOVIMIENTOS DE INGRESO + VENTAS DE ANIMALES (TAB_SALIDAS VENTA CON VALOR). SALDO = INGRESOS - GASTOS
-- DATOS: {DESDE, HASTA, INGRESOS, GASTOS, SALDO, POR_CATEGORIA:[{TIPO, CATEGORIA, VALOR, CANTIDAD}],
--         POR_MES:[{MES, INGRESOS, GASTOS, SALDO}], LECHE:{LITROS, VALOR, PRECIO_LITRO}}
CREATE OR REPLACE FUNCTION FUN_OBTENER_PLATA_JSON(
    jID_FINCA TAB_MOVIMIENTOS.ID_FINCA%TYPE,
    jID_USUARIO TAB_MOVIMIENTOS.USUARIO_CREACION%TYPE,
    jDESDE DATE,
    jHASTA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jINICIO DATE;
    jFIN DATE;
    jINGRESOS NUMERIC;
    jGASTOS NUMERIC;
    jLITROS NUMERIC;
    jVALOR_LECHE_CON_LITROS NUMERIC;
    jVALOR_LECHE NUMERIC;
    LISTA_CATEGORIAS JSON;
    LISTA_MESES JSON;
BEGIN
    --VALIDAR EL ACCESO (SOLO EL DUEÑO)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --EL PERIODO
    jFIN := COALESCE(jHASTA, CURRENT_DATE);
    jINICIO := COALESCE(jDESDE, date_trunc('month', jFIN)::DATE);
    IF jINICIO > jFIN THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha inicial debe ser antes de la final');
        RETURN RETORNO;
    ELSIF jFIN - jINICIO > 1100 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El periodo puede ser de máximo 3 años');
        RETURN RETORNO;
    END IF;

    --TOTALES
    SELECT COALESCE(SUM(VALOR) FILTER (WHERE TIPO = 'INGRESO'), 0), COALESCE(SUM(VALOR) FILTER (WHERE TIPO = 'GASTO'), 0)
    INTO jINGRESOS, jGASTOS FROM FUN_PLATA_DEL_PERIODO(jID_FINCA, jINICIO, jFIN);

    --POR CATEGORIA (DE MAYOR A MENOR DENTRO DE CADA TIPO)
    SELECT json_agg(json_build_object('TIPO', T.TIPO, 'CATEGORIA', T.CATEGORIA, 'VALOR', T.VALOR, 'CANTIDAD', T.CANTIDAD) ORDER BY T.TIPO DESC, T.VALOR DESC)
    INTO LISTA_CATEGORIAS
    FROM (SELECT TIPO, CATEGORIA, SUM(VALOR) AS VALOR, COUNT(*) AS CANTIDAD FROM FUN_PLATA_DEL_PERIODO(jID_FINCA, jINICIO, jFIN) GROUP BY TIPO, CATEGORIA) T;

    --POR MES (SOLO LOS MESES CON MOVIMIENTOS)
    SELECT json_agg(json_build_object('MES', T.MES, 'INGRESOS', T.INGRESOS, 'GASTOS', T.GASTOS, 'SALDO', T.INGRESOS - T.GASTOS) ORDER BY T.MES)
    INTO LISTA_MESES
    FROM (SELECT to_char(FECHA, 'YYYY-MM') AS MES,
                 COALESCE(SUM(VALOR) FILTER (WHERE TIPO = 'INGRESO'), 0) AS INGRESOS,
                 COALESCE(SUM(VALOR) FILTER (WHERE TIPO = 'GASTO'), 0) AS GASTOS
          FROM FUN_PLATA_DEL_PERIODO(jID_FINCA, jINICIO, jFIN) GROUP BY to_char(FECHA, 'YYYY-MM')) T;

    --LA LECHE VENDIDA: EL PRECIO POR LITRO SOLO CON LAS VENTAS QUE TRAEN LITROS
    SELECT COALESCE(SUM(VALOR), 0), SUM(LITROS), SUM(VALOR) FILTER (WHERE LITROS IS NOT NULL)
    INTO jVALOR_LECHE, jLITROS, jVALOR_LECHE_CON_LITROS
    FROM FUN_PLATA_DEL_PERIODO(jID_FINCA, jINICIO, jFIN) WHERE CATEGORIA = 'VENTA_LECHE';

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Plata de la finca',
        'DATOS', json_build_object(
            'DESDE', jINICIO,
            'HASTA', jFIN,
            'INGRESOS', jINGRESOS,
            'GASTOS', jGASTOS,
            'SALDO', jINGRESOS - jGASTOS,
            'POR_CATEGORIA', COALESCE(LISTA_CATEGORIAS, '[]'::JSON),
            'POR_MES', COALESCE(LISTA_MESES, '[]'::JSON),
            'LECHE', json_build_object('LITROS', jLITROS, 'VALOR', jVALOR_LECHE,
                'PRECIO_LITRO', CASE WHEN jLITROS > 0 THEN ROUND(jVALOR_LECHE_CON_LITROS / jLITROS) END)));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_WHATSAPP/FUN_TAB_WHATSAPP.SQL ═══════════
-- FUNCIONES DEL RESUMEN DIARIO POR WHATSAPP (FASE 5D) ------------------------------------------------------------------------------------------
-- EL DUEÑO LO ACTIVA EN "MI FINCA" (RESUMEN_WHATSAPP_PERSONA = 'SI'); EL ADMINISTRADOR VINCULA EL NUMERO QUE MANDA Y PRENDE EL ENVIO (WHATSAPP_ACTIVO)
-- EL TEXTO SALE DE FUN_OBTENER_ALERTAS_JSON (LO MISMO DE "PARA HOY"). SIN ENLACES. SI NO HAY NADA URGENTE ESE DIA, NO SE MANDA NADA
-- CONFIGURACION (TAB_CONFIGURACION): INSTANCIA_WHATSAPP, HORA_RESUMEN_WHATSAPP (HH:MM, HORA DE COLOMBIA), WHATSAPP_ACTIVO (SI / NO)



-- FUNCION QUE ARMA EL TEXTO DEL RESUMEN DE UN DUEÑO PARA UN DIA. DEVUELVE {CODIGO, DATOS:{TEXTO, HAY_ALERTAS}}
-- HASTA 5 NOMBRES POR LISTA Y "Y N MAS"; LAS LISTAS VACIAS NO SALEN
CREATE OR REPLACE FUNCTION FUN_TEXTO_RESUMEN_WHATSAPP_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jFECHA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jALERTAS JSON;
    jA JSON;
    jNOM_FINCA VARCHAR;
    jLINEAS TEXT[] := ARRAY[]::TEXT[];
    jLINEA TEXT;
    jCICLO JSON;
BEGIN
    jALERTAS := FUN_OBTENER_ALERTAS_JSON(jID_FINCA, jID_USUARIO, jFECHA);
    IF (jALERTAS ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jALERTAS;
    END IF;
    jA := jALERTAS -> 'DATOS';
    SELECT NOM_FINCA INTO jNOM_FINCA FROM TAB_FINCAS WHERE ID_FINCA = jID_FINCA;

    --LECHE QUE NO SE VENDE (LO MAS URGENTE)
    jLINEA := FUN_LISTA_RESUMEN_WHATSAPP(jA -> 'RETIROS_LECHE', 'RETIRO');
    IF jLINEA IS NOT NULL THEN jLINEAS := jLINEAS || ('• No vender la leche de: ' || jLINEA); END IF;
    jLINEA := FUN_LISTA_RESUMEN_WHATSAPP(jA -> 'PARTOS_PROXIMOS', 'PARTO');
    IF jLINEA IS NOT NULL THEN jLINEAS := jLINEAS || ('• Partos próximos (' || json_array_length(jA -> 'PARTOS_PROXIMOS') || '): ' || jLINEA); END IF;
    jLINEA := FUN_LISTA_RESUMEN_WHATSAPP(jA -> 'PALPAR', NULL);
    IF jLINEA IS NOT NULL THEN jLINEAS := jLINEAS || ('• Para palpar (' || json_array_length(jA -> 'PALPAR') || '): ' || jLINEA); END IF;
    jLINEA := FUN_LISTA_RESUMEN_WHATSAPP(jA -> 'VACIAS', NULL);
    IF jLINEA IS NOT NULL THEN jLINEAS := jLINEAS || ('• Vacas vacías (' || json_array_length(jA -> 'VACIAS') || '): ' || jLINEA); END IF;
    jLINEA := FUN_LISTA_RESUMEN_WHATSAPP(jA -> 'VACUNAS_POR_APLICAR', 'VACUNA');
    IF jLINEA IS NOT NULL THEN jLINEAS := jLINEAS || ('• Vacunas por aplicar (' || json_array_length(jA -> 'VACUNAS_POR_APLICAR') || '): ' || jLINEA); END IF;
    FOR jCICLO IN SELECT C.value FROM json_array_elements(jA -> 'CICLOS_ICA') C WHERE (C.value ->> 'FALTAN')::INTEGER > 0 AND (C.value ->> 'VIGENTE')::BOOLEAN LOOP
        jLINEAS := jLINEAS || ('• Ciclo del ICA «' || (jCICLO ->> 'NOM_CICLO') || '»: faltan ' || (jCICLO ->> 'FALTAN') || ' animales por vacunar');
    END LOOP;

    IF array_length(jLINEAS, 1) IS NULL THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Nada urgente hoy',
            'DATOS', json_build_object('HAY_ALERTAS', false,
                'TEXTO', 'Ganadero · ' || jNOM_FINCA || E'\n' || 'Hoy ' || to_char(jFECHA, 'DD/MM') || ': nada urgente. Todo al día.'));
        RETURN RETORNO;
    END IF;
    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Resumen de hoy',
        'DATOS', json_build_object('HAY_ALERTAS', true,
            'TEXTO', 'Ganadero · ' || jNOM_FINCA || E'\n' || 'Para hoy, ' || to_char(jFECHA, 'DD/MM') || E':\n' || array_to_string(jLINEAS, E'\n')
                || E'\n' || 'Abre la app para ver el detalle.'));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE CONVIERTE UNA LISTA DE ALERTAS EN "23, 25 (en 13 días) y 2 más" (HASTA 5 ANIMALES). NULL SI LA LISTA ESTA VACIA
-- jDETALLE: 'PARTO' (EN N DIAS), 'VACUNA' (NOMBRE DE LA VACUNA), 'RETIRO' (HASTA EL DIA) O NULL (SOLO EL ANIMAL)
CREATE OR REPLACE FUNCTION FUN_LISTA_RESUMEN_WHATSAPP(
    jLISTA JSON,
    jDETALLE VARCHAR
) RETURNS TEXT AS
$$
DECLARE
    jTOTAL INTEGER;
    jTEXTO TEXT;
BEGIN
    jTOTAL := COALESCE(json_array_length(jLISTA), 0);
    IF jTOTAL = 0 THEN
        RETURN NULL;
    END IF;
    SELECT string_agg(COALESCE(E.value ->> 'CHAPETA_ANIMAL', E.value ->> 'NOM_ANIMAL', 'sin chapeta')
        || CASE jDETALLE
               WHEN 'PARTO' THEN CASE WHEN (E.value ->> 'DIAS')::INTEGER < 0 THEN ' (atrasado ' || -(E.value ->> 'DIAS')::INTEGER || ' días)'
                                      WHEN (E.value ->> 'DIAS')::INTEGER = 0 THEN ' (hoy)'
                                      ELSE ' (en ' || (E.value ->> 'DIAS') || ' días)' END
               WHEN 'VACUNA' THEN ' (' || (E.value ->> 'NOM_VACUNA') || ')'
               WHEN 'RETIRO' THEN ' (hasta el ' || to_char((E.value ->> 'FECHA_FIN_RETIRO')::DATE, 'DD/MM') || ')'
               ELSE '' END, ', ' ORDER BY E.posicion)
    INTO jTEXTO
    FROM json_array_elements(jLISTA) WITH ORDINALITY AS E(value, posicion)
    WHERE E.posicion <= 5;
    IF jTOTAL > 5 THEN
        jTEXTO := jTEXTO || ' y ' || (jTOTAL - 5) || ' más';
    END IF;
    RETURN jTEXTO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE PONE EN LA COLA EL RESUMEN DEL DIA DE CADA DUEÑO ACTIVO QUE LO PIDIO (LA LLAMA ms-logica A LA HORA DEL RESUMEN)
-- SOLO SI EL ADMINISTRADOR PRENDIO EL ENVIO (WHATSAPP_ACTIVO = SI) Y SOLO SI ESE DIA HAY ALGO URGENTE. NO REPITE (UNO POR DIA)
CREATE OR REPLACE FUNCTION FUN_ENCOLAR_RESUMENES_JSON(
    jFECHA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jPERSONA RECORD;
    jTEXTO JSON;
    jENCOLADOS INTEGER := 0;
    jSIN_NADA INTEGER := 0;
    jID_MENSAJE INTEGER;
BEGIN
    IF COALESCE((SELECT VALOR_CONFIGURACION FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = 'WHATSAPP_ACTIVO'), 'NO') <> 'SI' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El envío por WhatsApp está apagado');
        RETURN RETORNO;
    END IF;

    FOR jPERSONA IN
        SELECT P.ID_FINCA, P.ID_USUARIO FROM TAB_FINCAS_PERSONAS P JOIN TAB_FINCAS F ON F.ID_FINCA = P.ID_FINCA
        WHERE P.ROL_FINCA = 'DUENIO' AND P.ESTADO_FINCA_PERSONA = 'ACTIVO' AND P.RESUMEN_WHATSAPP_PERSONA = 'SI'
          AND NOT EXISTS (SELECT 1 FROM TAB_MENSAJES_WHATSAPP M WHERE M.ID_FINCA = P.ID_FINCA AND M.ID_USUARIO = P.ID_USUARIO AND M.FECHA_RESUMEN = jFECHA)
        ORDER BY P.ID_FINCA_PERSONA
    LOOP
        jTEXTO := FUN_TEXTO_RESUMEN_WHATSAPP_JSON(jPERSONA.ID_FINCA, jPERSONA.ID_USUARIO, jFECHA);
        IF (jTEXTO ->> 'CODIGO')::INTEGER = 200 AND (jTEXTO -> 'DATOS' ->> 'HAY_ALERTAS')::BOOLEAN THEN
            jID_MENSAJE := funcion_Retorna_ultmoid('TAB_MENSAJES_WHATSAPP', 'ID_MENSAJE');
            INSERT INTO TAB_MENSAJES_WHATSAPP (ID_MENSAJE, ID_FINCA, ID_USUARIO, FECHA_RESUMEN, TEXTO_MENSAJE, USUARIO_CREACION)
            VALUES (jID_MENSAJE, jPERSONA.ID_FINCA, jPERSONA.ID_USUARIO, jFECHA, jTEXTO -> 'DATOS' ->> 'TEXTO', 'SISTEMA')
            ON CONFLICT ON CONSTRAINT UQ_MENSAJE_DIA DO NOTHING;
            IF FOUND THEN
                jENCOLADOS := jENCOLADOS + 1;
            END IF;
        ELSE
            jSIN_NADA := jSIN_NADA + 1;
        END IF;
    END LOOP;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', jENCOLADOS || ' resúmenes en la cola',
        'DATOS', json_build_object('ENCOLADOS', jENCOLADOS, 'SIN_NADA_URGENTE', jSIN_NADA));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LOS MENSAJES POR MANDAR (EN ORDEN), HASTA jLIMITE. LISTA VACIA = 404
CREATE OR REPLACE FUNCTION FUN_OBTENER_MENSAJES_PENDIENTES_JSON(
    jLIMITE INTEGER
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    LISTA_MENSAJES JSON;
BEGIN
    SELECT json_agg(json_build_object('ID_MENSAJE', T.ID_MENSAJE, 'ID_USUARIO', T.ID_USUARIO, 'TEXTO_MENSAJE', T.TEXTO_MENSAJE) ORDER BY T.ID_MENSAJE)
    INTO LISTA_MENSAJES
    FROM (SELECT ID_MENSAJE, ID_USUARIO, TEXTO_MENSAJE FROM TAB_MENSAJES_WHATSAPP
          WHERE ESTADO_MENSAJE = 'PENDIENTE' ORDER BY ID_MENSAJE LIMIT GREATEST(COALESCE(jLIMITE, 20), 1)) T;
    IF LISTA_MENSAJES IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'No hay mensajes por mandar');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Mensajes por mandar', 'DATOS', LISTA_MENSAJES);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE ANOTA COMO LE FUE A UN MENSAJE. jRESULTADO: ENVIADO, SIN_NUMERO O ERROR (A LOS 3 ERRORES QUEDA FALLIDO)
CREATE OR REPLACE FUNCTION FUN_MARCAR_MENSAJE_WHATSAPP_JSON(
    jID_MENSAJE TAB_MENSAJES_WHATSAPP.ID_MENSAJE%TYPE,
    jRESULTADO VARCHAR,
    jERROR TAB_MENSAJES_WHATSAPP.ERROR_MENSAJE%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    IF jRESULTADO NOT IN ('ENVIADO', 'SIN_NUMERO', 'ERROR') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Resultado no válido');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_MENSAJES_WHATSAPP
    SET INTENTOS_MENSAJE = INTENTOS_MENSAJE + 1,
        ESTADO_MENSAJE = CASE WHEN jRESULTADO = 'ENVIADO' THEN 'ENVIADO' WHEN jRESULTADO = 'SIN_NUMERO' THEN 'SIN_NUMERO'
                              WHEN INTENTOS_MENSAJE + 1 >= 3 THEN 'FALLIDO' ELSE 'PENDIENTE' END,
        ERROR_MENSAJE = CASE WHEN jRESULTADO = 'ENVIADO' THEN NULL ELSE left(jERROR, 300) END,
        FECHA_ENVIO_MENSAJE = CASE WHEN jRESULTADO = 'ENVIADO' THEN LOCALTIMESTAMP ELSE FECHA_ENVIO_MENSAJE END,
        USUARIO_MODIFICACION = 'SISTEMA',
        FECHA_MODIFICACION = NOW()
    WHERE ID_MENSAJE = jID_MENSAJE AND ESTADO_MENSAJE = 'PENDIENTE';

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Mensaje actualizado');
    ELSE
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Ese mensaje no está pendiente');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION PARA QUE EL DUEÑO PRENDA O APAGUE SU RESUMEN DIARIO EN UNA FINCA
CREATE OR REPLACE FUNCTION FUN_CAMBIAR_RESUMEN_WHATSAPP_JSON(
    jID_FINCA TAB_FINCAS_PERSONAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jACTIVO TAB_FINCAS_PERSONAS.RESUMEN_WHATSAPP_PERSONA%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jACTIVO IS NULL OR jACTIVO NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Di si quieres el resumen (SI o NO)');
        RETURN RETORNO;
    END IF;

    UPDATE TAB_FINCAS_PERSONAS
    SET RESUMEN_WHATSAPP_PERSONA = jACTIVO,
        USUARIO_MODIFICACION = jID_USUARIO,
        FECHA_MODIFICACION = NOW()
    WHERE ID_FINCA = jID_FINCA AND ID_USUARIO = jID_USUARIO;

    IF FOUND THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', CASE jACTIVO WHEN 'SI' THEN 'Listo: te llega el resumen cada mañana que haya algo para hacer'
            ELSE 'Listo: ya no te llega el resumen' END);
    ELSE
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', 'Error al guardar el resumen');
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE COMO ESTA EL RESUMEN DE UN DUEÑO EN UNA FINCA: SI LO PIDIO, SI EL ENVIO ESTA PRENDIDO, LA HORA, EL TEXTO DE HOY Y EL ULTIMO
CREATE OR REPLACE FUNCTION FUN_OBTENER_RESUMEN_WHATSAPP_JSON(
    jID_FINCA TAB_FINCAS_PERSONAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jACTIVO VARCHAR;
    jTEXTO JSON;
    jULTIMO JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT RESUMEN_WHATSAPP_PERSONA INTO jACTIVO FROM TAB_FINCAS_PERSONAS WHERE ID_FINCA = jID_FINCA AND ID_USUARIO = jID_USUARIO;
    jTEXTO := FUN_TEXTO_RESUMEN_WHATSAPP_JSON(jID_FINCA, jID_USUARIO, CURRENT_DATE);
    SELECT json_build_object('FECHA_RESUMEN', FECHA_RESUMEN, 'ESTADO_MENSAJE', ESTADO_MENSAJE, 'FECHA_ENVIO_MENSAJE', FECHA_ENVIO_MENSAJE) INTO jULTIMO
    FROM TAB_MENSAJES_WHATSAPP WHERE ID_FINCA = jID_FINCA AND ID_USUARIO = jID_USUARIO ORDER BY FECHA_RESUMEN DESC LIMIT 1;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Resumen por WhatsApp',
        'DATOS', json_build_object(
            'ACTIVO', jACTIVO = 'SI',
            'ENVIO_PRENDIDO', COALESCE((SELECT VALOR_CONFIGURACION FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = 'WHATSAPP_ACTIVO'), 'NO') = 'SI',
            'HORA', COALESCE((SELECT VALOR_CONFIGURACION FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = 'HORA_RESUMEN_WHATSAPP'), '06:00'),
            'TEXTO_HOY', jTEXTO -> 'DATOS' ->> 'TEXTO',
            'HAY_ALERTAS_HOY', (jTEXTO -> 'DATOS' ->> 'HAY_ALERTAS')::BOOLEAN,
            'ULTIMO', jULTIMO));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LA CONFIGURACION DEL WHATSAPP (PANTALLA DEL ADMINISTRADOR; EL PERMISO LO REVISA ms-logica CON EL MENU 7)
-- MAS LO QUE PASO HOY CON LA COLA
CREATE OR REPLACE FUNCTION FUN_OBTENER_CONFIG_WHATSAPP_JSON() RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Configuración del WhatsApp',
        'DATOS', json_build_object(
            'INSTANCIA', COALESCE((SELECT VALOR_CONFIGURACION FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = 'INSTANCIA_WHATSAPP'), 'ganadero'),
            'HORA', COALESCE((SELECT VALOR_CONFIGURACION FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = 'HORA_RESUMEN_WHATSAPP'), '06:00'),
            'ACTIVO', COALESCE((SELECT VALOR_CONFIGURACION FROM TAB_CONFIGURACION WHERE NOM_CONFIGURACION = 'WHATSAPP_ACTIVO'), 'NO') = 'SI',
            'DUENIOS_CON_RESUMEN', (SELECT COUNT(*) FROM TAB_FINCAS_PERSONAS WHERE ROL_FINCA = 'DUENIO' AND ESTADO_FINCA_PERSONA = 'ACTIVO' AND RESUMEN_WHATSAPP_PERSONA = 'SI'),
            'HOY', (SELECT json_build_object(
                        'ENVIADOS', COUNT(*) FILTER (WHERE ESTADO_MENSAJE = 'ENVIADO'),
                        'PENDIENTES', COUNT(*) FILTER (WHERE ESTADO_MENSAJE = 'PENDIENTE'),
                        'FALLIDOS', COUNT(*) FILTER (WHERE ESTADO_MENSAJE IN ('FALLIDO', 'SIN_NUMERO')))
                    FROM TAB_MENSAJES_WHATSAPP WHERE FECHA_RESUMEN = CURRENT_DATE)));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE GUARDA LA CONFIGURACION DEL WHATSAPP (ADMINISTRADOR): TODO O NADA (BLOQUE BEGIN ... EXCEPTION)
CREATE OR REPLACE FUNCTION FUN_GUARDAR_CONFIG_WHATSAPP_JSON(
    jINSTANCIA VARCHAR,
    jHORA VARCHAR,
    jACTIVO VARCHAR,
    jID_USUARIO TAB_CONFIGURACION.USUARIO_MODIFICACION%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
BEGIN
    IF jINSTANCIA IS NULL OR jINSTANCIA !~ '^[A-Za-z0-9_-]{1,50}$' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El nombre de la instancia solo lleva letras, números, - y _ (máximo 50)');
        RETURN RETORNO;
    ELSIF jHORA IS NULL OR jHORA !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La hora va como 06:00 (de 00:00 a 23:59)');
        RETURN RETORNO;
    ELSIF jACTIVO IS NULL OR jACTIVO NOT IN ('SI', 'NO') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Di si el envío queda prendido (SI o NO)');
        RETURN RETORNO;
    END IF;

    BEGIN
        UPDATE TAB_CONFIGURACION SET VALOR_CONFIGURACION = jINSTANCIA, USUARIO_MODIFICACION = jID_USUARIO, FECHA_MODIFICACION = NOW() WHERE NOM_CONFIGURACION = 'INSTANCIA_WHATSAPP';
        IF NOT FOUND THEN RAISE EXCEPTION 'Falta INSTANCIA_WHATSAPP en la configuración (corre la migración 004)'; END IF;
        UPDATE TAB_CONFIGURACION SET VALOR_CONFIGURACION = jHORA, USUARIO_MODIFICACION = jID_USUARIO, FECHA_MODIFICACION = NOW() WHERE NOM_CONFIGURACION = 'HORA_RESUMEN_WHATSAPP';
        IF NOT FOUND THEN RAISE EXCEPTION 'Falta HORA_RESUMEN_WHATSAPP en la configuración (corre la migración 004)'; END IF;
        UPDATE TAB_CONFIGURACION SET VALOR_CONFIGURACION = jACTIVO, USUARIO_MODIFICACION = jID_USUARIO, FECHA_MODIFICACION = NOW() WHERE NOM_CONFIGURACION = 'WHATSAPP_ACTIVO';
        IF NOT FOUND THEN RAISE EXCEPTION 'Falta WHATSAPP_ACTIVO en la configuración (corre la migración 004)'; END IF;
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', CASE jACTIVO WHEN 'SI' THEN 'Guardado: el resumen sale cada día a las ' || jHORA ELSE 'Guardado: el envío quedó apagado' END);
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_EVENTOS/FUN_TAB_EVENTOS.SQL ═══════════
-- FUNCIONES COMUNES A TODOS LOS EVENTOS -------------------------------------------------------------------------------------------------------------
-- ANULAR ES IGUAL PARA LOS SIETE EVENTOS: SE CAMBIA EL ESTADO A ANULADO, SALE DE LA LINEA DE TIEMPO Y DE LOS CALCULOS Y BAJA A TODOS LOS CELULARES
-- SOLO EL DUEÑO ANULA (EL VAQUERO Y EL VETERINARIO REGISTRAN PERO NO CORRIGEN NI ANULAN, COMO EN menurol)



-- FUNCION PARA ANULAR UN EVENTO. jTIPO: PESAJE, VACUNACION, SERVICIO, PALPACION, PARTO, ORDENO, SALIDA, MOVIMIENTO (PLATA, FASE 5B)
-- PARTO CON CRIA: SE ANULAN TAMBIEN LA CRIA Y SUS PESAJES (BLOQUE BEGIN ... EXCEPTION), SI LA CRIA NO TIENE OTROS REGISTROS NI CRIAS
-- SALIDA: AL ANULARLA, EL TRIGGER TRG_SALIDA_ANIMAL DEVUELVE EL ANIMAL A ACTIVO
-- SI YA ESTABA ANULADO RESPONDE 200 CON YA_EXISTIA (REINTENTO SEGURO DESDE LA SINCRONIZACION)
CREATE OR REPLACE FUNCTION FUN_ANULAR_EVENTO_JSON(
    jTIPO VARCHAR,
    jUUID UUID,
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jTABLA JSON;
    jID_EVENTO INTEGER;
    jESTADO VARCHAR;
    jID_CRIA INTEGER;
    jFILAS INTEGER;
BEGIN
    --EL TIPO SALE DE LA LISTA BLANCA (LOTES Y ANIMALES TIENEN SU PROPIA FUNCION DE ANULAR)
    jTABLA := FUN_TABLA_POR_TIPO(jTIPO);
    IF jTABLA IS NULL OR UPPER(TRIM(jTIPO)) IN ('LOTE', 'ANIMAL') THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Tipo de evento no válido');
        RETURN RETORNO;
    END IF;

    --VALIDAR EL ACCESO (SOLO EL DUEÑO)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --BUSCAR EL EVENTO EN SU TABLA (LOS NOMBRES VIENEN DE FUN_TABLA_POR_TIPO, NUNCA DE AFUERA)
    EXECUTE format('SELECT %s, %s FROM %s WHERE %s = $1 AND ID_FINCA = $2',
            jTABLA ->> 'ID', jTABLA ->> 'ESTADO', jTABLA ->> 'TABLA', jTABLA ->> 'UUID')
        INTO jID_EVENTO, jESTADO USING jUUID, jID_FINCA;

    IF jID_EVENTO IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Ese registro no existe en esta finca');
        RETURN RETORNO;
    ELSIF jESTADO = 'ANULADO' THEN
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ya estaba anulado', 'DATOS', json_build_object('YA_EXISTIA', true));
        RETURN RETORNO;
    END IF;

    --PARTO CON CRIA: LA CRIA NO PUEDE TENER OTROS REGISTROS (FUERA DE SUS PESAJES) NI CRIAS
    IF UPPER(TRIM(jTIPO)) = 'PARTO' THEN
        SELECT ID_CRIA INTO jID_CRIA FROM TAB_PARTOS WHERE ID_PARTO = jID_EVENTO;
        IF jID_CRIA IS NOT NULL AND (
               EXISTS (SELECT 1 FROM TAB_VACUNACIONES WHERE ID_ANIMAL = jID_CRIA AND ESTADO_VACUNACION = 'ACTIVO')
            OR EXISTS (SELECT 1 FROM TAB_SERVICIOS WHERE (ID_ANIMAL = jID_CRIA OR ID_TORO = jID_CRIA) AND ESTADO_SERVICIO = 'ACTIVO')
            OR EXISTS (SELECT 1 FROM TAB_PALPACIONES WHERE ID_ANIMAL = jID_CRIA AND ESTADO_PALPACION = 'ACTIVO')
            OR EXISTS (SELECT 1 FROM TAB_PARTOS WHERE ID_ANIMAL = jID_CRIA AND ESTADO_PARTO = 'ACTIVO')
            OR EXISTS (SELECT 1 FROM TAB_ORDENOS WHERE ID_ANIMAL = jID_CRIA AND ESTADO_ORDENO = 'ACTIVO')
            OR EXISTS (SELECT 1 FROM TAB_SALIDAS WHERE ID_ANIMAL = jID_CRIA AND ESTADO_SALIDA = 'ACTIVO')
            OR EXISTS (SELECT 1 FROM TAB_ANIMALES WHERE (ID_MADRE = jID_CRIA OR ID_PADRE = jID_CRIA) AND ESTADO_ANIMAL <> 'ANULADO')) THEN
            RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La cría de este parto ya tiene registros propios: anúlalos primero');
            RETURN RETORNO;
        END IF;
    END IF;

    BEGIN
        --ANULAR EL EVENTO (EXECUTE NO CAMBIA FOUND: SE REVISA CON ROW_COUNT)
        EXECUTE format('UPDATE %s SET %s = ''ANULADO'', USUARIO_MODIFICACION = $1, FECHA_MODIFICACION = NOW() WHERE %s = $2',
                jTABLA ->> 'TABLA', jTABLA ->> 'ESTADO', jTABLA ->> 'ID')
            USING jID_USUARIO, jID_EVENTO;
        GET DIAGNOSTICS jFILAS = ROW_COUNT;
        IF jFILAS = 0 THEN
            RAISE EXCEPTION 'No se pudo anular el registro';
        END IF;

        --PARTO CON CRIA: SUS PESAJES Y LA CRIA (PUEDE QUE NO TENGA PESAJES: ESE UPDATE NO SE REVISA)
        IF jID_CRIA IS NOT NULL THEN
            UPDATE TAB_PESAJES
            SET ESTADO_PESAJE = 'ANULADO',
                USUARIO_MODIFICACION = jID_USUARIO,
                FECHA_MODIFICACION = NOW()
            WHERE ID_ANIMAL = jID_CRIA AND ESTADO_PESAJE = 'ACTIVO';

            UPDATE TAB_ANIMALES
            SET ESTADO_ANIMAL = 'ANULADO',
                USUARIO_MODIFICACION = jID_USUARIO,
                FECHA_MODIFICACION = NOW()
            WHERE ID_ANIMAL = jID_CRIA;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'No se pudo anular la cría del parto';
            END IF;
        END IF;

        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE',
            CASE WHEN jID_CRIA IS NOT NULL THEN 'Parto anulado junto con su cría' ELSE 'Registro anulado' END,
            'DATOS', json_build_object('YA_EXISTIA', false));
    EXCEPTION WHEN OTHERS THEN
        RETORNO := json_build_object('CODIGO', 500, 'MENSAJE', SQLERRM);
    END;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_SINCRONIZACION/FUN_TAB_SINCRONIZACION.SQL ═══════════
-- FUNCIONES DEL MOTOR DE SINCRONIZACION -------------------------------------------------------------------------------------------------------------
-- DOS PASOS, SIEMPRE EN ESTE ORDEN: PRIMERO SE SUBE LO DEL CELULAR (FUN_SINCRONIZAR_REGISTROS_JSON) Y DESPUES SE BAJA LO DE LOS DEMAS
-- (FUN_OBTENER_CAMBIOS_JSON). CONTRATO COMPLETO EN PLAN_GANADERO.md, SECCION 4
--
-- CADA REGISTRO DE LA BANDEJA DE SALIDA DEL CELULAR:
--   { "orden": 57, "uuid": "8f3c...", "tipo": "PESAJE", "operacion": "CREAR", "datos": { "uuid_animal": "a91d...", "peso_kg": 412, ... } }
-- tipo: LOTE, ANIMAL, PESAJE, VACUNACION, SERVICIO, PALPACION, PARTO, ORDENO, SALIDA, POTRERO, OCUPACION (FASE 5A), MOVIMIENTO (FASE 5B, SOLO EL DUEÑO)
-- operacion: CREAR (TODOS), EDITAR (LOTE, ANIMAL, POTRERO Y OCUPACION = SACAR EL LOTE DEL POTRERO), ANULAR (TODOS)
-- LAS CLAVES DE "datos" SON LOS NOMBRES DE LAS COLUMNAS EN MINUSCULAS (VER CADA RAMA DE FUN_SINCRONIZAR_REGISTROS_JSON)



-- FUNCION QUE SUBE LA BANDEJA DE SALIDA DEL CELULAR (LOTES DE HASTA LOTE_MAXIMO_SINCRONIZACION REGISTROS)
-- RECORRE LOS REGISTROS EN EL ORDEN EN QUE LLEGAN Y LLAMA A LA MISMA FUNCION QUE SE USA EN LINEA (MISMAS REGLAS)
-- CADA REGISTRO VA EN SU PROPIO BEGIN ... EXCEPTION: SI UNO FALLA, SOLO ESE SE RECHAZA Y LOS DEMAS SE GUARDAN.
-- ES UNA EXCEPCION JUSTIFICADA AL "TODO O NADA": UN PESAJE MALO NO DEBE FRENAR LOS OTROS 49. DENTRO DE CADA REGISTRO SE MANTIENE
-- EL ROLLBACK REAL (UN PARTO Y SU CRIA ENTRAN JUNTOS O NINGUNO)
-- ESTADO DE CADA REGISTRO: OK (GUARDADO), YA_EXISTIA (YA HABIA LLEGADO: EL CELULAR LO BORRA DE LA BANDEJA), RECHAZADO (CON MENSAJE)
CREATE OR REPLACE FUNCTION FUN_SINCRONIZAR_REGISTROS_JSON(
    jID_FINCA TAB_SINCRONIZACIONES.ID_FINCA%TYPE,
    jID_USUARIO TAB_SINCRONIZACIONES.ID_USUARIO%TYPE,
    jREGISTROS JSON
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jREGISTRO JSON;
    jDATOS JSON;
    jTIPO VARCHAR;
    jOPERACION VARCHAR;
    jUUID UUID;
    jRESULTADO JSON;
    jESTADO VARCHAR;
    jMAXIMO INTEGER;
    jRECIBIDOS INTEGER;
    jGUARDADOS INTEGER := 0;
    jOMITIDOS INTEGER := 0;
    jRECHAZADOS INTEGER := 0;
    LISTA_RESULTADOS JSON[] := ARRAY[]::JSON[];
    LISTA_RECHAZADOS JSON[] := ARRAY[]::JSON[];
    jID_SINCRONIZACION INTEGER;
BEGIN
    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA; CADA FUNCION REVISA DESPUES SU PROPIO PERMISO)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --VALIDAR EL LOTE
    jMAXIMO := COALESCE(FUN_CONFIGURACION_NUMERO('LOTE_MAXIMO_SINCRONIZACION'), 50)::INTEGER;
    IF jREGISTROS IS NULL OR json_typeof(jREGISTROS) <> 'array' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Los registros deben llegar en una lista');
        RETURN RETORNO;
    END IF;
    jRECIBIDOS := json_array_length(jREGISTROS);
    IF jRECIBIDOS = 0 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'No hay registros para subir');
        RETURN RETORNO;
    ELSIF jRECIBIDOS > jMAXIMO THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'Máximo ' || jMAXIMO || ' registros por envío');
        RETURN RETORNO;
    END IF;

    --RECORRER LOS REGISTROS EN EL ORDEN EN QUE LLEGARON (UN ANIMAL CREADO SIN SEÑAL LLEGA ANTES QUE SUS EVENTOS)
    FOR jREGISTRO IN SELECT R.value FROM json_array_elements(jREGISTROS) WITH ORDINALITY AS R(value, posicion) ORDER BY R.posicion LOOP
        jTIPO := UPPER(TRIM(jREGISTRO ->> 'tipo'));
        jOPERACION := UPPER(TRIM(COALESCE(jREGISTRO ->> 'operacion', 'CREAR')));
        jDATOS := COALESCE(jREGISTRO -> 'datos', '{}'::JSON);
        jUUID := NULL;

        BEGIN
            jUUID := NULLIF(jREGISTRO ->> 'uuid', '')::UUID;
            IF jUUID IS NULL THEN
                jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', 'El registro no trae UUID');

            --CREAR
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'LOTE' THEN
                jRESULTADO := FUN_CREAR_LOTE_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_lote', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'ANIMAL' THEN
                jRESULTADO := FUN_CREAR_ANIMAL_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_lote', '')::UUID, (jDATOS ->> 'id_raza')::INTEGER,
                    jDATOS ->> 'chapeta_animal', jDATOS ->> 'nom_animal', jDATOS ->> 'sexo_animal', (jDATOS ->> 'fecha_nacimiento')::DATE,
                    jDATOS ->> 'fecha_nacimiento_estimada', NULLIF(jDATOS ->> 'uuid_madre', '')::UUID, NULLIF(jDATOS ->> 'uuid_padre', '')::UUID,
                    jDATOS ->> 'padre_externo', jDATOS ->> 'origen_animal', (jDATOS ->> 'fecha_ingreso_animal')::DATE, jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'PESAJE' THEN
                jRESULTADO := FUN_CREAR_PESAJE_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, (jDATOS ->> 'peso_kg')::NUMERIC,
                    COALESCE(jDATOS ->> 'estimado_cinta', 'NO'), (jDATOS ->> 'perimetro_cm')::NUMERIC, (jDATOS ->> 'fecha_evento')::TIMESTAMP,
                    jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'VACUNACION' THEN
                jRESULTADO := FUN_CREAR_VACUNACION_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, (jDATOS ->> 'id_vacuna')::INTEGER,
                    jDATOS ->> 'dosis_vacunacion', (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'SERVICIO' THEN
                jRESULTADO := FUN_CREAR_SERVICIO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'tipo_servicio',
                    NULLIF(jDATOS ->> 'uuid_toro', '')::UUID, jDATOS ->> 'toro_externo', (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'PALPACION' THEN
                jRESULTADO := FUN_CREAR_PALPACION_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'resultado_palpacion',
                    (jDATOS ->> 'meses_gestacion')::INTEGER, (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'PARTO' THEN
                jRESULTADO := FUN_CREAR_PARTO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'tipo_parto', jDATOS ->> 'cria_viva',
                    NULLIF(jDATOS ->> 'uuid_cria', '')::UUID, jDATOS ->> 'sexo_cria', jDATOS ->> 'chapeta_cria', jDATOS ->> 'nom_cria',
                    (jDATOS ->> 'peso_cria_kg')::NUMERIC, (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'ORDENO' THEN
                jRESULTADO := FUN_CREAR_ORDENO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'jornada_ordeno',
                    (jDATOS ->> 'litros_ordeno')::NUMERIC, (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'SALIDA' THEN
                jRESULTADO := FUN_CREAR_SALIDA_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_animal', '')::UUID, jDATOS ->> 'tipo_salida',
                    (jDATOS ->> 'valor_salida')::NUMERIC, (jDATOS ->> 'peso_salida_kg')::NUMERIC, jDATOS ->> 'causa_salida',
                    (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'POTRERO' THEN
                jRESULTADO := FUN_CREAR_POTRERO_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_potrero', (jDATOS ->> 'area_potrero')::NUMERIC,
                    (jDATOS ->> 'dias_descanso_potrero')::INTEGER, jDATOS -> 'contorno_potrero', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'OCUPACION' THEN
                jRESULTADO := FUN_ENTRAR_LOTE_POTRERO_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_lote', '')::UUID, NULLIF(jDATOS ->> 'uuid_potrero', '')::UUID,
                    (jDATOS ->> 'fecha_evento')::TIMESTAMP, jDATOS ->> 'observacion', jID_USUARIO);
            ELSIF jOPERACION = 'CREAR' AND jTIPO = 'MOVIMIENTO' THEN
                jRESULTADO := FUN_CREAR_MOVIMIENTO_JSON(jUUID, jID_FINCA, jDATOS ->> 'tipo_movimiento', jDATOS ->> 'categoria_movimiento',
                    (jDATOS ->> 'valor_movimiento')::NUMERIC, (jDATOS ->> 'litros_movimiento')::NUMERIC, jDATOS ->> 'descripcion_movimiento',
                    (jDATOS ->> 'fecha_evento')::TIMESTAMP, jID_USUARIO);

            --EDITAR (GANA EL ULTIMO QUE SINCRONIZA)
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'LOTE' THEN
                jRESULTADO := FUN_ACTUALIZAR_LOTE_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_lote', jID_USUARIO);
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'ANIMAL' THEN
                jRESULTADO := FUN_ACTUALIZAR_ANIMAL_JSON(jUUID, jID_FINCA, NULLIF(jDATOS ->> 'uuid_lote', '')::UUID, (jDATOS ->> 'id_raza')::INTEGER,
                    jDATOS ->> 'chapeta_animal', jDATOS ->> 'nom_animal', jDATOS ->> 'sexo_animal', (jDATOS ->> 'fecha_nacimiento')::DATE,
                    jDATOS ->> 'fecha_nacimiento_estimada', NULLIF(jDATOS ->> 'uuid_madre', '')::UUID, NULLIF(jDATOS ->> 'uuid_padre', '')::UUID,
                    jDATOS ->> 'padre_externo', jDATOS ->> 'origen_animal', (jDATOS ->> 'fecha_ingreso_animal')::DATE, jID_USUARIO);
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'POTRERO' THEN
                jRESULTADO := FUN_ACTUALIZAR_POTRERO_JSON(jUUID, jID_FINCA, jDATOS ->> 'nom_potrero', (jDATOS ->> 'area_potrero')::NUMERIC,
                    (jDATOS ->> 'dias_descanso_potrero')::INTEGER, jDATOS -> 'contorno_potrero', jID_USUARIO);
            ELSIF jOPERACION = 'EDITAR' AND jTIPO = 'OCUPACION' THEN
                jRESULTADO := FUN_SACAR_LOTE_POTRERO_JSON(jUUID, jID_FINCA, (jDATOS ->> 'fecha_salida_ocupacion')::TIMESTAMP, jID_USUARIO);

            --ANULAR
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'LOTE' THEN
                jRESULTADO := FUN_ANULAR_LOTE_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'ANIMAL' THEN
                jRESULTADO := FUN_ANULAR_ANIMAL_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'POTRERO' THEN
                jRESULTADO := FUN_ANULAR_POTRERO_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND jTIPO = 'OCUPACION' THEN
                jRESULTADO := FUN_ANULAR_OCUPACION_JSON(jUUID, jID_FINCA, jID_USUARIO);
            ELSIF jOPERACION = 'ANULAR' AND FUN_TABLA_POR_TIPO(jTIPO) IS NOT NULL THEN
                jRESULTADO := FUN_ANULAR_EVENTO_JSON(jTIPO, jUUID, jID_FINCA, jID_USUARIO);

            ELSE
                jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', 'Tipo u operación no soportada: ' || COALESCE(jTIPO, '?') || ' ' || jOPERACION);
            END IF;

            --SI LA FUNCION NO GUARDO, SE DESHACE LO QUE HUBIERA HECHO ESTE REGISTRO (SOLO ESTE)
            IF (jRESULTADO ->> 'CODIGO')::INTEGER != 200 THEN
                RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = jRESULTADO ->> 'MENSAJE';
            END IF;
        EXCEPTION
            WHEN unique_violation THEN
                --DOS CELULARES SUBIERON LO MISMO A LA VEZ: EL OTRO YA LO GUARDO (YA_EXISTIA). SI EL CHOQUE FUE CON OTRA REGLA UNICA
                --(POR EJEMPLO LA MISMA JORNADA DE ORDEÑO DESDE DOS CELULARES), SE RECHAZA CON UN MENSAJE CLARO
                IF FUN_EXISTE_UUID(jTIPO, jUUID) THEN
                    jRESULTADO := json_build_object('CODIGO', 200, 'MENSAJE', 'Ya estaba guardado', 'DATOS', json_build_object('YA_EXISTIA', true));
                ELSE
                    jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', 'Otro celular guardó lo mismo al mismo tiempo. Sincroniza de nuevo para verlo');
                END IF;
            WHEN OTHERS THEN
                --DATOS MAL FORMADOS (UUID O FECHA INVALIDA) O RECHAZO DE LA FUNCION
                jRESULTADO := json_build_object('CODIGO', 400, 'MENSAJE', SQLERRM);
        END;

        --CLASIFICAR EL RESULTADO
        IF (jRESULTADO ->> 'CODIGO')::INTEGER = 200 AND COALESCE((jRESULTADO -> 'DATOS' ->> 'YA_EXISTIA')::BOOLEAN, false) THEN
            jESTADO := 'YA_EXISTIA';
            jOMITIDOS := jOMITIDOS + 1;
        ELSIF (jRESULTADO ->> 'CODIGO')::INTEGER = 200 THEN
            jESTADO := 'OK';
            jGUARDADOS := jGUARDADOS + 1;
        ELSE
            jESTADO := 'RECHAZADO';
            jRECHAZADOS := jRECHAZADOS + 1;
            LISTA_RECHAZADOS := LISTA_RECHAZADOS || json_build_object('UUID', jREGISTRO ->> 'uuid', 'TIPO', jTIPO, 'OPERACION', jOPERACION, 'MENSAJE', jRESULTADO ->> 'MENSAJE');
        END IF;

        LISTA_RESULTADOS := LISTA_RESULTADOS || json_build_object(
            'UUID', jREGISTRO ->> 'uuid',
            'ORDEN', jREGISTRO -> 'orden',
            'ESTADO', jESTADO,
            'MENSAJE', CASE WHEN jESTADO = 'RECHAZADO' THEN jRESULTADO ->> 'MENSAJE' END);
    END LOOP;

    --DEJAR CONSTANCIA DE LA SINCRONIZACION
    jID_SINCRONIZACION := funcion_Retorna_ultmoid('TAB_SINCRONIZACIONES', 'ID_SINCRONIZACION');
    INSERT INTO TAB_SINCRONIZACIONES (ID_SINCRONIZACION, ID_FINCA, ID_USUARIO, RECIBIDOS_SINCRONIZACION, GUARDADOS_SINCRONIZACION,
        OMITIDOS_SINCRONIZACION, RECHAZADOS_SINCRONIZACION, DETALLE_SINCRONIZACION)
    VALUES (jID_SINCRONIZACION, jID_FINCA, jID_USUARIO, jRECIBIDOS, jGUARDADOS, jOMITIDOS, jRECHAZADOS,
        CASE WHEN jRECHAZADOS > 0 THEN array_to_json(LISTA_RECHAZADOS) END);

    RETORNO := json_build_object('CODIGO', 200,
        'MENSAJE', jGUARDADOS || CASE WHEN jGUARDADOS = 1 THEN ' subido' ELSE ' subidos' END
            || ', ' || jOMITIDOS || CASE WHEN jOMITIDOS = 1 THEN ' ya existía' ELSE ' ya existían' END
            || ', ' || jRECHAZADOS || CASE WHEN jRECHAZADOS = 1 THEN ' rechazado' ELSE ' rechazados' END,
        'DATOS', array_to_json(LISTA_RESULTADOS));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE BAJA AL CELULAR TODO LO DE LA FINCA QUE CAMBIO DESDE SU MARCA (NUEVO, EDITADO O ANULADO) Y LA MARCA NUEVA
-- jDESDE: LA MARCA QUE GUARDO EL CELULAR (HORA DEL SERVIDOR DE SU ULTIMA BAJADA). NULL = PRIMERA VEZ: BAJA LA FINCA COMPLETA SIN LO ANULADO
-- SE PIDEN MARGEN_SINCRONIZACION_SEGUNDOS ANTES DE LA MARCA PARA NO PERDER LO QUE SE GUARDABA EN ESE MOMENTO; LO REPETIDO NO HACE DAÑO
-- PORQUE EL CELULAR ACTUALIZA POR UUID. LA MARCA NUEVA ES NOW() DEL SERVIDOR, NUNCA LA HORA DEL CELULAR
-- LOS CATALOGOS (RAZAS, VACUNAS, CICLOS DEL ICA) SON GLOBALES Y BAJAN CON LA MISMA MARCA
CREATE OR REPLACE FUNCTION FUN_OBTENER_CAMBIOS_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jDESDE TIMESTAMP WITHOUT TIME ZONE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jMARCA TIMESTAMP WITHOUT TIME ZONE;
    jDESDE_REAL TIMESTAMP WITHOUT TIME ZONE;
    jCOMPLETO BOOLEAN;
    jFINCA JSON;
    LISTA_PERSONAS JSON;
    LISTA_LOTES JSON;
    LISTA_ANIMALES JSON;
    LISTA_PESAJES JSON;
    LISTA_VACUNACIONES JSON;
    LISTA_SERVICIOS JSON;
    LISTA_PALPACIONES JSON;
    LISTA_PARTOS JSON;
    LISTA_ORDENOS JSON;
    LISTA_SALIDAS JSON;
    LISTA_POTREROS JSON;
    LISTA_OCUPACIONES JSON;
    LISTA_MOVIMIENTOS JSON;
    LISTA_RAZAS JSON;
    LISTA_VACUNAS JSON;
    LISTA_CICLOS JSON;
BEGIN
    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    ELSIF jDESDE IS NOT NULL AND jDESDE > NOW() + INTERVAL '1 minute' THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La marca de sincronización es del futuro: se bajará todo de nuevo');
        RETURN RETORNO;
    END IF;

    --MARCA NUEVA Y DESDE CUANDO SE BUSCA
    jMARCA := NOW();
    jCOMPLETO := jDESDE IS NULL;
    jDESDE_REAL := jDESDE - make_interval(secs => COALESCE(FUN_CONFIGURACION_NUMERO('MARGEN_SINCRONIZACION_SEGUNDOS'), 5));

    --LA FINCA Y SUS PERSONAS
    SELECT json_build_object('ID_FINCA', ID_FINCA, 'NOM_FINCA', NOM_FINCA, 'MUNICIPIO_FINCA', MUNICIPIO_FINCA, 'VEREDA_FINCA', VEREDA_FINCA,
        'REGISTRO_ICA_FINCA', REGISTRO_ICA_FINCA, 'HIERRO_FINCA', HIERRO_FINCA) INTO jFINCA
    FROM TAB_FINCAS WHERE ID_FINCA = jID_FINCA AND (jCOMPLETO OR FECHA_MODIFICACION > jDESDE_REAL);

    SELECT json_agg(json_build_object('ID_USUARIO', ID_USUARIO, 'NOM_PERSONA', NOM_PERSONA, 'ROL_FINCA', ROL_FINCA, 'ESTADO_FINCA_PERSONA', ESTADO_FINCA_PERSONA))
    INTO LISTA_PERSONAS
    FROM TAB_FINCAS_PERSONAS WHERE ID_FINCA = jID_FINCA AND (jCOMPLETO OR FECHA_MODIFICACION > jDESDE_REAL);

    --LOTES Y ANIMALES
    SELECT json_agg(json_build_object('ID_LOTE', ID_LOTE, 'UUID_LOTE', UUID_LOTE, 'NOM_LOTE', NOM_LOTE, 'ESTADO_LOTE', ESTADO_LOTE)) INTO LISTA_LOTES
    FROM TAB_LOTES WHERE ID_FINCA = jID_FINCA
      AND ((jCOMPLETO AND ESTADO_LOTE <> 'ANULADO') OR (NOT jCOMPLETO AND FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(FUN_DATOS_ANIMAL(ID_ANIMAL) ORDER BY ID_ANIMAL) INTO LISTA_ANIMALES
    FROM TAB_ANIMALES WHERE ID_FINCA = jID_FINCA
      AND ((jCOMPLETO AND ESTADO_ANIMAL <> 'ANULADO') OR (NOT jCOMPLETO AND FECHA_MODIFICACION > jDESDE_REAL));

    --EVENTOS (CON EL UUID DEL ANIMAL, QUE ES COMO LOS GUARDA EL CELULAR)
    SELECT json_agg(json_build_object('UUID_PESAJE', E.UUID_PESAJE, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO, 'PESO_KG', E.PESO_KG,
        'ESTIMADO_CINTA', E.ESTIMADO_CINTA, 'PERIMETRO_CM', E.PERIMETRO_CM, 'OBSERVACION_PESAJE', E.OBSERVACION_PESAJE, 'ESTADO_PESAJE', E.ESTADO_PESAJE,
        'USUARIO_CREACION', E.USUARIO_CREACION)) INTO LISTA_PESAJES
    FROM TAB_PESAJES E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_PESAJE = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_VACUNACION', E.UUID_VACUNACION, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO, 'ID_VACUNA', E.ID_VACUNA,
        'DOSIS_VACUNACION', E.DOSIS_VACUNACION, 'FECHA_PROXIMA_DOSIS', E.FECHA_PROXIMA_DOSIS, 'FECHA_FIN_RETIRO', E.FECHA_FIN_RETIRO,
        'OBSERVACION_VACUNACION', E.OBSERVACION_VACUNACION, 'ESTADO_VACUNACION', E.ESTADO_VACUNACION, 'USUARIO_CREACION', E.USUARIO_CREACION)) INTO LISTA_VACUNACIONES
    FROM TAB_VACUNACIONES E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_VACUNACION = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_SERVICIO', E.UUID_SERVICIO, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO, 'TIPO_SERVICIO', E.TIPO_SERVICIO,
        'UUID_TORO', T.UUID_ANIMAL, 'TORO_EXTERNO', E.TORO_EXTERNO, 'OBSERVACION_SERVICIO', E.OBSERVACION_SERVICIO, 'ESTADO_SERVICIO', E.ESTADO_SERVICIO,
        'USUARIO_CREACION', E.USUARIO_CREACION)) INTO LISTA_SERVICIOS
    FROM TAB_SERVICIOS E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL LEFT JOIN TAB_ANIMALES T ON T.ID_ANIMAL = E.ID_TORO
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_SERVICIO = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_PALPACION', E.UUID_PALPACION, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO,
        'RESULTADO_PALPACION', E.RESULTADO_PALPACION, 'MESES_GESTACION', E.MESES_GESTACION, 'OBSERVACION_PALPACION', E.OBSERVACION_PALPACION,
        'ESTADO_PALPACION', E.ESTADO_PALPACION, 'USUARIO_CREACION', E.USUARIO_CREACION)) INTO LISTA_PALPACIONES
    FROM TAB_PALPACIONES E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_PALPACION = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_PARTO', E.UUID_PARTO, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO, 'TIPO_PARTO', E.TIPO_PARTO,
        'CRIA_VIVA', E.CRIA_VIVA, 'SEXO_CRIA', E.SEXO_CRIA, 'UUID_CRIA', C.UUID_ANIMAL, 'OBSERVACION_PARTO', E.OBSERVACION_PARTO, 'ESTADO_PARTO', E.ESTADO_PARTO,
        'USUARIO_CREACION', E.USUARIO_CREACION)) INTO LISTA_PARTOS
    FROM TAB_PARTOS E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL LEFT JOIN TAB_ANIMALES C ON C.ID_ANIMAL = E.ID_CRIA
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_PARTO = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_ORDENO', E.UUID_ORDENO, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO, 'JORNADA_ORDENO', E.JORNADA_ORDENO,
        'LITROS_ORDENO', E.LITROS_ORDENO, 'OBSERVACION_ORDENO', E.OBSERVACION_ORDENO, 'ESTADO_ORDENO', E.ESTADO_ORDENO, 'USUARIO_CREACION', E.USUARIO_CREACION))
    INTO LISTA_ORDENOS
    FROM TAB_ORDENOS E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_ORDENO = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_SALIDA', E.UUID_SALIDA, 'UUID_ANIMAL', A.UUID_ANIMAL, 'FECHA_EVENTO', E.FECHA_EVENTO, 'TIPO_SALIDA', E.TIPO_SALIDA,
        'VALOR_SALIDA', E.VALOR_SALIDA, 'PESO_SALIDA_KG', E.PESO_SALIDA_KG, 'CAUSA_SALIDA', E.CAUSA_SALIDA, 'OBSERVACION_SALIDA', E.OBSERVACION_SALIDA,
        'ESTADO_SALIDA', E.ESTADO_SALIDA, 'USUARIO_CREACION', E.USUARIO_CREACION)) INTO LISTA_SALIDAS
    FROM TAB_SALIDAS E JOIN TAB_ANIMALES A ON A.ID_ANIMAL = E.ID_ANIMAL
    WHERE E.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND E.ESTADO_SALIDA = 'ACTIVO') OR (NOT jCOMPLETO AND E.FECHA_MODIFICACION > jDESDE_REAL));

    --POTREROS Y OCUPACIONES (FASE 5A). EL CONTORNO BAJA COMPLETO: EL MAPA LO DIBUJA SIN SEÑAL SI LOS MOSAICOS ESTAN EN CACHE
    SELECT json_agg(json_build_object('UUID_POTRERO', UUID_POTRERO, 'NOM_POTRERO', NOM_POTRERO, 'AREA_POTRERO', AREA_POTRERO,
        'DIAS_DESCANSO_POTRERO', DIAS_DESCANSO_POTRERO, 'CONTORNO_POTRERO', CONTORNO_POTRERO, 'ESTADO_POTRERO', ESTADO_POTRERO)) INTO LISTA_POTREROS
    FROM TAB_POTREROS WHERE ID_FINCA = jID_FINCA
      AND ((jCOMPLETO AND ESTADO_POTRERO <> 'ANULADO') OR (NOT jCOMPLETO AND FECHA_MODIFICACION > jDESDE_REAL));

    SELECT json_agg(json_build_object('UUID_OCUPACION', O.UUID_OCUPACION, 'UUID_POTRERO', P.UUID_POTRERO, 'UUID_LOTE', L.UUID_LOTE,
        'FECHA_EVENTO', O.FECHA_EVENTO, 'FECHA_SALIDA_OCUPACION', O.FECHA_SALIDA_OCUPACION, 'OBSERVACION_OCUPACION', O.OBSERVACION_OCUPACION,
        'ESTADO_OCUPACION', O.ESTADO_OCUPACION, 'USUARIO_CREACION', O.USUARIO_CREACION)) INTO LISTA_OCUPACIONES
    FROM TAB_OCUPACIONES O JOIN TAB_POTREROS P ON P.ID_POTRERO = O.ID_POTRERO JOIN TAB_LOTES L ON L.ID_LOTE = O.ID_LOTE
    WHERE O.ID_FINCA = jID_FINCA AND ((jCOMPLETO AND O.ESTADO_OCUPACION = 'ACTIVO') OR (NOT jCOMPLETO AND O.FECHA_MODIFICACION > jDESDE_REAL));

    --PLATA (FASE 5B): SOLO BAJA AL CELULAR DEL DUEÑO
    IF jVALIDACION -> 'DATOS' ->> 'ROL_FINCA' = 'DUENIO' THEN
        SELECT json_agg(json_build_object('UUID_MOVIMIENTO', UUID_MOVIMIENTO, 'FECHA_EVENTO', FECHA_EVENTO, 'TIPO_MOVIMIENTO', TIPO_MOVIMIENTO,
            'CATEGORIA_MOVIMIENTO', CATEGORIA_MOVIMIENTO, 'VALOR_MOVIMIENTO', VALOR_MOVIMIENTO, 'LITROS_MOVIMIENTO', LITROS_MOVIMIENTO,
            'DESCRIPCION_MOVIMIENTO', DESCRIPCION_MOVIMIENTO, 'ESTADO_MOVIMIENTO', ESTADO_MOVIMIENTO, 'USUARIO_CREACION', USUARIO_CREACION)) INTO LISTA_MOVIMIENTOS
        FROM TAB_MOVIMIENTOS WHERE ID_FINCA = jID_FINCA
          AND ((jCOMPLETO AND ESTADO_MOVIMIENTO = 'ACTIVO') OR (NOT jCOMPLETO AND FECHA_MODIFICACION > jDESDE_REAL));
    END IF;

    --CATALOGOS GLOBALES
    SELECT json_agg(json_build_object('ID_RAZA', ID_RAZA, 'NOM_RAZA', NOM_RAZA, 'ESTADO_RAZA', ESTADO_RAZA)) INTO LISTA_RAZAS
    FROM TAB_RAZAS WHERE jCOMPLETO OR FECHA_MODIFICACION > jDESDE_REAL;

    SELECT json_agg(json_build_object('ID_VACUNA', ID_VACUNA, 'NOM_VACUNA', NOM_VACUNA, 'TIPO_VACUNA', TIPO_VACUNA, 'DIAS_REFUERZO', DIAS_REFUERZO,
        'DIAS_RETIRO_LECHE', DIAS_RETIRO_LECHE, 'OBLIGATORIA_ICA', OBLIGATORIA_ICA, 'ESTADO_VACUNA', ESTADO_VACUNA)) INTO LISTA_VACUNAS
    FROM TAB_VACUNAS WHERE jCOMPLETO OR FECHA_MODIFICACION > jDESDE_REAL;

    SELECT json_agg(json_build_object('ID_CICLO', ID_CICLO, 'ID_VACUNA', ID_VACUNA, 'NOM_CICLO', NOM_CICLO, 'FECHA_INICIO_CICLO', FECHA_INICIO_CICLO,
        'FECHA_FIN_CICLO', FECHA_FIN_CICLO, 'ESTADO_CICLO', ESTADO_CICLO)) INTO LISTA_CICLOS
    FROM TAB_CICLOS_ICA WHERE (jCOMPLETO AND ESTADO_CICLO = 'ACTIVO') OR (NOT jCOMPLETO AND FECHA_MODIFICACION > jDESDE_REAL);

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', CASE WHEN jCOMPLETO THEN 'Finca completa' ELSE 'Cambios desde la última vez' END,
        'DATOS', json_build_object(
            'MARCA', jMARCA,
            'COMPLETO', jCOMPLETO,
            'ROL_FINCA', jVALIDACION -> 'DATOS' ->> 'ROL_FINCA',
            'FINCA', jFINCA,
            'PERSONAS', COALESCE(LISTA_PERSONAS, '[]'::JSON),
            'LOTES', COALESCE(LISTA_LOTES, '[]'::JSON),
            'ANIMALES', COALESCE(LISTA_ANIMALES, '[]'::JSON),
            'PESAJES', COALESCE(LISTA_PESAJES, '[]'::JSON),
            'VACUNACIONES', COALESCE(LISTA_VACUNACIONES, '[]'::JSON),
            'SERVICIOS', COALESCE(LISTA_SERVICIOS, '[]'::JSON),
            'PALPACIONES', COALESCE(LISTA_PALPACIONES, '[]'::JSON),
            'PARTOS', COALESCE(LISTA_PARTOS, '[]'::JSON),
            'ORDENOS', COALESCE(LISTA_ORDENOS, '[]'::JSON),
            'SALIDAS', COALESCE(LISTA_SALIDAS, '[]'::JSON),
            'POTREROS', COALESCE(LISTA_POTREROS, '[]'::JSON),
            'OCUPACIONES', COALESCE(LISTA_OCUPACIONES, '[]'::JSON),
            'MOVIMIENTOS', COALESCE(LISTA_MOVIMIENTOS, '[]'::JSON),
            'RAZAS', COALESCE(LISTA_RAZAS, '[]'::JSON),
            'VACUNAS', COALESCE(LISTA_VACUNAS, '[]'::JSON),
            'CICLOS_ICA', COALESCE(LISTA_CICLOS, '[]'::JSON)));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- FUNCION QUE DEVUELVE LAS ULTIMAS 20 SINCRONIZACIONES (PANTALLA "SINCRONIZACION"). EL DUEÑO VE LAS DE TODOS; LOS DEMAS, LAS SUYAS
CREATE OR REPLACE FUNCTION FUN_OBTENER_SINCRONIZACIONES_JSON(
    jID_FINCA TAB_SINCRONIZACIONES.ID_FINCA%TYPE,
    jID_USUARIO TAB_SINCRONIZACIONES.ID_USUARIO%TYPE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    LISTA_SINCRONIZACIONES JSON;
BEGIN
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    SELECT json_agg(json_build_object(
        'ID_SINCRONIZACION', T.ID_SINCRONIZACION,
        'NOM_PERSONA', T.NOM_PERSONA,
        'FECHA_SINCRONIZACION', T.FECHA_SINCRONIZACION,
        'RECIBIDOS_SINCRONIZACION', T.RECIBIDOS_SINCRONIZACION,
        'GUARDADOS_SINCRONIZACION', T.GUARDADOS_SINCRONIZACION,
        'OMITIDOS_SINCRONIZACION', T.OMITIDOS_SINCRONIZACION,
        'RECHAZADOS_SINCRONIZACION', T.RECHAZADOS_SINCRONIZACION,
        'DETALLE_SINCRONIZACION', T.DETALLE_SINCRONIZACION
    ) ORDER BY T.ID_SINCRONIZACION DESC) INTO LISTA_SINCRONIZACIONES
    FROM (
        SELECT S.*, P.NOM_PERSONA
        FROM TAB_SINCRONIZACIONES S
        LEFT JOIN TAB_FINCAS_PERSONAS P ON P.ID_FINCA = S.ID_FINCA AND P.ID_USUARIO = S.ID_USUARIO
        WHERE S.ID_FINCA = jID_FINCA
          AND (jVALIDACION -> 'DATOS' ->> 'ROL_FINCA' = 'DUENIO' OR S.ID_USUARIO = jID_USUARIO)
        ORDER BY S.ID_SINCRONIZACION DESC
        LIMIT 20
    ) T;

    IF LISTA_SINCRONIZACIONES IS NULL THEN
        RETORNO := json_build_object('CODIGO', 404, 'MENSAJE', 'Todavía no hay sincronizaciones');
    ELSE
        RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Últimas sincronizaciones', 'DATOS', LISTA_SINCRONIZACIONES);
    END IF;
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_ALERTAS/FUN_TAB_ALERTAS.SQL ═══════════
-- FUNCIONES DE LAS ALERTAS DE LA FINCA (FASE 3: PANTALLA "HOY") ----------------------------------------------------------------------------------------
-- LAS CALCULA LA BASE CON LOS EVENTOS ACTIVOS (NADA SE GUARDA: SALEN DE LA LINEA DE TIEMPO). EL CELULAR GUARDA EL RESULTADO EN CADA
-- SINCRONIZACION Y LO MUESTRA SIN SEÑAL ("ALERTAS DE LA ULTIMA VEZ QUE HUBO SEÑAL"): LA LOGICA NO SE REPITE EN TYPESCRIPT
-- LOS DIAS DE CADA AVISO ESTAN EN TAB_CONFIGURACION (DIAS_GESTACION, DIAS_AVISO_PARTO, DIAS_PALPAR_DESPUES_SERVICIO, DIAS_VACIA_ALERTA, DIAS_AVISO_VACUNA)
--
-- ALERTA                 QUE MIRA
-- PARTOS_PROXIMOS        HEMBRAS CON UN SERVICIO DESPUES DE SU ULTIMO PARTO (Y SIN PALPACION VACIA DESPUES DEL SERVICIO) O PALPADAS PREÑADAS:
--                        PARTO PROBABLE = SERVICIO + DIAS_GESTACION, O PALPACION + (9 - MESES) MESES. DESDE 30 DIAS ATRASADO HASTA DIAS_AVISO_PARTO
-- PALPAR                 SERVICIO DE HACE DIAS_PALPAR_DESPUES_SERVICIO O MAS SIN NINGUNA PALPACION DESPUES
-- VACIAS                 VACAS (CON PARTOS) CUYO ULTIMO PARTO FUE HACE MAS DE DIAS_VACIA_ALERTA Y QUE NO ESTAN SERVIDAS NI PREÑADAS DESPUES DE ESE PARTO
-- VACUNAS_POR_APLICAR    LA PROXIMA DOSIS DE LA ULTIMA APLICACION DE CADA PRODUCTO A CADA ANIMAL: DESDE 30 DIAS ATRASADA HASTA DIAS_AVISO_VACUNA
-- RETIROS_LECHE          TRATAMIENTOS CON RETIRO DE LECHE QUE SIGUE VIGENTE HOY
-- CICLOS_ICA             CICLOS DEL ICA VIGENTES O QUE EMPIEZAN EN 30 DIAS, CON CUANTOS ANIMALES ACTIVOS FALTAN POR VACUNAR EN ESE CICLO



-- FUNCION QUE DEVUELVE LAS ALERTAS DE LA FINCA PARA UN DIA (NULL = HOY). CUALQUIER ROL DE LA FINCA LAS PUEDE VER
-- SIEMPRE RESPONDE 200 CON LAS SEIS LISTAS (VACIAS SI NO HAY NADA): "SIN ALERTAS" ES UNA BUENA NOTICIA, NO UN 404
CREATE OR REPLACE FUNCTION FUN_OBTENER_ALERTAS_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jFECHA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jHOY DATE;
    jDIAS_GESTACION INTEGER;
    jDIAS_AVISO_PARTO INTEGER;
    jDIAS_PALPAR INTEGER;
    jDIAS_VACIA INTEGER;
    jDIAS_AVISO_VACUNA INTEGER;
    LISTA_PARTOS JSON;
    LISTA_PALPAR JSON;
    LISTA_VACIAS JSON;
    LISTA_VACUNAS JSON;
    LISTA_RETIROS JSON;
    LISTA_CICLOS JSON;
BEGIN
    --VALIDAR EL ACCESO (CUALQUIER ROL DE LA FINCA)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, NULL);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --DIAS DE LA CONFIGURACION (CON EL VALOR DE FABRICA SI NO ESTA)
    jHOY := COALESCE(jFECHA, CURRENT_DATE);
    jDIAS_GESTACION := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_GESTACION'), 283)::INTEGER;
    jDIAS_AVISO_PARTO := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_AVISO_PARTO'), 30)::INTEGER;
    jDIAS_PALPAR := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_PALPAR_DESPUES_SERVICIO'), 45)::INTEGER;
    jDIAS_VACIA := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_VACIA_ALERTA'), 120)::INTEGER;
    jDIAS_AVISO_VACUNA := COALESCE(FUN_CONFIGURACION_NUMERO('DIAS_AVISO_VACUNA'), 15)::INTEGER;

    --PARTOS PROXIMOS: POR EL ULTIMO SERVICIO (SIN PALPACION VACIA DESPUES) O, SI NO HAY SERVICIO, POR LA ULTIMA PALPACION PREÑADA
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'FECHA_PARTO_PROBABLE', T.FECHA_PROBABLE, 'DIAS', T.FECHA_PROBABLE - jHOY, 'SEGUN', T.SEGUN, 'PADRE', T.PADRE
    ) ORDER BY T.FECHA_PROBABLE, T.CHAPETA_ANIMAL) INTO LISTA_PARTOS
    FROM (
        SELECT A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL,
            CASE WHEN S.FECHA_EVENTO IS NOT NULL THEN S.FECHA_EVENTO::DATE + jDIAS_GESTACION
                 ELSE (P.FECHA_EVENTO + make_interval(months => 9 - P.MESES_GESTACION))::DATE END AS FECHA_PROBABLE,
            CASE WHEN S.FECHA_EVENTO IS NOT NULL THEN 'SERVICIO' ELSE 'PALPACION' END AS SEGUN,
            COALESCE(TORO.CHAPETA_ANIMAL, TORO.NOM_ANIMAL, S.TORO_EXTERNO) AS PADRE
        FROM TAB_ANIMALES A
        LEFT JOIN LATERAL (SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PARTOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') UP ON true
        LEFT JOIN LATERAL (SELECT * FROM TAB_SERVICIOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
                           AND FECHA_EVENTO > COALESCE(UP.F, '-infinity') ORDER BY FECHA_EVENTO DESC LIMIT 1) S ON true
        LEFT JOIN TAB_ANIMALES TORO ON TORO.ID_ANIMAL = S.ID_TORO
        LEFT JOIN LATERAL (SELECT * FROM TAB_PALPACIONES WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO'
                           AND FECHA_EVENTO > COALESCE(S.FECHA_EVENTO, UP.F, '-infinity') ORDER BY FECHA_EVENTO DESC LIMIT 1) P ON true
        WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO' AND A.SEXO_ANIMAL = 'H'
          AND ((S.FECHA_EVENTO IS NOT NULL AND COALESCE(P.RESULTADO_PALPACION, 'PRENIADA') = 'PRENIADA')
               OR (S.FECHA_EVENTO IS NULL AND P.RESULTADO_PALPACION = 'PRENIADA'))
    ) T
    WHERE T.FECHA_PROBABLE BETWEEN jHOY - 30 AND jHOY + jDIAS_AVISO_PARTO;

    --PALPAR: SERVIDAS HACE DIAS_PALPAR O MAS Y SIN PALPACION DESPUES DEL SERVICIO
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'FECHA_SERVICIO', T.FECHA_SERVICIO, 'DIAS_DESDE_SERVICIO', jHOY - T.FECHA_SERVICIO
    ) ORDER BY T.FECHA_SERVICIO, T.CHAPETA_ANIMAL) INTO LISTA_PALPAR
    FROM (
        SELECT A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, S.FECHA_EVENTO::DATE AS FECHA_SERVICIO
        FROM TAB_ANIMALES A
        LEFT JOIN LATERAL (SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PARTOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') UP ON true
        JOIN LATERAL (SELECT * FROM TAB_SERVICIOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
                      AND FECHA_EVENTO > COALESCE(UP.F, '-infinity') ORDER BY FECHA_EVENTO DESC LIMIT 1) S ON true
        WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO' AND A.SEXO_ANIMAL = 'H'
          AND S.FECHA_EVENTO::DATE <= jHOY - jDIAS_PALPAR
          AND NOT EXISTS (SELECT 1 FROM TAB_PALPACIONES PA WHERE PA.ID_ANIMAL = A.ID_ANIMAL AND PA.ESTADO_PALPACION = 'ACTIVO' AND PA.FECHA_EVENTO > S.FECHA_EVENTO)
    ) T;

    --VACIAS: VACAS CON EL ULTIMO PARTO HACE MAS DE DIAS_VACIA, SIN SERVICIO DESPUES (O CON LA ULTIMA PALPACION VACIA Y SIN SERVICIO DESPUES DE ELLA)
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'FECHA_ULTIMO_PARTO', T.ULTIMO_PARTO, 'DIAS_VACIA', jHOY - T.ULTIMO_PARTO
    ) ORDER BY T.ULTIMO_PARTO, T.CHAPETA_ANIMAL) INTO LISTA_VACIAS
    FROM (
        SELECT A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, UP.F::DATE AS ULTIMO_PARTO
        FROM TAB_ANIMALES A
        JOIN LATERAL (SELECT MAX(FECHA_EVENTO) AS F FROM TAB_PARTOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PARTO = 'ACTIVO') UP ON UP.F IS NOT NULL
        LEFT JOIN LATERAL (SELECT * FROM TAB_SERVICIOS WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_SERVICIO = 'ACTIVO'
                           AND FECHA_EVENTO > UP.F ORDER BY FECHA_EVENTO DESC LIMIT 1) S ON true
        LEFT JOIN LATERAL (SELECT * FROM TAB_PALPACIONES WHERE ID_ANIMAL = A.ID_ANIMAL AND ESTADO_PALPACION = 'ACTIVO'
                           AND FECHA_EVENTO > UP.F ORDER BY FECHA_EVENTO DESC LIMIT 1) P ON true
        WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO' AND A.SEXO_ANIMAL = 'H'
          AND UP.F::DATE < jHOY - jDIAS_VACIA
          AND COALESCE(P.RESULTADO_PALPACION, '') <> 'PRENIADA'
          AND (S.FECHA_EVENTO IS NULL OR (P.RESULTADO_PALPACION = 'VACIA' AND P.FECHA_EVENTO > S.FECHA_EVENTO))
    ) T;

    --VACUNAS POR APLICAR: LA ULTIMA APLICACION DE CADA PRODUCTO A CADA ANIMAL, CON SU PROXIMA DOSIS DENTRO DEL AVISO (O ATRASADA HASTA 30 DIAS)
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'ID_VACUNA', T.ID_VACUNA, 'NOM_VACUNA', T.NOM_VACUNA, 'FECHA_PROXIMA_DOSIS', T.FECHA_PROXIMA_DOSIS, 'DIAS', T.FECHA_PROXIMA_DOSIS - jHOY
    ) ORDER BY T.FECHA_PROXIMA_DOSIS, T.NOM_VACUNA, T.CHAPETA_ANIMAL) INTO LISTA_VACUNAS
    FROM (
        SELECT DISTINCT ON (VC.ID_ANIMAL, VC.ID_VACUNA) A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, V.ID_VACUNA, V.NOM_VACUNA, VC.FECHA_PROXIMA_DOSIS
        FROM TAB_VACUNACIONES VC
        JOIN TAB_ANIMALES A ON A.ID_ANIMAL = VC.ID_ANIMAL
        JOIN TAB_VACUNAS V ON V.ID_VACUNA = VC.ID_VACUNA
        WHERE VC.ID_FINCA = jID_FINCA AND VC.ESTADO_VACUNACION = 'ACTIVO' AND A.ESTADO_ANIMAL = 'ACTIVO'
        ORDER BY VC.ID_ANIMAL, VC.ID_VACUNA, VC.FECHA_EVENTO DESC
    ) T
    WHERE T.FECHA_PROXIMA_DOSIS BETWEEN jHOY - 30 AND jHOY + jDIAS_AVISO_VACUNA;

    --RETIROS DE LECHE VIGENTES: NO VENDER LA LECHE DE ESTOS ANIMALES HASTA LA FECHA
    SELECT json_agg(json_build_object(
        'UUID_ANIMAL', T.UUID_ANIMAL, 'CHAPETA_ANIMAL', T.CHAPETA_ANIMAL, 'NOM_ANIMAL', T.NOM_ANIMAL,
        'NOM_VACUNA', T.NOM_VACUNA, 'FECHA_FIN_RETIRO', T.FECHA_FIN_RETIRO, 'DIAS_RESTANTES', T.FECHA_FIN_RETIRO - jHOY
    ) ORDER BY T.FECHA_FIN_RETIRO DESC, T.CHAPETA_ANIMAL) INTO LISTA_RETIROS
    FROM (
        SELECT DISTINCT ON (VC.ID_ANIMAL) A.UUID_ANIMAL, A.CHAPETA_ANIMAL, A.NOM_ANIMAL, V.NOM_VACUNA, VC.FECHA_FIN_RETIRO
        FROM TAB_VACUNACIONES VC
        JOIN TAB_ANIMALES A ON A.ID_ANIMAL = VC.ID_ANIMAL
        JOIN TAB_VACUNAS V ON V.ID_VACUNA = VC.ID_VACUNA
        WHERE VC.ID_FINCA = jID_FINCA AND VC.ESTADO_VACUNACION = 'ACTIVO' AND A.ESTADO_ANIMAL = 'ACTIVO'
          AND VC.FECHA_FIN_RETIRO >= jHOY AND VC.FECHA_EVENTO::DATE <= jHOY
        ORDER BY VC.ID_ANIMAL, VC.FECHA_FIN_RETIRO DESC
    ) T;

    --CICLOS DEL ICA VIGENTES O QUE EMPIEZAN EN 30 DIAS, CON LOS ANIMALES ACTIVOS QUE AUN NO TIENEN ESA VACUNA EN EL CICLO
    SELECT json_agg(json_build_object(
        'ID_CICLO', C.ID_CICLO, 'NOM_CICLO', C.NOM_CICLO, 'NOM_VACUNA', V.NOM_VACUNA,
        'FECHA_INICIO_CICLO', C.FECHA_INICIO_CICLO, 'FECHA_FIN_CICLO', C.FECHA_FIN_CICLO,
        'VIGENTE', jHOY BETWEEN C.FECHA_INICIO_CICLO AND C.FECHA_FIN_CICLO,
        'DIAS_PARA_EMPEZAR', GREATEST(C.FECHA_INICIO_CICLO - jHOY, 0), 'DIAS_PARA_TERMINAR', C.FECHA_FIN_CICLO - jHOY,
        'FALTAN', (SELECT COUNT(*) FROM TAB_ANIMALES A
                   WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL = 'ACTIVO'
                     AND NOT EXISTS (SELECT 1 FROM TAB_VACUNACIONES VC WHERE VC.ID_ANIMAL = A.ID_ANIMAL AND VC.ID_VACUNA = C.ID_VACUNA
                                     AND VC.ESTADO_VACUNACION = 'ACTIVO' AND VC.FECHA_EVENTO::DATE BETWEEN C.FECHA_INICIO_CICLO AND C.FECHA_FIN_CICLO))
    ) ORDER BY C.FECHA_INICIO_CICLO) INTO LISTA_CICLOS
    FROM TAB_CICLOS_ICA C
    JOIN TAB_VACUNAS V ON V.ID_VACUNA = C.ID_VACUNA
    WHERE C.ESTADO_CICLO = 'ACTIVO' AND C.FECHA_FIN_CICLO >= jHOY AND C.FECHA_INICIO_CICLO <= jHOY + 30;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Alertas de la finca',
        'DATOS', json_build_object(
            'FECHA', jHOY,
            'PARTOS_PROXIMOS', COALESCE(LISTA_PARTOS, '[]'::JSON),
            'PALPAR', COALESCE(LISTA_PALPAR, '[]'::JSON),
            'VACIAS', COALESCE(LISTA_VACIAS, '[]'::JSON),
            'VACUNAS_POR_APLICAR', COALESCE(LISTA_VACUNAS, '[]'::JSON),
            'RETIROS_LECHE', COALESCE(LISTA_RETIROS, '[]'::JSON),
            'CICLOS_ICA', COALESCE(LISTA_CICLOS, '[]'::JSON),
            'DIAS_VACIA_ALERTA', jDIAS_VACIA,
            'DIAS_AVISO_PARTO', jDIAS_AVISO_PARTO));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_INDICADORES/FUN_TAB_INDICADORES.SQL ═══════════
-- FUNCIONES DE LOS INDICADORES DE LA FINCA (FASE 4, MENU 6 INDICADORES Y EXCEL) ---------------------------------------------------------------------
-- LOS CALCULA LA BASE CON LOS EVENTOS ACTIVOS DE UN PERIODO (DESDE / HASTA). NADA SE GUARDA. EL CELULAR GUARDA LA ULTIMA RESPUESTA PARA VERLA SIN SEÑAL
-- SOLO EL DUEÑO Y EL VETERINARIO (EL VAQUERO NO TIENE EL MENU 6)
--
-- QUIEN CUENTA EN EL PERIODO: UN ANIMAL "ESTUVO EN LA FINCA" SI LLEGO (FECHA_INGRESO_ANIMAL) ANTES DEL FIN DEL PERIODO Y NO HABIA SALIDO
-- (FECHA_SALIDA_ANIMAL) ANTES DEL INICIO. LOS ANULADOS NUNCA CUENTAN
--
-- INDICADOR                COMO SE CALCULA
-- NATALIDAD (%)            CRIAS NACIDAS VIVAS EN EL PERIODO / HEMBRAS REPRODUCTORAS QUE ESTUVIERON (24 MESES O MAS AL FINAL DEL PERIODO, O CON PARTOS) × 100
-- MORTALIDAD (%)           MUERTES EN EL PERIODO / ANIMALES QUE ESTUVIERON × 100
-- INTERVALO ENTRE PARTOS   PROMEDIO DE DIAS ENTRE DOS PARTOS SEGUIDOS DE LA MISMA VACA, CUANDO EL SEGUNDO CAE EN EL PERIODO
-- LITROS POR VACA AL DIA   PROMEDIO, ENTRE LOS DIAS CON ORDEÑO, DE (LITROS DEL DIA / VACAS ORDEÑADAS ESE DIA)
-- GANANCIA DIARIA DE PESO  POR ANIMAL CON DOS O MAS PESAJES EN EL PERIODO SEPARADOS AL MENOS 14 DIAS: (ULTIMO - PRIMERO) / DIAS, EN GRAMOS;
--                          PROMEDIO POR LOTE (EL LOTE DE HOY DEL ANIMAL)



-- FUNCION QUE DEVUELVE LOS INDICADORES DE UNA FINCA EN UN PERIODO. DESDE Y HASTA NULL = LOS ULTIMOS 12 MESES HASTA HOY. MAXIMO 3 AÑOS
CREATE OR REPLACE FUNCTION FUN_OBTENER_INDICADORES_JSON(
    jID_FINCA TAB_FINCAS.ID_FINCA%TYPE,
    jID_USUARIO TAB_FINCAS_PERSONAS.ID_USUARIO%TYPE,
    jDESDE DATE,
    jHASTA DATE
) RETURNS JSON AS
$$
DECLARE
    RETORNO JSON;
    jVALIDACION JSON;
    jFIN DATE;
    jINICIO DATE;
    jPRESENTES INTEGER;
    jHEMBRAS INTEGER;
    jCRIAS_VIVAS INTEGER;
    jMUERTES INTEGER;
    jINTERVALO NUMERIC;
    jINTERVALOS INTEGER;
    jLITROS NUMERIC;
    jDIAS_ORDENO INTEGER;
    jLITROS_VACA_DIA NUMERIC;
    jVENTAS INTEGER;
    jVALOR_VENTAS NUMERIC;
    jGDP_GENERAL NUMERIC;
    jGDP_ANIMALES INTEGER;
    LISTA_CATEGORIAS JSON;
    LISTA_LECHE_MES JSON;
    LISTA_PARTOS_MES JSON;
    LISTA_GDP_LOTE JSON;
BEGIN
    --VALIDAR EL ACCESO (DUEÑO Y VETERINARIO)
    jVALIDACION := FUN_VALIDAR_ACCESO_FINCA(jID_FINCA, jID_USUARIO, ARRAY['DUENIO', 'VETERINARIO']);
    IF (jVALIDACION ->> 'CODIGO')::INTEGER != 200 THEN
        RETURN jVALIDACION;
    END IF;

    --EL PERIODO
    jFIN := COALESCE(jHASTA, CURRENT_DATE);
    jINICIO := COALESCE(jDESDE, (jFIN - INTERVAL '12 months')::DATE + 1);
    IF jINICIO > jFIN THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'La fecha inicial debe ser antes de la final');
        RETURN RETORNO;
    ELSIF jFIN - jINICIO > 1100 THEN
        RETORNO := json_build_object('CODIGO', 400, 'MENSAJE', 'El periodo puede ser de máximo 3 años');
        RETURN RETORNO;
    END IF;

    --ANIMALES QUE ESTUVIERON EN LA FINCA EN EL PERIODO
    SELECT COUNT(*) INTO jPRESENTES
    FROM TAB_ANIMALES A
    WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL <> 'ANULADO'
      AND A.FECHA_INGRESO_ANIMAL <= jFIN AND COALESCE(A.FECHA_SALIDA_ANIMAL::DATE, 'infinity') >= jINICIO;

    --HEMBRAS REPRODUCTORAS QUE ESTUVIERON (24 MESES O MAS AL FINAL DEL PERIODO, O CON ALGUN PARTO)
    SELECT COUNT(*) INTO jHEMBRAS
    FROM TAB_ANIMALES A
    WHERE A.ID_FINCA = jID_FINCA AND A.ESTADO_ANIMAL <> 'ANULADO' AND A.SEXO_ANIMAL = 'H'
      AND A.FECHA_INGRESO_ANIMAL <= jFIN AND COALESCE(A.FECHA_SALIDA_ANIMAL::DATE, 'infinity') >= jINICIO
      AND (A.FECHA_NACIMIENTO <= (jFIN - INTERVAL '24 months')::DATE
           OR EXISTS (SELECT 1 FROM TAB_PARTOS P WHERE P.ID_ANIMAL = A.ID_ANIMAL AND P.ESTADO_PARTO = 'ACTIVO' AND P.FECHA_EVENTO::DATE <= jFIN));

    --CRIAS VIVAS Y MUERTES EN EL PERIODO
    SELECT COUNT(*) INTO jCRIAS_VIVAS FROM TAB_PARTOS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_PARTO = 'ACTIVO' AND CRIA_VIVA = 'SI' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;
    SELECT COUNT(*) INTO jMUERTES FROM TAB_SALIDAS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_SALIDA = 'ACTIVO' AND TIPO_SALIDA = 'MUERTE' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;

    --INTERVALO ENTRE PARTOS: CADA PARTO DEL PERIODO CONTRA EL PARTO ANTERIOR DE LA MISMA VACA
    SELECT AVG(T.DIAS), COUNT(*) INTO jINTERVALO, jINTERVALOS
    FROM (
        SELECT P.FECHA_EVENTO::DATE - (SELECT MAX(Q.FECHA_EVENTO)::DATE FROM TAB_PARTOS Q
                                       WHERE Q.ID_ANIMAL = P.ID_ANIMAL AND Q.ESTADO_PARTO = 'ACTIVO' AND Q.FECHA_EVENTO < P.FECHA_EVENTO) AS DIAS
        FROM TAB_PARTOS P
        WHERE P.ID_FINCA = jID_FINCA AND P.ESTADO_PARTO = 'ACTIVO' AND P.FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
    ) T
    WHERE T.DIAS IS NOT NULL;

    --LECHE: TOTAL, DIAS CON ORDEÑO Y LITROS POR VACA AL DIA
    SELECT SUM(T.LITROS), COUNT(*), AVG(T.LITROS / T.VACAS) INTO jLITROS, jDIAS_ORDENO, jLITROS_VACA_DIA
    FROM (
        SELECT FECHA_EVENTO::DATE AS DIA, SUM(LITROS_ORDENO) AS LITROS, COUNT(DISTINCT ID_ANIMAL) AS VACAS
        FROM TAB_ORDENOS
        WHERE ID_FINCA = jID_FINCA AND ESTADO_ORDENO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
        GROUP BY FECHA_EVENTO::DATE
    ) T;

    --LECHE POR MES (PARA LA GRAFICA)
    SELECT json_agg(json_build_object('MES', T.MES, 'LITROS', T.LITROS, 'LITROS_VACA_DIA', round(T.LVD, 1)) ORDER BY T.MES) INTO LISTA_LECHE_MES
    FROM (
        SELECT to_char(D.DIA, 'YYYY-MM') AS MES, SUM(D.LITROS) AS LITROS, AVG(D.LITROS / D.VACAS) AS LVD
        FROM (
            SELECT FECHA_EVENTO::DATE AS DIA, SUM(LITROS_ORDENO) AS LITROS, COUNT(DISTINCT ID_ANIMAL) AS VACAS
            FROM TAB_ORDENOS
            WHERE ID_FINCA = jID_FINCA AND ESTADO_ORDENO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
            GROUP BY FECHA_EVENTO::DATE
        ) D
        GROUP BY to_char(D.DIA, 'YYYY-MM')
    ) T;

    --PARTOS POR MES (PARA LA GRAFICA)
    SELECT json_agg(json_build_object('MES', T.MES, 'PARTOS', T.PARTOS, 'CRIAS_VIVAS', T.VIVAS) ORDER BY T.MES) INTO LISTA_PARTOS_MES
    FROM (
        SELECT to_char(FECHA_EVENTO, 'YYYY-MM') AS MES, COUNT(*) AS PARTOS, COUNT(*) FILTER (WHERE CRIA_VIVA = 'SI') AS VIVAS
        FROM TAB_PARTOS
        WHERE ID_FINCA = jID_FINCA AND ESTADO_PARTO = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
        GROUP BY to_char(FECHA_EVENTO, 'YYYY-MM')
    ) T;

    --GANANCIA DIARIA DE PESO: POR ANIMAL (PRIMER Y ULTIMO PESAJE DEL PERIODO, AL MENOS 14 DIAS ENTRE ELLOS) Y PROMEDIO POR LOTE
    SELECT json_agg(json_build_object('NOM_LOTE', T.NOM_LOTE, 'ANIMALES', T.ANIMALES, 'GRAMOS_DIA', round(T.GRAMOS)) ORDER BY T.NOM_LOTE) INTO LISTA_GDP_LOTE
    FROM (
        SELECT COALESCE(L.NOM_LOTE, 'Sin lote') AS NOM_LOTE, COUNT(*) AS ANIMALES, AVG(G.GRAMOS) AS GRAMOS
        FROM (
            SELECT P1.ID_ANIMAL, (P2.PESO_KG - P1.PESO_KG) * 1000 / (P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE) AS GRAMOS
            FROM (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
                  WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
                  ORDER BY ID_ANIMAL, FECHA_EVENTO ASC) P1
            JOIN (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
                  WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
                  ORDER BY ID_ANIMAL, FECHA_EVENTO DESC) P2 ON P2.ID_ANIMAL = P1.ID_ANIMAL
            WHERE P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE >= 14
        ) G
        JOIN TAB_ANIMALES A ON A.ID_ANIMAL = G.ID_ANIMAL
        LEFT JOIN TAB_LOTES L ON L.ID_LOTE = A.ID_LOTE
        GROUP BY COALESCE(L.NOM_LOTE, 'Sin lote')
    ) T;

    SELECT AVG(G.GRAMOS), COUNT(*) INTO jGDP_GENERAL, jGDP_ANIMALES
    FROM (
        SELECT (P2.PESO_KG - P1.PESO_KG) * 1000 / (P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE) AS GRAMOS
        FROM (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
              WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
              ORDER BY ID_ANIMAL, FECHA_EVENTO ASC) P1
        JOIN (SELECT DISTINCT ON (ID_ANIMAL) ID_ANIMAL, PESO_KG, FECHA_EVENTO FROM TAB_PESAJES
              WHERE ID_FINCA = jID_FINCA AND ESTADO_PESAJE = 'ACTIVO' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN
              ORDER BY ID_ANIMAL, FECHA_EVENTO DESC) P2 ON P2.ID_ANIMAL = P1.ID_ANIMAL
        WHERE P2.FECHA_EVENTO::DATE - P1.FECHA_EVENTO::DATE >= 14
    ) G;

    --VENTAS DEL PERIODO
    SELECT COUNT(*), COALESCE(SUM(VALOR_SALIDA), 0) INTO jVENTAS, jVALOR_VENTAS FROM TAB_SALIDAS
    WHERE ID_FINCA = jID_FINCA AND ESTADO_SALIDA = 'ACTIVO' AND TIPO_SALIDA = 'VENTA' AND FECHA_EVENTO::DATE BETWEEN jINICIO AND jFIN;

    --EL HATO DE HOY POR CATEGORIA
    SELECT json_agg(json_build_object('CATEGORIA', T.CATEGORIA, 'CANTIDAD', T.CANTIDAD) ORDER BY T.ORDEN) INTO LISTA_CATEGORIAS
    FROM (
        SELECT FUN_CATEGORIA_ANIMAL(ID_ANIMAL) AS CATEGORIA, COUNT(*) AS CANTIDAD,
            array_position(ARRAY['VACA', 'NOVILLA', 'TERNERA', 'TORO', 'NOVILLO', 'TERNERO']::VARCHAR[], FUN_CATEGORIA_ANIMAL(ID_ANIMAL)) AS ORDEN
        FROM TAB_ANIMALES
        WHERE ID_FINCA = jID_FINCA AND ESTADO_ANIMAL = 'ACTIVO'
        GROUP BY FUN_CATEGORIA_ANIMAL(ID_ANIMAL)
    ) T;

    RETORNO := json_build_object('CODIGO', 200, 'MENSAJE', 'Indicadores de la finca',
        'DATOS', json_build_object(
            'DESDE', jINICIO,
            'HASTA', jFIN,
            'ANIMALES_EN_EL_PERIODO', jPRESENTES,
            'HATO_POR_CATEGORIA', COALESCE(LISTA_CATEGORIAS, '[]'::JSON),
            'NATALIDAD', json_build_object('CRIAS_VIVAS', jCRIAS_VIVAS, 'HEMBRAS', jHEMBRAS,
                'PORCENTAJE', CASE WHEN jHEMBRAS > 0 THEN round(jCRIAS_VIVAS * 100.0 / jHEMBRAS, 1) END),
            'MORTALIDAD', json_build_object('MUERTES', jMUERTES, 'ANIMALES', jPRESENTES,
                'PORCENTAJE', CASE WHEN jPRESENTES > 0 THEN round(jMUERTES * 100.0 / jPRESENTES, 1) END),
            'INTERVALO_PARTOS', json_build_object('PROMEDIO_DIAS', round(jINTERVALO), 'INTERVALOS', COALESCE(jINTERVALOS, 0)),
            'LECHE', json_build_object('LITROS_TOTALES', COALESCE(jLITROS, 0), 'DIAS_CON_ORDENO', COALESCE(jDIAS_ORDENO, 0),
                'LITROS_VACA_DIA', round(jLITROS_VACA_DIA, 1), 'POR_MES', COALESCE(LISTA_LECHE_MES, '[]'::JSON)),
            'PARTOS_POR_MES', COALESCE(LISTA_PARTOS_MES, '[]'::JSON),
            'GANANCIA_PESO', json_build_object('GRAMOS_DIA', round(jGDP_GENERAL), 'ANIMALES', COALESCE(jGDP_ANIMALES, 0),
                'POR_LOTE', COALESCE(LISTA_GDP_LOTE, '[]'::JSON)),
            'VENTAS', json_build_object('CANTIDAD', jVENTAS, 'VALOR_TOTAL', jVALOR_VENTAS)));
    RETURN RETORNO;
END;
$$ LANGUAGE plpgsql;



-- ═══════════ FUNCIONES/FUN_AUDITORIA/FUN_TAB_AUDITORIA.SQL ═══════════
-- TRIGGERS DE GANADERO Y CONSULTAS DE LA AUDITORIA --------------------------------------------------------------------------------------------------
-- LA LOGICA DE NEGOCIO SIGUE EN LAS FUNCIONES FUN_*_JSON. LOS TRIGGERS SOLO HACEN LO QUE DEBE CUMPLIRSE SIEMPRE, VENGA EL CAMBIO DE DONDE VENGA
-- (UNA FUNCION, LA SINCRONIZACION O UN UPDATE A MANO EN psql):
--
--   TRIGGER                 CUANDO                          QUE HACE
--   TRG_PROTEGER_<TABLA>    BEFORE INSERT / UPDATE          PONE FECHA_MODIFICACION = NOW() (LA MARCA CON LA QUE EL CELULAR BAJA LOS CAMBIOS)
--                                                           E IMPIDE CAMBIAR UUID, FINCA, FECHA_CREACION Y USUARIO_CREACION
--   TRG_NO_BORRAR_<TABLA>   BEFORE DELETE                   IMPIDE EL DELETE: AQUI SE ANULA (SALVO LIMPIEZAS CON ganadero.permitir_borrar = 'SI')
--   TRG_AUDITORIA_<TABLA>   AFTER INSERT / UPDATE / DELETE  GUARDA EN TAB_AUDITORIAS QUIEN CAMBIO QUE Y CUANDO (SOLO LAS COLUMNAS QUE CAMBIARON)
--   TRG_PESO_ACTUAL         AFTER INSERT / UPDATE PESAJE    DEJA EN EL ANIMAL EL PESO DEL ULTIMO PESAJE ACTIVO (TAMBIEN AL ANULAR UNO)
--   TRG_SALIDA_ANIMAL       AFTER INSERT / UPDATE SALIDA    VENTA / MUERTE / TRASLADO CAMBIA EL ESTADO DEL ANIMAL; ANULAR LA SALIDA LO DEVUELVE A ACTIVO



-- FUNCION DEL TRIGGER QUE PROTEGE LOS REGISTROS SINCRONIZABLES
-- TG_ARGV[0]: COLUMNA UUID EN MINUSCULAS ('' SI LA TABLA NO TIENE)
-- FECHA_MODIFICACION TAMBIEN SE PONE AL CREAR: ASI "LO QUE CAMBIO DESDE LA MARCA" INCLUYE LO NUEVO SIN COALESCE
CREATE OR REPLACE FUNCTION FUN_TRG_PROTEGER_REGISTRO() RETURNS TRIGGER AS
$$
DECLARE
    jNUEVO JSONB;
    jVIEJO JSONB;
    jCOLUMNA VARCHAR;
BEGIN
    NEW.FECHA_MODIFICACION := NOW();
    IF TG_OP = 'INSERT' THEN
        RETURN NEW;
    END IF;

    --COLUMNAS QUE NO SE PUEDEN CAMBIAR NUNCA
    jNUEVO := to_jsonb(NEW);
    jVIEJO := to_jsonb(OLD);
    FOREACH jCOLUMNA IN ARRAY ARRAY[NULLIF(TG_ARGV[0], ''), 'id_finca', 'fecha_creacion', 'usuario_creacion'] LOOP
        IF jCOLUMNA IS NOT NULL AND jNUEVO ? jCOLUMNA AND (jNUEVO -> jCOLUMNA) IS DISTINCT FROM (jVIEJO -> jCOLUMNA) THEN
            RAISE EXCEPTION 'En % no se puede cambiar la columna %', upper(TG_TABLE_NAME), upper(jCOLUMNA);
        END IF;
    END LOOP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;



-- FUNCION DEL TRIGGER QUE IMPIDE BORRAR: EN GANADERO SE ANULA (ESTADO = 'ANULADO') PARA QUE LA ANULACION LLEGUE A TODOS LOS CELULARES
-- PARA LIMPIAR DATOS DE PRUEBA O DE LA DEMO, DENTRO DE LA TRANSACCION: SET LOCAL ganadero.permitir_borrar = 'SI';
CREATE OR REPLACE FUNCTION FUN_TRG_NO_BORRAR() RETURNS TRIGGER AS
$$
BEGIN
    IF COALESCE(current_setting('ganadero.permitir_borrar', true), '') = 'SI' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'En % no se borra: se anula (ESTADO = ANULADO)', upper(TG_TABLE_NAME);
END;
$$ LANGUAGE plpgsql;



-- FUNCION DEL TRIGGER DE AUDITORIA
-- TG_ARGV[0]: COLUMNA ID, TG_ARGV[1]: COLUMNA UUID ('' SI NO TIENE), TG_ARGV[2]: COLUMNA ESTADO ('' SI NO TIENE). TODAS EN MINUSCULAS
-- EN UN UPDATE SOLO GUARDA LAS COLUMNAS QUE CAMBIARON; SI SOLO CAMBIO FECHA_MODIFICACION O USUARIO_MODIFICACION NO GUARDA NADA
CREATE OR REPLACE FUNCTION FUN_TRG_AUDITORIA() RETURNS TRIGGER AS
$$
DECLARE
    jNUEVO JSONB;
    jVIEJO JSONB;
    jFILA JSONB;
    jCAMBIOS JSONB;
    jOPERACION VARCHAR;
    jUSUARIO VARCHAR;
    jUUID_TEXTO VARCHAR;
BEGIN
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        jNUEVO := to_jsonb(NEW);
    END IF;
    IF TG_OP IN ('UPDATE', 'DELETE') THEN
        jVIEJO := to_jsonb(OLD);
    END IF;
    jFILA := COALESCE(jNUEVO, jVIEJO);

    --QUE OPERACION FUE Y QUIEN LA HIZO
    IF TG_OP = 'INSERT' THEN
        jOPERACION := 'CREAR';
        jUSUARIO := jNUEVO ->> 'usuario_creacion';
    ELSIF TG_OP = 'UPDATE' THEN
        --COLUMNAS QUE CAMBIARON (SIN CONTAR LA MARCA DE MODIFICACION)
        SELECT jsonb_object_agg(N.key, jsonb_build_object('ANTES', V.value, 'DESPUES', N.value)) INTO jCAMBIOS
        FROM jsonb_each(jNUEVO) N
        JOIN jsonb_each(jVIEJO) V ON V.key = N.key
        WHERE N.value IS DISTINCT FROM V.value
          AND N.key NOT IN ('fecha_modificacion', 'usuario_modificacion');
        IF jCAMBIOS IS NULL THEN
            RETURN NULL;
        END IF;
        jOPERACION := CASE WHEN TG_ARGV[2] <> '' AND jNUEVO ->> TG_ARGV[2] = 'ANULADO' AND jVIEJO ->> TG_ARGV[2] <> 'ANULADO' THEN 'ANULAR' ELSE 'EDITAR' END;
        jUSUARIO := COALESCE(jNUEVO ->> 'usuario_modificacion', jNUEVO ->> 'usuario_creacion');
    ELSE
        jOPERACION := 'BORRAR';
        jUSUARIO := current_user;
    END IF;

    jUUID_TEXTO := CASE WHEN TG_ARGV[1] <> '' THEN jFILA ->> TG_ARGV[1] END;

    --GUARDAR EL REGISTRO DE AUDITORIA
    INSERT INTO TAB_AUDITORIAS (NOM_TABLA_AUDITORIA, OPERACION_AUDITORIA, ID_REGISTRO_AUDITORIA, UUID_REGISTRO_AUDITORIA, ID_FINCA,
        CAMBIOS_AUDITORIA, DATOS_AUDITORIA, USUARIO_AUDITORIA)
    VALUES (upper(TG_TABLE_NAME), jOPERACION, (jFILA ->> TG_ARGV[0])::INTEGER, jUUID_TEXTO::UUID, (jFILA ->> 'id_finca')::INTEGER,
        jCAMBIOS, CASE WHEN TG_OP = 'UPDATE' THEN NULL ELSE jFILA END, jUSUARIO);
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;



-- FUNCION DEL TRIGGER QUE DEJA EN EL ANIMAL EL PESO DE SU ULTIMO PESAJE ACTIVO
-- SE RECALCULA DESDE LOS PESAJES (NO SE COPIA EL NUEVO): ASI FUNCIONA IGUAL SI LLEGA TARDE UN PESAJE VIEJO O SI SE ANULA EL ULTIMO
CREATE OR REPLACE FUNCTION FUN_TRG_PESO_ACTUAL() RETURNS TRIGGER AS
$$
DECLARE
    jPESO NUMERIC;
    jFECHA TIMESTAMP;
BEGIN
    SELECT PESO_KG, FECHA_EVENTO INTO jPESO, jFECHA
    FROM TAB_PESAJES
    WHERE ID_ANIMAL = NEW.ID_ANIMAL AND ESTADO_PESAJE = 'ACTIVO'
    ORDER BY FECHA_EVENTO DESC, ID_PESAJE DESC
    LIMIT 1;

    UPDATE TAB_ANIMALES
    SET PESO_ACTUAL_KG = jPESO,
        FECHA_ULTIMO_PESAJE = jFECHA,
        USUARIO_MODIFICACION = COALESCE(NEW.USUARIO_MODIFICACION, NEW.USUARIO_CREACION)
    WHERE ID_ANIMAL = NEW.ID_ANIMAL
      AND (PESO_ACTUAL_KG IS DISTINCT FROM jPESO OR FECHA_ULTIMO_PESAJE IS DISTINCT FROM jFECHA);
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;



-- FUNCION DEL TRIGGER QUE CAMBIA EL ESTADO DEL ANIMAL CON SU SALIDA
-- SALIDA ACTIVA: VENTA -> VENDIDO, MUERTE -> MUERTO, TRASLADO -> TRASLADADO. SALIDA ANULADA: VUELVE A ACTIVO
CREATE OR REPLACE FUNCTION FUN_TRG_SALIDA_ANIMAL() RETURNS TRIGGER AS
$$
BEGIN
    IF NEW.ESTADO_SALIDA = 'ACTIVO' THEN
        UPDATE TAB_ANIMALES
        SET ESTADO_ANIMAL = CASE NEW.TIPO_SALIDA WHEN 'VENTA' THEN 'VENDIDO' WHEN 'MUERTE' THEN 'MUERTO' ELSE 'TRASLADADO' END,
            FECHA_SALIDA_ANIMAL = NEW.FECHA_EVENTO,
            USUARIO_MODIFICACION = COALESCE(NEW.USUARIO_MODIFICACION, NEW.USUARIO_CREACION)
        WHERE ID_ANIMAL = NEW.ID_ANIMAL;
    ELSIF TG_OP = 'UPDATE' AND OLD.ESTADO_SALIDA = 'ACTIVO' THEN
        UPDATE TAB_ANIMALES
        SET ESTADO_ANIMAL = 'ACTIVO',
            FECHA_SALIDA_ANIMAL = NULL,
            USUARIO_MODIFICACION = COALESCE(NEW.USUARIO_MODIFICACION, NEW.USUARIO_CREACION)
        WHERE ID_ANIMAL = NEW.ID_ANIMAL AND ESTADO_ANIMAL IN ('VENDIDO', 'MUERTO', 'TRASLADADO');
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;



-- CREACION DE LOS TRIGGERS ---------------------------------------------------------------------------------------------------------------------------

-- PROTEGER (FECHA_MODIFICACION E INMUTABLES)
CREATE OR REPLACE TRIGGER TRG_PROTEGER_FINCAS BEFORE INSERT OR UPDATE ON TAB_FINCAS FOR EACH ROW EXECUTE FUNCTION FUN_TRG_PROTEGER_REGISTRO('');
CREATE OR REPLACE TRIGGER TRG_PROTEGER_FINCAS_PERSONAS BEFORE INSERT OR UPDATE ON TAB_FINCAS_PERSONAS FOR EACH ROW EXECUTE FUNCTION FUN_TRG_PROTEGER_REGISTRO('');
CREATE OR REPLACE TRIGGER TRG_PROTEGER_CONFIGURACION BEFORE INSERT OR UPDATE ON TAB_CONFIGURACION FOR EACH ROW EXECUTE FUNCTION FUN_TRG_PROTEGER_REGISTRO('');
CREATE OR REPLACE TRIGGER TRG_PROTEGER_RAZAS BEFORE INSERT OR UPDATE ON TAB_RAZAS FOR EACH ROW EXECUTE FUNCTION FUN_TRG_PROTEGER_REGISTRO('');
CREATE OR REPLACE TRIGGER TRG_PROTEGER_VACUNAS BEFORE INSERT OR UPDATE ON TAB_VACUNAS FOR EACH ROW EXECUTE FUNCTION FUN_TRG_PROTEGER_REGISTRO('');
